(function () {
'use strict';

(function () {
  'use strict';

  const COLUMNS = [

    { key: 'kind',       tier: 'persist', sources: ['text'], required: true,
      desc: '身份：self/ally/enemy/summon/scene/field/zone' },
    { key: 'name',       tier: 'persist', sources: ['text'], required: true,
      desc: '名字（不含身份标签与等级）' },
    { key: 'level',      tier: 'persist', sources: ['text', 'mvu'], desc: '等级' },
    { key: 'rank',       tier: 'persist', sources: ['text'],
      desc: '职级：杂兵/精锐/首领/领主/传奇' },
    { key: 'tags',       tier: 'persist', sources: ['text'], merge: 'union',
      desc: '标签（种族/血统等），如「纯血金龙」' },
    { key: 'race',       tier: 'persist', sources: ['text', 'mvu'],
      desc: '种族' },

    { key: 'ac',         tier: 'persist', sources: ['text', 'mvu'], desc: '护甲等级' },
    { key: 'attrs',      tier: 'persist', sources: ['text', 'mvu'], merge: 'object',
      desc: '六维属性 {力量,敏捷,体质,智力,感知,魅力}' },
    { key: 'skills',     tier: 'persist', sources: ['text'], merge: 'union',
      desc: '技能列表 [{name, 倍率}]' },
    { key: 'weakness',   tier: 'persist', sources: ['text'], merge: 'union', desc: '弱点' },
    { key: 'resistance', tier: 'persist', sources: ['text'], merge: 'union', desc: '抗性' },
    { key: 'features',   tier: 'persist', sources: ['text'], merge: 'union', desc: '特征' },
    { key: 'attack',     tier: 'persist', sources: ['text'], desc: '基本攻击（原文，如 `64 × 4d10 + 624`）' },

    { key: 'combat',     tier: 'persist', sources: ['text'], merge: 'object',
      desc: '战斗属性 {暴击率, 暴击伤害, 暴击阈值, 物理减伤, 魔法减伤, 攻击次数}' },
    { key: 'equip',      tier: 'persist', sources: ['text'], merge: 'union',
      desc: '装备列表 [{name, slot, quality, 效果}]（名字+槽位+品质+效果）' },
    { key: 'threat',     tier: 'persist', sources: ['text'], desc: '威胁度' },

    { key: 'hp',         tier: 'turn', sources: ['text', 'mvu'], desc: '当前生命值' },
    { key: 'hpMax',      tier: 'turn', sources: ['text', 'mvu'], desc: '生命值上限' },
    { key: 'tempHp',     tier: 'turn', sources: ['text'], desc: '临时生命值' },

    { key: 'san',        tier: 'turn', sources: ['text', 'mvu'], allowNull: true,
      desc: '当前理智值（仅地海等有理智体系的世界观）' },
    { key: 'sanMax',     tier: 'turn', sources: ['text', 'mvu'], allowNull: true,
      desc: '理智值上限' },
    { key: 'distance',   tier: 'turn', sources: ['text'], unit: 'm',
      desc: '到主角的距离（米）——★ turn 档，每轮变' },

    { key: 'pairDist',   tier: 'turn', sources: ['text'], merge: 'byName',
      desc: '与其它单位的距离 [{name, m}]（任意两人；A↔B 两边各存一条）' },

    { key: 'terrain',    tier: 'turn', sources: ['text'],
      desc: '地形/高度类别：高地 / 洼地 / 平地（也可写「高台 4 米」这种原文）' },
    { key: 'pos',        tier: 'turn', sources: ['text'],
      desc: '动态坐标 {x,y,z}（用于算距离；y 是高度米）' },
    { key: 'mapPos',     tier: 'persist', sources: ['text'],
      desc: '静态坐标 {x,y,z}（只用于画布摆位，不参与距离）' },
    { key: 'acted',      tier: 'turn', sources: ['text'], desc: '本轮已行动（布尔）' },
    { key: 'pending',    tier: 'turn', sources: ['text'], desc: '本轮未行动（布尔）' },

    { key: 'posture',    tier: 'turn', sources: ['text'], unit: '%', optional: true,
      desc: '（个人设定，非体系固有）架势条百分比；应作为状态之一写，不要单列' },
    { key: 'surround',   tier: 'turn', sources: ['text'], desc: '周边描述（如「半身掩体（战壕 3 米）」）' },

    { key: 'statuses',   tier: 'fight', sources: ['text'], merge: 'byName',
      desc: '状态 [{name, 剩余回合|null}]（null = 永久/未标注）' },

    { key: 'duration',   tier: 'fight', sources: ['text'], unit: 'round', allowNull: true,
      panelOwned: true,
      desc: '场地/场景持续回合（null = 永久；只在首次写，之后由面板递减，续期写「N(刷新)」）' },
    { key: 'radius',     tier: 'fight', sources: ['text'], unit: 'm', desc: '作用范围（米）' },
    { key: 'center',     tier: 'fight', sources: ['text'], desc: '中心坐标 {x,y,z}' },
    { key: 'fieldType',  tier: 'fight', sources: ['text'], desc: '场地/场景类型' },
    { key: 'glyph',      tier: 'fight', sources: ['text'], desc: '图案（emoji）' },
    { key: 'height',     tier: 'fight', sources: ['text'], unit: 'm', desc: '高度' },
    { key: 'cover',      tier: 'fight', sources: ['text'], desc: '覆盖（全身/半身）' },

    { key: 'zone',       tier: 'fight', sources: ['text'], desc: '区块标记（是 = 这是区域不是实体）' },

    { key: 'shape',      tier: 'fight', sources: ['text'], desc: '图形（点/圈/矩形；空 = 圆形区域）' },

    { key: 'owner',      tier: 'fight', sources: ['text'], desc: '归属（player = 玩家画的，可删；空 = AI 布景）' },
    { key: 'effect',     tier: 'fight', sources: ['text'], desc: '效果描述' },

    { key: 'mapClass',   tier: 'fight', sources: ['text'],
      desc: '地图类别：效果/场景/建筑/道具（决定画法与可点性）' },

    { key: 'tint',       tier: 'fight', sources: ['text'], desc: '色调（场景用：沙漠/森林/雪原/沼泽…）' },

    { key: 'emojiFill',  tier: 'fight', sources: ['text'], desc: '场景内填充的 emoji（可多个）' },

    { key: 'note',       tier: 'fight', sources: ['text'], desc: '点击对象时显示的说明' },

    { key: 'lethal',     tier: 'fight', sources: ['text'], unit: 'm', desc: '杀伤范围（米，道具用）' },

    { key: 'fill',       tier: 'fight', sources: ['text'], desc: '是否填充（是/实心 = 填满；否/空心 = 只画轮廓）' },
    { key: 'spacing',    tier: 'fight', sources: ['text'], unit: 'm', desc: '点间距（米，越小越密；空 = 1 米）' },
    { key: 'vertices',   tier: 'fight', sources: ['text'], desc: '折线/多边形的顶点（x1,z1 x2,z2 …；空 = 用中心+范围推）' },

    { key: 'length',     tier: 'fight', sources: ['text'], unit: 'm', desc: '长度（米，线段/矩形用；空 = 用范围推）' },
    { key: 'angle',      tier: 'fight', sources: ['text'], unit: 'deg', desc: '角度（度，0 = 横向；线段/矩形旋转用）' },
  ];

  const COL_BY_KEY = {};
  COLUMNS.forEach((c) => { COL_BY_KEY[c.key] = c; });

  const FIELD_ALIAS_RAW = {

    kind: 'kind', 身份: 'kind', 类型: 'kind', 分类: 'kind',
    name: 'name', 名称: 'name', 名字: 'name', 姓名: 'name', 标记: 'name',
    level: 'level', 等级: 'level', lv: 'level',
    rank: 'rank', 职级: 'rank', 阶位: 'rank', 位阶: 'rank',
    tags: 'tags', 标签: 'tags',
    race: 'race', 种族: 'race', 血统: 'race',

    ac: 'ac', 护甲: 'ac', 护甲等级: 'ac', 防御: 'ac',
    attrs: 'attrs', 属性: 'attrs', 六维: 'attrs',
    skills: 'skills', 技能: 'skills',
    weakness: 'weakness', 弱点: 'weakness',
    resistance: 'resistance', 抗性: 'resistance',
    features: 'features', 特征: 'features', 特性: 'features',
    attack: 'attack', 基本攻击: 'attack', 攻击: 'attack',

    combat: 'combat', 战斗属性: 'combat',
    equip: 'equip', 装备: 'equip', 装备列表: 'equip',    threat: 'threat', 威胁度: 'threat', 威胁: 'threat',

    hp: 'hp', 当前hp: 'hp', 生命: 'hp', 当前生命: 'hp', 当前生命值: 'hp', 血量: 'hp',
    hpmax: 'hpMax', 生命上限: 'hpMax', 生命值上限: 'hpMax', 最大生命: 'hpMax', hp上限: 'hpMax',
    temphp: 'tempHp', 临时生命: 'tempHp', 临时生命值: 'tempHp', 护盾: 'tempHp',

    san: 'san', san值: 'san', 当前san: 'san', 当前理智: 'san', 理智: 'san', 理智值: 'san',
    sanmax: 'sanMax', san上限: 'sanMax', 理智上限: 'sanMax', 理智值上限: 'sanMax',
    最大理智: 'sanMax', 理智最大值: 'sanMax',
    distance: 'distance', 距离: 'distance', dist: 'distance', 相距: 'distance',

    pairdist: 'pairDist', 距离表: 'pairDist', 两两距离: 'pairDist', 相对距离: 'pairDist',
    单位距离: 'pairDist', 单位间距离: 'pairDist',

    terrain: 'terrain', 地形: 'terrain', 地势: 'terrain', 地势类别: 'terrain',
    高低: 'terrain', 高低差: 'terrain', 海拔: 'terrain', 地形高度: 'terrain',
    pos: 'pos', 坐标: 'pos', position: 'pos', 位置坐标: 'pos',
    mappos: 'mapPos',
    acted: 'acted', 已行动: 'acted', 本轮已行动: 'acted',
    pending: 'pending', 未行动: 'pending', 本轮未行动: 'pending',
    posture: 'posture', 架势: 'posture', 架势条: 'posture',
    surround: 'surround', 周边: 'surround', 环境: 'surround',

    statuses: 'statuses', 状态: 'statuses', 状态效果: 'statuses',
    duration: 'duration', 持续: 'duration', 持续时间: 'duration',
    radius: 'radius', 范围: 'radius', 半径: 'radius',
    center: 'center', 中心: 'center',
    fieldtype: 'fieldType', 场地类型: 'fieldType',
    glyph: 'glyph', 图案: 'glyph', 图标: 'glyph',
    height: 'height', 高度: 'height',
    cover: 'cover', 覆盖: 'cover',

    掩体: 'cover', 掩护: 'cover', 掩体情况: 'cover', 掩体覆盖: 'cover',
    shape: 'shape', 图形: 'shape', 形状: 'shape',

    fill: 'fill', 填充: 'fill', 实心: 'fill', 是否填充: 'fill', 空心: 'fill',
    spacing: 'spacing', 间距: 'spacing', 点间距: 'spacing', 密度: 'spacing',
    vertices: 'vertices', 顶点: 'vertices', 折线顶点: 'vertices',

    length: 'length', 长: 'length', 长度: 'length', len: 'length',
    angle: 'angle', 角: 'angle', 角度: 'angle', 旋转: 'angle', 旋转角: 'angle', rotate: 'angle',
    owner: 'owner', 归属: 'owner', 来源: 'owner',
    effect: 'effect', 效果: 'effect',

    zone: 'zone', 区块: 'zone', 区域: 'zone', 是否区块: 'zone',

    mapclass: 'mapClass', 地图类别: 'mapClass', 对象类别: 'mapClass',
    场景类别: 'mapClass', 地图分类: 'mapClass',
    tint: 'tint', 色调: 'tint', 颜色: 'tint', 色彩: 'tint',
    emojifill: 'emojiFill', 填充emoji: 'emojiFill', 填充表情: 'emojiFill',
    表情: 'emojiFill', 内部填充: 'emojiFill', 散布: 'emojiFill',
    note: 'note', 说明: 'note', 描述: 'note', 备注: 'note', 详情: 'note',
    lethal: 'lethal', 杀伤范围: 'lethal', 杀伤半径: 'lethal', 爆炸范围: 'lethal',
  };

  function normalizeFieldName(raw) {
    const s = String(raw == null ? '' : raw)
      .replace(/[\uFF01-\uFF5E]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
      .replace(/[\s_\-·・:：]/g, '')
      .toLowerCase();
    return FIELD_ALIAS_RAW[s] || '';
  }

  const FIELD_ALIAS = {};
  Object.keys(FIELD_ALIAS_RAW).forEach((k) => {
    const nk = k
      .replace(/[\uFF01-\uFF5E]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
      .replace(/[\s_\-·・:：]/g, '')
      .toLowerCase();
    FIELD_ALIAS[nk] = FIELD_ALIAS_RAW[k];
  });

  function normalizeName(raw) {
    return String(raw == null ? '' : raw)
      .replace(/[\uFF01-\uFF5E]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0))
      .replace(/^[\s「『【\[（(]+|[\s」』】\]）)]+$/g, '')
      .replace(/\s+/g, '')
      .trim();
  }

  function rowKey(row) {
    const kind = String((row && row.kind) || '');
    const name = normalizeName(row && row.name);
    const at = String((row && row.firstSeenAt) || '');
    return `${kind}::${name}::${at}`;
  }

  function posStamp(pos) {
    if (!pos || typeof pos !== 'object') return '';
    const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
    return `${n(pos.x)},${n(pos.y)},${n(pos.z)}`;
  }

  function describeForAI() {
    const byTier = { persist: [], fight: [], turn: [] };
    COLUMNS.forEach((c) => {
      if (!c.desc) return;

      if (c.optional === true) return;
      (byTier[c.tier] || byTier.turn).push(`  ${c.key} — ${c.desc}`);
    });
    return [
      '【战斗状态块 —— 面板自己维护战场数据，**你只需要写这一块**】',
      '',
      '<BattleState>',
      '轮次: 3',
      '场地:',
      '  名称: 布契古战壕 | 类型: 洼地 | 中心: 0,-1,5 | 范围: 8 | 持续: 3',
      '单位:',
      '  [自身] 拉缇娜 | HP 17/828 | 临时生命 737 | 距离 0 | 坐标 0,0,0 | 状态 懒惰领域(3)：行动迟缓；贪狼反击(2)：近战反伤 20%',      '  [敌方·Lv78·传奇] 阿洛兹 | HP 11253/16380 | 距离 3 | 坐标 10,0,0 | 状态 懒惰(3)：行动迟缓；苦痛印记(2)：受伤 +10%；破甲：AC-2',
      '场景:',
      '  标记: 坍塌的哨楼 | 类型: 建筑 | 中心: 6,0,12 | 图案: 🏚️ | 高度: 4',
      '  标记: 危险区 | 类型: 区域 | 区块: 是 | 中心: 0,0,5 | 范围: 6 | 持续: 3',,

      '距离表:',
      '  璐米欧儿→阿洛兹: 8',
      '  阿洛兹→矿洞守卫·斥候: 3',

      '本轮已行动: 拉缇娜 | 阿洛兹',
      '本轮未行动: 无',
      '</BattleState>',
      '',
      '🔴 上面这个块**原样照抄结构**，块内不要写注释（每个字都会被当成数据）。',
      '',
      '【单位行的写法（最要紧，位置不能乱）】',
      '  [身份] 名字 | HP 当前/上限 | 距离 N | 坐标 x,y,z | 状态 名字(剩余回合)：效果 …',
      '  · ★ **状态必须带效果**：`状态 破甲(2)：AC-2；护盾(3)：吸收 200`（`；` 分隔状态，效果里可含逗号）',
      '  · **只写新建或变化的状态**；没写效果 ⇒ 面板**沿用上一轮**那些状态的效果（不追问、不延误推进）',
      '  · 身份只能是：自身 / 队友 / 敌方 / 召唤物',
      '  · 敌方后面可以再跟 ·Lv78·传奇（等级与职级）',
      '  · 状态用**括号**写剩余回合；永久的**不写括号**',
      '  · HP 读不到就写 `--/--`（**不要写 0**）',

      '  · ★ **有理智值的世界观**（如「诡秘地海」）⇒ 单位行要带 `SAN 当前/上限`，',
      '    位置就在 HP 后面：`[自身] 拉缇娜 | HP 29/30 | SAN 48/49 | 距离 0 | 坐标 0,0,0`。',
      '    🔴 **只认 `<BattleState>` 里的这一份**：写在 `<CombatSnapshot>` 里的面板读不到。',
      '    SAN 读不到写 `--/--`（**不要写 0/0**，0 是「理智耗尽」，与「不知道」是两件事）。',
      '    没有理智体系的世界观就**不要写 SAN**。',
      '',
      '【持续回合由面板记账（最要紧的一条）】',
      '  · 你**只在它第一次出现**时写回合数：`中毒(3)` / `持续: 3`。',
      '  · 之后面板自己每轮递减，并把它当前的剩余值发给你 ⇒ **不要每轮重抄初始值**',
      '    （重抄会把账顶回去，效果就永远不消失了 —— 这是已经发生过的真机 bug）。',
      '  · 要**续期/重置** ⇒ 写 `中毒(3，刷新)` / `持续: 3(刷新)`。只有带「刷新」二字',
      '    面板才采纳你给的新回合数。',
      '  · 🔴 百分比**不是**回合数：`护盾(100%)` 会被读成「时长未标注」。限时的一律写回合。',
      '',
      '【三档数据（决定「你不写时面板会不会保留」）】',
      '  · 存档级（只需**首次**写一次，之后不写也一直在）：',
      ...byTier.persist,
      '  · 战斗级（战斗结束自动清空）：',
      ...byTier.fight,
      '  · 每回合（每轮都变，**要写就写最新的**）：',
      ...byTier.turn,
      '',
      '🔴 **你不写某一项 ⇒ 面板沿用上一轮的**（不是清空）。',
      '   所以你不必每轮重复写 AC、属性、弱点这些不变的东西。',
      '🔴 **不要写 `<json_patch>`** —— 面板不执行任何外部变量补丁，写了也会被忽略。',
    ].join('\n');
  }

  const Schema = {
    COLUMNS, COL_BY_KEY, FIELD_ALIAS, FIELD_ALIAS_RAW,
    normalizeFieldName, normalizeName, rowKey, posStamp, describeForAI,
  };

  if (typeof window !== 'undefined') window.__BE3_SCHEMA__ = Schema;
  if (typeof module !== 'undefined' && module.exports) module.exports = Schema;
})();

(function () {
  'use strict';

  const Schema = (typeof require === 'function' && typeof module !== 'undefined')
    ? require('./schema.js')
    : (typeof window !== 'undefined' ? window.__BE3_SCHEMA__ : null);

  const LOG_LIMIT = 500;

  const isObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
  const clone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
  const asText = (v) => (v === null || v === undefined ? '' : String(v));

  function pickBySource(col, candidates) {
    const srcs = Array.isArray(col && col.sources) ? col.sources : ['text'];
    const c = isObj(candidates) ? candidates : {};
    for (const s of srcs) {
      const v = c[s];

      if (v !== null && v !== undefined) return { value: v, source: s };
    }
    return { value: null, source: null };
  }

  function mergeValue(merge, oldV, newV) {
    if (oldV === undefined) return newV;
    if (newV === undefined) return oldV;
    switch (merge) {

      case 'union': {
        const a = Array.isArray(oldV) ? oldV : [];
        const b = Array.isArray(newV) ? newV : (newV === null || newV === undefined ? [] : [newV]);
        const out = a.slice();
        b.forEach((x) => {
          const xs = JSON.stringify(x);
          if (!out.some((y) => JSON.stringify(y) === xs)) out.push(x);
        });
        return out;
      }

      case 'object':
        return Object.assign({}, isObj(oldV) ? oldV : {}, isObj(newV) ? newV : {});

      case 'byName': {
        if (newV === undefined) return oldV;
        const a = Array.isArray(oldV) ? oldV.slice() : [];

        const b0 = Array.isArray(newV) ? newV : [];
        const b = b0.map((x) => {
          if (!isObj(x)) return x;

          const clean = Object.assign({}, x);
          delete clean.刷新;
          const nm = asText(clean && clean.name).trim();
          if (!nm) return clean;
          const oldOne = a.filter((y) => asText(y && y.name).trim() === nm)[0];
          if (!isObj(oldOne)) return clean;
          const merged = Object.assign({}, oldOne, clean);
          Object.keys(oldOne).forEach((k) => {
            const nv = clean[k];
            if (nv === null || nv === undefined || nv === '') merged[k] = oldOne[k];
          });

          if (x.刷新 !== true && oldOne.剩余回合 !== undefined) {
            merged.剩余回合 = oldOne.剩余回合;
          }
          return merged;
        });

        const out = b.slice();
        a.forEach((x) => {
          const nm = asText(x && x.name).trim();
          if (!nm) return;
          if (!out.some((y) => asText(y && y.name).trim() === nm)) out.push(x);
        });
        return out;
      }
      default:
        return newV;
