      if (next && typeof next === 'object') skills = JSON.parse(JSON.stringify(next));
      return getSkills();
    }

    function getCombo() { return combo ? JSON.parse(JSON.stringify(combo)) : null; }

    const Geo = (() => {
      try {
        return isRequire ? require('./geometry.js') : (window.__BE3_GEOMETRY__ || null);
      } catch (e) { return null; }
    })();

    function getCanvasView() { return Object.assign({}, canvasView); }

    function getCanvasAspect() { return canvasAspect; }
    function setCanvasAspect(a) {
      const n = Number(a);
      if (!Number.isFinite(n) || n < 1.2 || n > 8) return { changed: false, aspect: canvasAspect };
      if (Math.abs(n - canvasAspect) <= 0.01) return { changed: false, aspect: canvasAspect };
      canvasAspect = n;
      return { changed: true, aspect: canvasAspect };
    }

    function setCanvasView(patch) {
      const p = patch && typeof patch === 'object' ? patch : {};
      const next = Object.assign({}, canvasView);
      Object.keys(p).forEach((k) => {
        if (['zoom', 'panX', 'panY', 'iconScale', 'focus', 'namesOn', 'links', 'distOpen', 'distLine'].indexOf(k) >= 0) next[k] = p[k];
      });
      canvasView = Geo ? Geo.clampFieldView(next) : next;
      return Object.assign({}, canvasView);
    }

    function canvasAction(action, arg) {
      const a = asText(action);
      if (a === 'canvas-zoom-in' || a === 'canvas-zoom-out') {
        if (!Geo) return getCanvasView();
        canvasView = Geo.zoomFieldView(canvasView, a === 'canvas-zoom-in' ? 'in' : 'out');
        return getCanvasView();
      }
      if (a === 'canvas-reset') {
        canvasView = Geo
          ? Geo.resetFieldView(canvasView)
          : Object.assign({}, canvasView, { zoom: 1, panX: 0, panY: 0 });
        return getCanvasView();
      }
      if (a === 'canvas-icon-in' || a === 'canvas-icon-out') {
        const cur = Number(canvasView.iconScale) || 1;
        const step = Geo ? Geo.ICON_SCALE_STEP : 1.2;
        return setCanvasView({ iconScale: a === 'canvas-icon-in' ? cur * step : cur / step });
      }

      if (a === 'canvas-names') {
        return setCanvasView({ namesOn: canvasView.namesOn !== true });
      }
      if (a === 'canvas-links') {
        return setCanvasView({ links: canvasView.links !== true });
      }

      if (a === 'dist-toggle') {
        return setCanvasView({ distOpen: canvasView.distOpen !== true });
      }

      if (a === 'dist-line') {
        const side = asText(arg || canvasView.distLine);
        return setCanvasView({ distLine: canvasView.distLine === side ? '' : side });
      }
      if (a === 'focus-unit') {
        const nm = asText(arg);

        const next = canvasView.focus === nm ? '' : nm;
        const v = setCanvasView({ focus: next });

        if (uiState && typeof uiState.setFocusUnit === 'function') {
          try { uiState.setFocusUnit(next); } catch (e) {                     }
        }
        return v;
      }
      return getCanvasView();
    }

    function panCanvas(dx, dy) {
      if (!Geo) return getCanvasView();
      canvasView = Geo.panFieldView(canvasView, dx, dy);
      return getCanvasView();
    }

    let skillCfg = { mode: 'combo', custom: false, ultimateExitOnUse: true };
    function getSkillCfg() { return Object.assign({}, skillCfg); }
    function setSkillCfg(k, val) {
      const key = asText(k);
      if (key === 'mode') skillCfg.mode = (val === 'classic' ? 'classic' : 'combo');
      else if (key === 'custom') skillCfg.custom = val === true || val === 'true' || val === '1';
      else if (key === 'ultimateExitOnUse') skillCfg.ultimateExitOnUse = !(val === false || val === 'false' || val === '0');
      else return getSkillCfg();
      return getSkillCfg();
    }

    let mapSel = '';

    let measure = { mode: '', from: '', target: '' };

    function getMeasure() { return Object.assign({}, measure); }
    function clearMeasure() { measure = { mode: '', from: '', target: '' }; return getMeasure(); }

    function measureClick(name) {
      if (!Geo || typeof Geo.measureStep !== 'function') return { state: getMeasure(), rows: [] };
      const r = Geo.measureStep(Geo.buildMatrix(table.snapshot()), table.snapshot(), measure, name);
      measure = r.state;
      return r;
    }

    function measureInfo() {
      if (!Geo || typeof Geo.measureView !== 'function') return { mode: '', title: '', hint: '', rows: [] };
      const snap = table.snapshot();
      return Geo.measureView(Geo.buildMatrix(snap), snap, measure);
    }

    function getMapSel() { return mapSel; }

    function setMapSel(name) {
      const nm = asText(name).trim();
      mapSel = mapSel === nm ? '' : nm;
      return mapSel;
    }
    function clearMapSel() { mapSel = ''; return mapSel; }

    const CoordTable = (() => {
      try {
        return isRequire ? require('./coord-table.js') : (window.__BE3_COORDTABLE__ || null);
      } catch (e) { return null; }
    })();
    const coordTbl = CoordTable && CoordTable.createCoordTable ? CoordTable.createCoordTable() : null;

    function getMapOrigin() {
      if (!coordTbl) return null;
      const r = coordTbl.sync(table.snapshot());
      return r && r.origin ? r.origin : null;
    }

    function movePlayer(dx, dz) {
      if (!coordTbl) return { ok: false, reason: '坐标表未装配', moved: false, changes: [] };
      const snap = table.snapshot(); const r = coordTbl.moveSelf(dx, dz, snap);
      if (!r.ok) return r;
      if (r.ops && r.ops.length) {
        const res = table.apply(r.ops);
        if (res && res.rejected && res.rejected.length) {
          log('system', `⚠️ 移动后距离修正有 ${res.rejected.length} 条被拒：${res.rejected[0].reason}`);
        }
      }

      const adj = (r.changes || []).filter((c) => c.kind === 'adjusted'); const stale = (r.changes || []).filter((c) => c.kind === 'stale' || c.kind === 'unknown');
      if (adj.length) {
        log('system', `主角移动到 (${r.self.pos.x}, ${r.self.pos.z})，按几何推算修正 ${adj.length} 个距离：`
          + adj.map((c) => `${c.name} ${c.from}→${c.to}米`).join('、'));
      }
      if (stale.length) {
        log('system', `⚠️ 这些单位没有坐标或距离未知，**未修正**（不编数字）：${stale.map((c) => c.name).join('、')}`);
      }
      return { ok: true, reason: '', moved: true, changes: r.changes, self: r.self };
    }

    function getSlotPlan() {
      return Skills.planSlots({
        mode: skillCfg.mode,
        person: isObj(lastStatData) ? lastStatData.人物 : null,
        skills,
        combo,
        decorate: decorateSkill,
      });
    }

    function equipTierBucket() {
      if (!Inventory || !equipment) return {};
      const 装备列表 = {};
      (equipment.items || []).forEach((it) => {
        if (!it || !it.键名) return;
        装备列表[it.键名] = it;
      });
      const summary = Inventory.sumEquipBonuses(装备列表);
      return (summary && summary.阶位) || {};
    }

    function getSkillSlotsRaw() {
      const st = isObj(lastStatData) ? lastStatData : {}, p = isObj(st.人物) ? st.人物 : {}, awk = isObj(p.觉醒技能槽) ? p.觉醒技能槽 : {};
      return { slots: Object.assign({}, awk, isObj(p.主动技能槽) ? p.主动技能槽 : {}), 觉醒: awk,
        系统配置: isObj(st.系统配置) ? st.系统配置 : {}, 来源: isObj(lastStatData) ? 'stat_data' : 'none' };
    }

    function decorateSkill(name) {
      const sk = skills[name] || {};
      const cd = Number(sk.冷却计数) || 0;

      const lv = Skills.effectiveLevel
        ? Skills.effectiveLevel(sk, equipTierBucket())
        : { 有效等级: Number(sk.当前等级) || 0, 裸等级: Number(sk.当前等级) || 0, 加成: 0, 封顶: false };
      return {
        name,
        阶位: sk.阶位 || '',
        当前等级: Number(sk.当前等级) || 0,
        有效等级: lv.有效等级,
        等级加成: lv.加成,
        等级封顶: lv.封顶,
        冷却计数: cd,
        cooling: sk.冷却中 === true || cd > 0,
        usedThisRound: usedThisRound.indexOf(name) >= 0,
      };
    }

    function useSkill(name) {
      const nm = asText(name).trim();
      if (!nm) return { ok: false, reason: 'empty' };
      if (!skills[nm]) return { ok: false, reason: 'not_found', name: nm };
      const sk = skills[nm];
      const cd = Number(sk.冷却计数) || 0;
      if (cd > 0 || sk.冷却中 === true) {
        return { ok: false, reason: 'cooling', name: nm, cd };
      }
      if (usedThisRound.indexOf(nm) >= 0) return { ok: false, reason: 'duplicate', name: nm };
      usedThisRound.push(nm);
      log('skill', `记录使用【${nm}】（推进时结算冷却）`);
      return { ok: true, name: nm, used: usedThisRound.slice() };
    }

    function unuseSkill(name) {
      const nm = asText(name).trim();
      const i = usedThisRound.indexOf(nm);
      if (i < 0) return false;
      usedThisRound.splice(i, 1);
      log('skill', `撤销【${nm}】`);
      return true;
    }

    function getUsed() { return usedThisRound.slice(); }
    function getUsedResources() { return usedResources.slice(); }

    function getAwakening() {
      if (!Skills.awakeningList) return [];
      return Skills.awakeningList(skills, equipTierBucket()).map((x) => Object.assign({}, x, {
        usedThisRound: usedThisRound.indexOf(x.name) >= 0,
      }));
    }

    function resetComboOnBegin() {
      if (!combo) return;
      const r = Skills.resetOnBattleEntry(combo, { mode: 'combo' });
      combo = r.combo;
    }

    function submitReply(text, env) {
      const e = env || {};
      const src = asText(text);
      if (!src.trim()) return { ok: false, reason: '正文为空', snapshot: table.snapshot(), log: [] };

      const cls = Narrative && Narrative.classifyReply
        ? Narrative.classifyReply(src)
        : { segments: [], mode: 'empty' };

      const cotText = Narrative && Narrative.mergeCot ? Narrative.mergeCot(e.reasoning, cls && cls.cot) : asText(cls && cls.cot);
      const narrText = cls.segments
        .filter((s) => s.kind === 'narrative')
        .map((s) => Narrative.stripMark(s.text))
        .join('\n');
      const dup = (fingerprint(src) === lastFp);

      if (!dup && Narrative && Narrative.archiveLogEntries) {
        Narrative.archiveLogEntries(src, { cot: cotText }, table.getRound())
          .forEach((e2) => log(e2.kind, e2.text, { round: e2.round, chars: e2.chars }));
      }

      let parsed;
      try { parsed = Parser.parseReply(src); } catch (err) {
        log('system', `解析失败：${err && err.message ? err.message : err}`);

        logSegments(cls, dup);
        return { ok: false, reason: 'parse_failed', snapshot: table.snapshot(), log: [] };
      }

      const aiRound = parsed.round; const myRound = table.getRound();
      if (aiRound !== null && aiRound !== myRound + 1 && aiRound !== myRound) {
        log('system', `⚠️ AI 说这是「第 ${aiRound} 轮」，而面板当前是「第 ${myRound} 轮」`
          + '（轮次由面板推进，AI 说的只作参考，不会让面板跳回合）');
      }

      parsed.warnings.forEach((w) => {
        if (w.kind === 'json_patch_ignored') {
          log('system', `AI 写了 ${w.count} 个 <json_patch>，面板自持数据 ⇒ 已忽略（不执行、不入表）`);
        } else if (w.kind === 'kind_assumed') {
          log('system', `「${w.name}」没有标身份，按**敌方**处理（请让 AI 写 [自身]/[队友]/[敌方]）`);
        }
      });

      const res = table.apply(parsed.ops);
      res.rejected.forEach((r) => log('system', `拒绝一条变更：${r.reason}`));
      if (res.applied) log('system', `已更新战场数据（${res.applied} 处）`);

      const roundNow = table.getRound();

      const fp = fingerprint(src);
      const decision = AiControl.decideAdvance(parsed, {
        auto: e.auto !== false,
        fp,
        lastFp,
        inBattle: table.isInBattle(),
        busy,
        hasState: parsed.hasBlock.state === true,

        consecutiveVeto: vetoStreak,
      });

      if (decision.act === 'advance') vetoStreak = 0;
      else if (parsed.hasBlock.state === true) vetoStreak += 1;
      let advanced = null;
      if (decision.act === 'advance') {

        let logged = false;
        advanced = advance({
          reason: decision.reason,
          narrative: narrText,
          beforePushLog: (roundAfter) => {
            logged = true;
            logSegments(cls, dup, roundAfter);
          },
        });
        if (!logged) logSegments(cls, dup);
      } else {

        logSegments(cls, dup); log('system', `回合控制：${decision.reason}`);
      }

      lastFp = fp;

      return {
        ok: true,
        snapshot: table.snapshot(),
        applied: res.applied,
        rejected: res.rejected,
        decision,
        advanced,
        log: logs.slice(-12),
      };
    }

    function advance(opts) {
      const p = opts || {};
      if (busy) return { ok: false, reason: '上一次推进还没结束（在途锁）' };
      busy = true;
      try {
        const before = table.snapshot();

        const useSkills = p.skills || skills;

        const used = Array.isArray(p.usedSkills) ? p.usedSkills : usedThisRound;

        const delta = Math.max(1, Math.min(20, Math.floor(Number(p.delta) || 1)));

        const ad = Turn.advanceTurn(before, {
          skills: useSkills,
          usedSkills: used,
          combo,

        mode: p.mode || skillCfg.mode || (combo ? 'combo' : 'classic'),
          valueMode: p.valueMode,
          inBattle: table.isInBattle(),
          ultimateExitOnUse: p.ultimateExitOnUse !== undefined ? p.ultimateExitOnUse : skillCfg.ultimateExitOnUse,
          delta,
        });
        const r = table.apply(ad.ops);

        if (ad.skills) skills = ad.skills;
        if (ad.combo) combo = ad.combo;

        let resourceEffects = null;
        if (Array.isArray(resources) && resources.length) {
          const rr = Turn.applyResourceUsage(resources, usedResources, 1);
          if (rr.used.length) {
            resources = rr.resources;
            resourceEffects = rr;
            rr.used.forEach((x) => {
              log('resource', `资源【${x.name}】次数 ${x.from} → ${x.to}`);
            });
          }
          rr.skipped.forEach((x) => {
            const why = x.reason === 'exhausted' ? '已经耗尽'
              : x.reason === 'duplicate' ? '本回合重复记录（只扣一次）'
                : x.reason === 'not_found' ? '列表里没有它' : x.reason;
            log('system', `资源【${x.name}】未扣次数：${why}`);
          });
        }

        usedThisRound = [];
        usedResources = [];

        if (ad.skills || ad.comboChanged) {
          const cdApplied = (ad.effects.ticked || []).filter((x) => x.cooling);
          if (cdApplied.length) {
            log('skill', `进入冷却：${cdApplied.map((x) => `${x.skill}(${x.cd})`).join('、')}`);
          }
          const skipped = (ad.effects.warned || []);
          skipped.forEach((x) => {
            const why = x.reason === 'cooling' ? '冷却中'
              : x.reason === 'unknown_tier' ? '阶位认不出（未进冷却）'
                : x.reason === 'not_found' ? '技能表里没有'
                  : x.reason;
            log('system', `本轮【${x.skill}】未进冷却：${why}`);
          });

        if (ad.effects.comboWhy && Skills && typeof Skills.explainCombo === 'function') {
          log('skill', Skills.explainCombo(ad.effects.comboWhy));
        }
      }

        ad.effects.expired.forEach((x) => {
          if (x.status) log('system', `「${x.unit}」的状态【${x.status}】到期`);
          if (x.field) log('system', `场地【${x.field}】持续时间结束`);
        });
        ad.effects.ticked.filter((x) => x.unit || x.field).forEach((x) => {
          if (x.unit) log('system', `「${x.unit}」的【${x.status}】剩余 ${x.from} → ${x.to} 回合`);
          else if (x.field) log('system', `场地【${x.field}】持续 ${x.from} → ${x.to} 回合`);
        });

        if (typeof p.beforePushLog === 'function') {
          try { p.beforePushLog(ad.nextRound); } catch (e) {                 }
        }

        store.push(table.exportState(), {
          narrative: p.narrative || '',
          usedSkills: used,
          label: delta === 1 ? `推进到第 ${ad.nextRound} 轮` : `推进 ${delta} 轮 → 第 ${ad.nextRound} 轮`,
          skills,
          combo,

          bag: bagSession ? bagSession.exportState() : null,
          resources,

          equipment: equipSession ? equipSession.exportState() : null,

          logs: logs.slice(),
        });
        log('system', `回合推进 → 第 ${table.getRound()} 轮`
          + (delta > 1 ? `（一次推 ${delta} 轮）` : '')
          + (p.reason ? `（${p.reason}）` : '')
          + (r.rejected.length ? `；⚠️ ${r.rejected.length} 条变更被拒绝` : ''));
        return {
          ok: true, round: table.getRound(), delta, effects: ad.effects,
          resourceEffects, snapshot: table.snapshot(),
        };
      } finally {
        busy = false;
      }
    }

    function restoreFrom(result) {
      if (!result) return null;
      table.importState(result.snapshot);
      if (Object.prototype.hasOwnProperty.call(result, 'skills')) skills = JSON.parse(JSON.stringify(result.skills || {}));
      if (Object.prototype.hasOwnProperty.call(result, 'combo')) combo = result.combo ? JSON.parse(JSON.stringify(result.combo)) : combo;

      if (Object.prototype.hasOwnProperty.call(result, 'bag') && result.bag && bagSession) {
        bagSession.importState(result.bag);
      }
      if (Object.prototype.hasOwnProperty.call(result, 'resources') && Array.isArray(result.resources)) {
        resources = JSON.parse(JSON.stringify(result.resources));
      }

      if (Object.prototype.hasOwnProperty.call(result, 'equipment') && result.equipment && equipSession) {
        equipSession.importState(result.equipment);
      }

      if (Object.prototype.hasOwnProperty.call(result, 'logs') && Array.isArray(result.logs)) {
        logs = result.logs.slice();
      }

      usedThisRound = [];
      usedResources = [];

      lastFp = '';
      return table.snapshot();
    }

    function undo() {
      const r = store.prev();
      if (!r) { log('system', '没有上一回合可退（已经是最早的一轮，或还没推进过）'); return null; }
      const snap = restoreFrom(r);

      log('system', `已回退到第 ${r.meta.round} 轮`);
      return snap;
    }

    function redo() {
      const r = store.next();
      if (!r) { log('system', '没有可以重放的下一回合 —— 请用【推进回合】重新推演'); return null; }
      const snap = restoreFrom(r);

      log('system', `已重放到第 ${r.meta.round} 轮`);
      return snap;
    }

    function snapshot() { return table.snapshot(); }
    function getLog() { return logs.slice(); }
    function clearLog() { logs = []; }
    function rounds() { return store.list(); }

    function beginBattle() {
      table.apply(Turn.beginBattleOps());
      resetComboOnBegin();
      log('system', '进入战斗（面板接管战场数据；连击重置为 alpha/advanced）');
      return table.snapshot();
    }

    function endBattle(opts) {
      const o = opts || {};
      table.apply(Turn.endBattleOps());

      if (combo) { combo.当前显示槽 = 'advanced'; combo.当前高级组 = 'alpha'; }
      let cleared = [];
      if (o.clearCooldowns === true && Skills.resetCooldowns) {
        const r = Skills.resetCooldowns(skills);
        skills = r.skillMap;
        cleared = r.cleared;
        if (cleared.length) log('skill', `战斗结束 ⇒ 清空 ${cleared.length} 个技能的冷却（已被显式开启）`);
      }
      log('system', '战斗结束：状态与场地已清理，存档级数据（AC/属性/弱点）保留'
        + (o.clearCooldowns === true ? '；技能冷却已清空' : '；技能冷却保留（存档数据）'));
      return table.snapshot();
    }

    function clearAll() {
      table.importState({ v: 1, round: 0, inBattle: false, rows: [] });
      store.clear();
      lastFp = '';

      logs = [];
      log('system', '【清空面板】已清空战场数据与回合日志（技能/背包等存档数据不受影响）');
      return table.snapshot();
    }

    function buildSettleReport(opts) {
      const o = (opts && typeof opts === 'object') ? opts : {};
      const empty = {
        ok: false, reason: '', text: '', sections: [], narrativeCount: 0,
        chars: 0, truncated: false, dropped: 0, round: table.getRound(), fromRound: null,
      };
      if (!Narrative || !Narrative.buildSettleText) {
        return Object.assign({}, empty, { reason: 'no_narrative_module' });
      }
      if (!Describe || !Describe.describeUnits) {
        return Object.assign({}, empty, { reason: 'no_describe_module' });
      }

      const snap = api.snapshot();
      const units = Describe.describeUnits(snap);

      if (!asText(units).trim()) return Object.assign({}, empty, { reason: 'no_units' });

      const narratives = Narrative.pickNarratives(api.getLog());
      const withRound = narratives.filter((n) => n.round !== null);
      const fromRound = withRound.length ? Math.min(...withRound.map((n) => n.round)) : null;

      const roundNow = Number.isFinite(Number(snap.round)) ? Number(snap.round) : table.getRound();
      const st = Narrative.buildSettleText({
        round: roundNow,
        fromRound,
        units,
        fields: Describe.describeFields(snap),
        scenes: Describe.describeScenes(snap),
        narratives,
        maxChars: o.maxChars,
      });
      return Object.assign({ ok: true, reason: '' }, st);
    }

    function advanceN(n, opts) {
      const delta = Math.floor(Number(n));
      if (!Number.isFinite(delta) || delta < 1) {
        return { ok: false, reason: `推进回合数非法：${n}（必须是 ≥1 的整数）` };
      }
      return advance(Object.assign({}, opts || {}, { delta }));
    }

    const api = {

      submitReply, advance, advanceN, undo, redo,
      importSave, getSkills, setSkills,

      getSkillBook, getReferenceRaw, getSkillSlotsRaw,
      getCombo, getSlotPlan, useSkill, unuseSkill, getUsed, getAwakening,
      beginBattle, endBattle, clearAll,
      snapshot, getLog, clearLog, rounds,

      addLog, buildSettleReport, getLogFilter, setLogFilter,

      getBag, getBagView, setBagView, dropItem, moveItem,
      getBagExpanded, toggleBagDetail, getBagPage, setBagPage,
      getEquipment, getResources, useResource, unuseResource, getUsedResources,

      getBagSelection, setBagSelection, clearBagSelection,
      dropItems, moveItems,

      getReference, getRefSelected, toggleRef, setRefAll, getRefNearOnly, setRefNearOnly,

      getCollapsed, toggleSection, getShowSettings, toggleSettings,
      getFocusUnit, setFocusUnit,

      getCfgPage, setCfgPage, forceCfgPage,

      bindWbView, setWbView,

