    return { ok: true, preset: p, count: p.items.length, reason: '' };
  }

  function exportFileName(now) {
    const d = now instanceof Date && !isNaN(now.getTime()) ? now : new Date(0);
    const p2 = (n) => String(n).padStart(2, '0');
    return `be3-preset-${d.getFullYear()}${p2(d.getMonth() + 1)}${p2(d.getDate())}-${p2(d.getHours())}${p2(d.getMinutes())}.json`;
  }

  function serializeExport(preset) {
    const items = normalizePreset(preset).items.map((x) => ({
      id: x.id, name: x.name, source: x.source, role: x.role, enabled: x.enabled, content: x.content,
    }));
    return JSON.stringify({ format: 'be3-preset', version: 1, items }, null, 2);
  }

  function serializeExportText(preset) {
    return normalizePreset(preset).items.map((x) => {
      const head = `#### ${x.enabled ? '' : '[停用] '}${x.name}`;

      const meta = `role:${x.role}${x.binding && x.binding !== 'literal' ? ` | binding:${x.binding}` : ''}`;
      return `${head}\n${meta}\n${x.content}`;
    }).join('\n\n');
  }

  let lastHistoryHandled = false;
  let lastHistoryCount = 0;

  function buildParts(preset, src) {
    const s = isObj(src) ? src : {};

    const firstText = (...vals) => {
      for (let i = 0; i < vals.length; i++) {
        const t = asText(vals[i]);
        if (t.trim()) return t;
      }
      return '';
    };
    const pick = (source, content) => {
      if (source === 'worldbook') return { kind: 'worldbook', text: firstText(s.worldbookText, s.worldbook) };

      if (source === 'contract') return { kind: 'panel', text: firstText(s.contract, s.contractText) };
      if (source === 'brief') return { kind: 'panel', text: firstText(s.brief, s.briefText) };
      if (source === 'user_input') return { kind: 'user_input', text: firstText(s.userInput, s.input) };
      if (source === 'history') return { kind: 'history', text: firstText(s.historyText, s.history) };
      return { kind: 'panel', text: asText(content) };
    };

    const byIdent = (() => {
      if (!Array.isArray(s.playerPreset)) return null;
      const m = {};
      s.playerPreset.forEach((x) => {
        const k = isObj(x) ? asText(x.identifier) : '';
        if (k) m[k] = x;
      });
      return m;
    })();
    const out = [];

    const histMsgs = Array.isArray(s.historySlot)
      ? s.historySlot.filter((m) => isObj(m) && ['user', 'assistant', 'system'].indexOf(asText(m.role)) >= 0
        && asText(m.content).trim())
      : [];
    let histUsedInSlot = false;
    normalizePreset(preset).items.forEach((it) => {
      if (it.enabled !== true) return;

      let content = it.content;
      let kind = null;
      if (it.binding === 'entry' && it.identifier) {
        const hit = byIdent ? byIdent[it.identifier] : null;
        if (hit && hit.marker !== true) {
          content = asText(hit.content);

          kind = 'preset';
          if (hit.enabled !== true) return;
        }
      }

      if (it.source === 'history' && histMsgs.length) {
        histUsedInSlot = true;

        const merged = histMsgs.map((m) => `[${asText(m.role)}] ${asText(m.content)}`).join('\n');
        const combined = firstText(s.historyText, s.history);
        const head = combined ? resolveVars(combined, s.vars) : '';
        if (head.trim()) out.push({ kind: 'history', role: it.role, content: head });
        histMsgs.forEach((m) => {
          const o = { kind: 'history', role: asText(m.role), content: asText(m.content) };
          if (Number.isFinite(Number(m.depth))) o.depth = Number(m.depth);
          out.push(o);
        });
        void merged;
        return;
      }
      const r = pick(it.source, content);

      const text = isObj(s.vars) && Object.keys(s.vars).length
        ? resolveVars(r.text, s.vars) : r.text;

      if (!text.trim()) return;
      out.push({ kind: kind || r.kind, role: it.role, content: text });
    });

    const histNote = asText(s.historyNote);

    if (false && histMsgs.length && histNote && !histUsedInSlot) {
      const at = (() => {
        for (let i = out.length - 1; i >= 0; i--) if (out[i].kind === 'user_input') return i;
        return out.length;
      })();
      out.splice(at, 0, { kind: 'panel', role: 'system', content: histNote });
    }

    {
      const histParts = out.filter((x) => x.kind === 'history');
      if (histParts.length) {
        for (let i = out.length - 1; i >= 0; i--) if (out[i].kind === 'history') out.splice(i, 1);
        const uiAt = (() => {
          for (let i = out.length - 1; i >= 0; i--) if (out[i].kind === 'user_input') return i;
          return out.length;
        })();
        out.splice.apply(out, [uiAt, 0].concat(histParts));
      }
    }

    lastHistoryHandled = histMsgs.length > 0;
    lastHistoryCount = histMsgs.length;
    return out;
  }

  function __lastHistoryHandled() { return lastHistoryHandled; }
  function __lastHistoryCount() { return lastHistoryCount; }

  function resolveVars(text, map) {
    const src = asText(text);
    const m = isObj(map) ? map : {};
    if (!src || !src.indexOf('{{')) return src;
    return src.replace(/\{\{\s*getvar\s*::([A-Za-z0-9_\u4e00-\u9fa5]+)\s*\}\}/g, (whole, key) => {
      const k = asText(key).trim();
      return Object.prototype.hasOwnProperty.call(m, k) ? asText(m[k]) : whole;
    });
  }

  const Api = {
    overlayHeight,
    defaultPreset, normalizePreset, normalizeItem, itemsOf, SOURCES, ROLES,
    nextId, applyPresetOp,
    parseImport, serializeExport, serializeExportText, exportFileName,
    buildParts, resolveVars,

    __lastHistoryHandled, __lastHistoryCount,
  };
  if (typeof window !== 'undefined') window.__BE3_CFGBIG__ = Api;
  if (typeof module !== 'undefined' && module.exports) module.exports = Api;
})();

