  function diffDefaults(items) {
    const list = Array.isArray(items) ? items : [];
    const has = new Set(list.map((x) => str(x.id)));
    const missing = SLOTS.map((s) => s.id).filter((id) => !has.has(id))

      .concat(['wb', 'contract', 'brief', 'action'].filter((id) => !has.has(id)));
    const known = new Set(SLOTS.map((s) => s.id).concat(['wb', 'contract', 'brief', 'action']));
    const extra = list.filter((x) => x.group === 'battle' && !known.has(str(x.id))).map((x) => str(x.id));
    return { missing, extra };
  }

  function fillDefaults(items) {
    const list = (Array.isArray(items) ? items : []).map((x, i) => normalizeItem(x, i));
    const d = diffDefaults(list);
    const all = defaultBattlePreset().items.map((x, i) => normalizeItem(x, i, 'battle'));
    const byId = {};
    all.forEach((x) => { byId[x.id] = x; });

    const upgraded = [];
    const stale = [];
    const next = list.map((x) => {
      if (!x || x.binding !== 'literal') return x;
      const fresh = byId[x.id];
      if (!isObj(fresh)) return x;
      const cur = str(x.content);
      const want = str(fresh.content);
      if (cur === want) return x;

      const histList = Array.isArray(LEGACY_LITERAL_TEXT[x.id]) ? LEGACY_LITERAL_TEXT[x.id] : [];
      const untouched = cur.trim() === '' || histList.indexOf(cur) >= 0;
      if (!untouched) { stale.push(x.id); return x; }
      upgraded.push(x.id);
      return Object.assign({}, x, { content: want });
    });

    const d2 = diffDefaults(next);
    if (!d2.missing.length) return { items: next, added: 0, updated: upgraded, stale };
    const add = d2.missing.map((id) => byId[id]).filter(isObj);

    let at = 0;
    next.forEach((x, i) => { if (x.group === 'battle') at = i + 1; });
    const out = next.slice(0, at).concat(add, next.slice(at));
    return { items: out, added: add.length, updated: upgraded, stale };
  }

  const Api = {
    LABEL, GROUPS, SLOTS, MARKERS,
    panelSlot, literalSlot, defaultBattlePreset,
    parseStPreset, mergePlayerCopy,
    normalizeItem, normalize, splitGroups,
    collectSetvars, resolveVarBus, stripVarItems,
