    const tf = traitList.map((x) => {
      if (typeof x === 'string') return x.trim();
      if (!isObj(x)) return asText(x).trim();
      let nm = asText(x.name || x.名称 || x.名).trim();
      let body = asText(x.描述 || x.效果 || x.说明).trim();
      const tags = arr(x.标签).map((t) => (typeof t === 'string'
        ? t.trim() : asText(isObj(t) ? (t.name || t.名称) : t).trim())).filter(Boolean);
      if (!nm && !body) {
        const keys = Object.keys(x);
        if (keys.length === 1 && isObj(x[keys[0]])) {
          nm = keys[0];
          body = asText(x[keys[0]].描述 || x[keys[0]].效果 || x[keys[0]].说明).trim();
        } else if (keys.length === 1) {
          nm = keys[0];
          body = asText(x[keys[0]]).trim();
        }
      }
      const bits = [nm];
      if (tags.length) bits.push('[' + tags.join('/') + ']');
      const head = bits.filter(Boolean).join(' ');
      if (!head && !body) return '';
      return body ? (head || '（无名特质）') + '：' + body : head;
    }).filter(Boolean);
    if (tf.length) L.push('  特质：' + tf.join(' · '));

    if (isObj(s.sanity) && s.sanity.known === true && nOf(s.sanity.max) !== null) {
      const cur = nOf(s.sanity.cur);
      L.push(`  SAN：${cur === null ? '?' : cur}/${nOf(s.sanity.max)}（理智值 / 理智值上限）`);
    }

    if (s.expMax === true) {
      L.push('  经验：已满级（Lv.100）');
    } else if (nOf(s.expLevelNeed) !== null && Number(s.expLevelNeed) > 0) {
      const lvExp = nOf(s.expLevel);
      L.push(`  经验：本级 ${lvExp === null ? '?' : lvExp}/${nOf(s.expLevelNeed)}`
        + `（${pct(s.expPct)}；累计 ${asText(s.exp)}/${asText(s.expNext)}）`);
    }

    return L.join('\n');
  }

  function pickSpecialEffect(effect, lv) {
    const L = Math.max(1, Math.floor(Number(lv) || 1));
    if (!effect) return null;
    if (typeof effect === 'string') {
      const t = effect.trim();
      return t ? { key: String(L), value: t } : null;
    }
    if (!isObj(effect)) return null;
    const exact = effect[String(L)];
    if (typeof exact === 'string' && exact.trim()) return { key: String(L), value: exact };

    const nums = Object.keys(effect).map((k) => Number(k)).filter((k) => Number.isFinite(k)).sort((a, b) => a - b);
    const le = nums.filter((k) => k <= L);
    if (le.length) {
      const k = String(le[le.length - 1]);
      const v = effect[k];
      if (typeof v === 'string' && v.trim()) return { key: k, value: v };
    }
    if (typeof effect['无'] === 'string' && effect['无'].trim()) return { key: '无', value: effect['无'] };

    const keys = Object.keys(effect).filter((k) => typeof effect[k] === 'string' && effect[k].trim());
    if (keys.length) return { key: keys[0], value: effect[keys[0]] };
    return null;
  }

  function skillEffectText(raw, lv) {
    const r = isObj(raw) ? raw : {};
    const eff = pickSpecialEffect(r.特殊效果, lv);
    if (eff && eff.value.trim()) return { text: eff.value.trim(), from: '特殊效果', key: eff.key };
    const alt = pickSpecialEffect(r.效果, lv);
    if (alt && alt.value.trim()) return { text: alt.value.trim(), from: '效果', key: alt.key };

    const others = ['效果说明', '详细效果', '技能效果'];
    for (let k = 0; k < others.length; k++) {
      const v = r[others[k]];
      if (typeof v === 'string' && v.trim()) return { text: v.trim(), from: others[k], key: '' };
    }
    const desc = asText(r.描述).trim();
    if (desc) return { text: desc, from: '描述', key: '', briefOnly: true };
    return { text: '', from: '', key: '' };
  }

  function SKN() {
    try {
      if (typeof globalThis !== 'undefined' && globalThis.__BE3_SKILLNUMS__) return globalThis.__BE3_SKILLNUMS__;
      if (typeof require === 'function') return require('./skillnums.js');
    } catch (e) {                    }
    return null;
  }

  function rateTextOf(raw, tree, lv, tier, extra) {
    const S = SKN();
    const x = isObj(extra) ? extra : {};
    if (!S) {

      const r = isObj(raw) ? raw : {};
      const v = nOf(r.伤害倍率) !== null ? nOf(r.伤害倍率) : nOf(r.倍率);
      return (v === null || v <= 0) ? '倍率未记录' : `倍率 ${v}%`;
    }

    return S.rateText({ raw, tree, slot: x.slot, level: lv, tier, mode: x.mode, includeRef: x.includeRef === true });
  }

  function rateLineOf(raw, tree, lv, tier, extra) {
    const S = SKN();
    const x = isObj(extra) ? extra : {};
    if (!S) return rateTextOf(raw, tree, lv, tier, extra);
    return S.rateLine({ raw, tree, slot: x.slot, level: lv, tier, mode: x.mode });
  }

  const EXTRA_NUM_KEYS = ['消耗', '消耗资源', 'MP', 'SP', '范围', '作用范围', '射程',
    '判定', '命中判定', '检定', '持续', '持续回合', '持续轮数', '冷却回合', '层数', '上限', '目标'];

  function tierBonusBucket(equipList) {
    const S = SKN();
    if (S) return S.tierBonusBucket(equipList);
    return {};
  }

  function effLevelOf(raw, bucket, tierOverride) {
    const S = SKN();
    if (S) return S.effLevelOf(raw, bucket, tierOverride);
    const r = isObj(raw) ? raw : {};
    const base = nOf(r.当前等级) === null ? 0 : Number(r.当前等级);
    return { level: Math.max(base, 0), base, bonus: 0, capped: false };
