  function skillsBlock(x) {
    const o = isObj(x) ? x : {};
    const book = isObj(o.slots) ? o.slots : {};
    const combo = isObj(o.combo) ? o.combo : {};
    const used = arr(o.used).map((s) => asText(s).trim()).filter(Boolean);
    const cfg = isObj(o.skillCfg) ? o.skillCfg : {};

    const bucket = tierBonusBucket(o.equipList);

