    })();
    const L = [];
    let total = 0;
    let empty = 0;

    const slotRow = (nameOrObj, slotLike, curMark) => {

      const slot = isObj(nameOrObj) ? nameOrObj
        : (isObj(slotLike) ? slotLike : (slotByName[asText(nameOrObj).trim()] || null));
      const nm = asText(isObj(nameOrObj) ? nameOrObj.name : nameOrObj).trim();
      if (!nm) { empty++; return '    · （空槽）'; }
      total++;
      const entry = isObj(book[nm]) ? book[nm] : {};

      const raw = (() => {
        const base = (() => {
          if (!isObj(entry.raw)) return Object.assign({}, entry);
          const out = Object.assign({}, entry.raw);
          Object.keys(entry).forEach((k) => {
