      const slotLv = nOf(slot && slot.技能等级);
      const slotBonus = nOf(slot && slot.等级加成);
      const cand = [own.level, slotEff, slotLv].filter((v) => v !== null && v !== undefined && v > 0);
      const lv = cand.length ? Math.max.apply(null, cand) : 1;

      const bonus = Math.max(own.bonus || 0, slotBonus === null ? 0 : slotBonus);
      const head = [nm];

      const baseLv = own.base > 0 ? own.base : nOf(raw.当前等级);
      const bonusTxt = bonus > 0 ? '（裸 ' + baseLv + '+装备 ' + bonus + '）'
