      if (rateLn && rateLn.text) head.push(rateLn.text);
      const cd = nOf(slot && slot.冷却计数) !== null ? nOf(slot.冷却计数) : nOf(entry.冷却计数);
      const cooling = (slot && slot.cooling === true) || entry.冷却中 === true || (cd !== null && cd > 0);
      if (cooling) head.push(cd !== null ? '冷却中（剩 ' + cd + ' 回合）' : '冷却中');
      if (used.indexOf(nm) >= 0) head.push('本回合已用');
      const lines = ['    · ' + head.join(' · ')];

      const ef = skillEffectText(raw, lv);
      if (ef.text) {
        const tag = ef.briefOnly
          ? '（⚠️ 存档里没有【特殊效果】，下面是**简介**，不能用来判定）'
