      } else {
        lines.push('      特殊效果：（存档里没有这一条的【特殊效果】）');
      }

      const extras = [];
      EXTRA_NUM_KEYS.forEach((k) => {
        const v = raw[k];
        if (v === null || v === undefined || v === '') return;
        if (isObj(v)) {
          const t = Object.keys(v).map((kk) => kk + asText(v[kk])).join(' / ');
          if (t.trim()) extras.push(k + '：' + t);
          return;
        }
        extras.push(k + '：' + asText(v));
      });
      if (extras.length) lines.push('      ' + extras.join(' · '));
      return lines.join('\n');
    };

    const groupOf = (label, names, marks) => {
      const cells = [];
      for (let i = 0; i < 3; i++) {
        const s = arr(names)[i] || null;
        cells.push(slotRow(s && s.name, s, (marks && marks[i]) || ''));
