      cells.forEach((c) => L.push(c));
    };

    const baseSlot = (combo.基础技能槽 || []).map((nm) => ({ name: nm }));
    const classSlot = (combo.转职技能槽 || []).map((nm) => ({ name: nm }));
    L.push('  基础 / 转职（6 格 · 连击起点 · 与面板技能栏同序）');
    for (let i = 0; i < 3; i++) L.push(slotRow((baseSlot[i] || {}).name, baseSlot[i]));
    for (let i = 0; i < 3; i++) L.push(slotRow((classSlot[i] || {}).name, classSlot[i]));

    const groups = isObj(combo.高级技能组配置) ? combo.高级技能组配置 : {};
    const curKey = asText(combo.当前高级组) || 'alpha';
    const curDisplay = asText(combo.当前显示槽) === 'ultimate' ? 'ultimate' : 'advanced';
    const labelOf = (k) => ({ alpha: '高级技能组 I', beta: '高级技能组 II', gamma: '高级技能组 III', ultimate: '终式技能组' }[k] || k);
    ['alpha', 'beta', 'gamma', 'ultimate'].forEach((k) => {
      const list = (groups[k] || []).map((nm) => ({ name: nm }));

      const marks = [];
      const isCur = (k === 'ultimate') ? (curDisplay === 'ultimate') : (k === curKey);
