      groupOf(labelOf(k) + (isCur ? ' ★当前组' : ''), list, null);
    });

    const awk = arr(o.awakening).filter((a) => a && asText(a.name).trim());
    const awkCfg = combo.觉醒技能槽 ? Object.keys(combo.觉醒技能槽) : [];
    L.push('  觉醒槽（独立体系 · 不参与连击 · 参与冷却）');
    if (awk.length) {
