  function refBlock(refs, selected, opts) {
    const o = isObj(opts) ? opts : {};

    const refMode = o.mode !== undefined ? o.mode : 'classic';
    const sel = arr(selected).map((s) => asText(s).trim()).filter(Boolean);
    if (!sel.length) return '';
    const list = arr(refs).filter((r) => isObj(r) && sel.indexOf(asText(r.name).trim()) >= 0);
    if (!list.length) return '';
    const L = ['  参考名单（玩家勾选的人物资料）'];

    list.forEach((r) => {
      const d = isObj(r.detail) ? r.detail : {};
