    const callGenerateRaw = typeof d.callGenerateRaw === 'function' ? d.callGenerateRaw : null;
    const submitReply = typeof d.submitReply === 'function' ? d.submitReply : () => null;
    const snapshot = typeof d.snapshot === 'function' ? d.snapshot : () => null;
    const matrix = typeof d.matrix === 'function' ? d.matrix : () => null;
    const note = typeof d.note === 'function' ? d.note : () => {};
    const onState = typeof d.onState === 'function' ? d.onState : () => {};
    const log = typeof d.log === 'function' ? d.log : () => {};
    const getMaxChatHistory = typeof d.getMaxChatHistory === 'function' ? d.getMaxChatHistory : () => undefined;
    const callCreateChatMessages = typeof d.callCreateChatMessages === 'function' ? d.callCreateChatMessages : null;

    const resolveChannel = typeof d.resolveChannel === 'function' ? d.resolveChannel : null;
    const hostCaps = typeof d.hostCaps === 'function' ? d.hostCaps : null;
    const postJson = typeof d.postJson === 'function' ? d.postJson : null;

    const getWorldbook = typeof d.getWorldbook === 'function' ? d.getWorldbook : null;

    const getPresetItems = typeof d.getPresetItems === 'function' ? d.getPresetItems : () => null;

    async function wbTextOf(o) {
      if (!getWorldbook) return { text: '', skipped: [], notes: [] };
      let r;
      try {
        r = await getWorldbook(o);
      } catch (e) {
        safeCall(() => log('system', `⚠️ 世界书读取抛错（本轮不带世界书）：${e && e.message ? e.message : e}`));
        return { text: '', skipped: [], notes: [] };
      }
      const x = isObj(r) ? r : {};
      const skipped = Array.isArray(x.skipped) ? x.skipped : [];
      const notes = Array.isArray(x.notes) ? x.notes : [];

      notes.forEach((n) => safeCall(() => log('system', n)));
      if (skipped.length) {
        const names = skipped.map((s) => `${s.name || s.book || '?'}（${s.reason}）`).slice(0, 8);
        safeCall(() => log('system', `⚠️ 世界书有 ${skipped.length} 条没发出去：${names.join('；')}`
          + (skipped.length > 8 ? ' …' : '')));
      }
      const text = asText(x.text) || asText(x.block && x.block.text);
      if (!text.trim()) {
        safeCall(() => log('system', 'ℹ️ 本轮没有可发的世界书条目（未勾选 / 都读不到）—— 战斗规则可能缺失'));
      } else {

        const nWb = Number(x.count) || Number(x.block && x.block.count) || (Array.isArray(x.items) ? x.items.length : 0);
        safeCall(() => log('system', `📖 已带世界书 ${nWb} 条 / ${text.length} 字（已跑宏与 EJS）`));
      }
      return { text, skipped, notes };
    }

    let busy = false;

    let lastAction = '';
    let lastAt = 0;

    const DUPLICATE_WINDOW_MS = 1500;

    let state = 'idle';

    let lastFailure = null;
    const now = () => (typeof d.now === 'function' ? d.now() : Date.now());

    function setState(next) {
      state = next;
      try { onState(next); } catch (e) {                  }
    }

    function isBusy() { return busy; }
    function getState() { return state; }
    function getLastFailure() { return lastFailure; }

    function safeCall(fn) {
      try { fn(); } catch (e) {                  }
    }

    async function sendViaPanel(dec, actionText, where, o) {
      const api = isObj(dec && dec.api) ? dec.api : {};

      busy = true;
      setState('generating');
      const wb = await wbTextOf(o);

      const pack = (() => {
        try { return typeof d.getPresetPack === 'function' ? d.getPresetPack() : null; } catch (e) { return null; }
      })();
      const packItems = (() => {
        if (!isObj(pack)) return null;
        return Array.isArray(pack.items) ? pack.items : (pack.items === null ? null : undefined);
      })();
      const presetItems = (() => {
        if (Array.isArray(packItems) && packItems.length) return packItems;
        const x = (() => { try { return getPresetItems(); } catch (e) { return null; } })();
        if (Array.isArray(x) && x.length) return x;

        return (packItems === null) ? null : (Array.isArray(x) ? x : null);
      })();

      const histR = (() => {
        try {
          const fn = d.getChatHistory;
          if (typeof fn !== 'function') {

            return { ok: false, messages: [], reason: '引擎没拿到 getChatHistory（host-caps/host-hooks 没接上）' };
          }
          const n = o.maxChatHistory !== undefined ? o.maxChatHistory : getMaxChatHistory();
          return fn(n);
        } catch (e) { return { ok: false, messages: [], reason: asText(e && e.message) }; }
      })();
      const historyMessages = (isObj(histR) && Array.isArray(histR.messages)) ? histR.messages : [];
      if (isObj(histR) && histR.ok !== true) {
        safeCall(() => log('system', `⚠️ 聊天历史没读到：${asText(histR.reason) || '原因未知'}（这一轮不带历史）`));
      } else if (!historyMessages.length) {

        const sk = (isObj(histR) && isObj(histR.skipped)) ? histR.skipped : {};
        const why = `读到 0 楼（隐藏 ${sk.hidden || 0} / 空楼 ${sk.empty || 0} / 无 role ${sk.roleUnknown || 0}）`;
        safeCall(() => log('system', `ℹ️ 本轮不带聊天历史：${why}`));
      } else {
        safeCall(() => log('system', `💬 已带聊天历史 ${historyMessages.length} 楼（${histR && histR.chars ? histR.chars : 0} 字，来自 ${asText(histR && histR.from) || '?'}）`));
      }
      const historyText = (() => {
        if (!historyMessages.length) return '';
        return historyMessages.map((m) => `[${m.role}] ${asText(m.content)}`).join('\n');
      })();

      const ctx = {
        action: actionText,
        snapshot: snapshot(),
        matrix: matrix(),
        maxChatHistory: o.maxChatHistory !== undefined ? o.maxChatHistory : getMaxChatHistory(),
        worldbookText: wb.text,

        presetItems,

        playerPresetItems: (isObj(pack) && Array.isArray(pack.playerPreset)) ? pack.playerPreset : null,
        vars: (isObj(pack) && isObj(pack.vars)) ? pack.vars : null,

        extra: (() => {
          try { return typeof d.extraSnapshot === 'function' ? d.extraSnapshot() : null; } catch (e) { return null; }
        })(),

        panelText: (() => {
          try {
            const sn = typeof d.panelSnapshot === 'function' ? d.panelSnapshot() : null;
            return isObj(sn) ? asText(sn.text) : '';
          } catch (e) { return ''; }
        })(),

        actionRaw: actionText,

        historyText,

        historyMessages,

        historyNote: (() => {

          if (isObj(histR) && asText(histR.note)) return asText(histR.note);
          if (historyMessages.length) return `【聊天历史】已随本次请求逐楼附带 ${historyMessages.length} 楼（role 原样）`;
          if (isObj(histR) && histR.ok !== true) return `【聊天历史】本次请求**没有**附带聊天楼层（${asText(histR.reason) || '原因未知'}）`;
          const sk = (isObj(histR) && isObj(histR.skipped)) ? histR.skipped : {};
          return `【聊天历史】本次请求**没有**附带聊天楼层（读到 0 楼：隐藏 ${sk.hidden || 0} / 空楼 ${sk.empty || 0} / 无 role ${sk.roleUnknown || 0}）`;
        })(),
      };

      const failBuild = (reason, kind) => {
        busy = false;
        return { ok: false, reason, kind: kind || 'build_failed' };
      };

      const built = Prompt.buildPanelMessages
        ? Prompt.buildPanelMessages(ctx)
        : { ok: false, reason: '内核没有 buildPanelMessages（版本不匹配）' };
      if (!built.ok) {
        safeCall(() => note(`⚠️ 组装请求失败：${built.reason}`));
        return failBuild(built.reason);
      }

      const caps = (() => {
        try { return hostCaps(); } catch (e) { return null; }
      })();
      const seg = ApiMod.formatSegments(caps, built.parts);

      {
        const byteOf = (x) => String((x && x.content) || '').length;
        const total = seg.messages.reduce((n, m) => n + byteOf(m), 0);
        const byKind = {};

        const sameLen = Array.isArray(built.parts) && built.parts.length === seg.messages.length;
        seg.messages.forEach((m, i) => {
          const p = sameLen
            ? built.parts[i]
            : built.parts.filter((z) => z && z.content === m.content)[0];
          const k = (p && p.kind) ? p.kind : ((m && m.role) || 'other');
          byKind[k] = (byKind[k] || 0) + byteOf(m);
        });
        const parts = Object.keys(byKind)
          .sort((a, b) => byKind[b] - byKind[a])
          .map((k) => `${k} ${byKind[k]}`).join(' / ');
        safeCall(() => log('system',
          `📏 本轮请求体：${seg.messages.length} 段 · 共 ${total} 字（${parts}）`
          + `${total > 200000 ? ' —— ⚠️ 偏大，若上游报 429/超长，去 API 配置页调小【带多少历史】' : ''}`));
      }

      if (!seg.ok) {
        const why = seg.reasons.join('；') || '宏/正则能力缺失';
        safeCall(() => note(`⚠️ ${why}`));
        safeCall(() => log('system', `⚠️ 面板通道的文本处理不完整：${why}`));
      }
      if (!seg.messages.length) {
        safeCall(() => note('⚠️ 没有可发送的内容 —— 契约与行动都是空的'));
        return failBuild('empty_messages');
      }

      const preset = (() => {
        const p = built.preset;
        return isObj(p) ? p : {};
      })();
      const req = ApiMod.buildRequest({ api, messages: seg.messages, gen: built.gen, preset });
      if (!req.ok) {
        safeCall(() => note(`⚠️ 拼请求失败：${req.reason}`));
        return failBuild(req.reason);
      }

      setState('generating');
      safeCall(() => note(`⏳ 正在生成…（面板 API · ${where === 'chatbar' ? '发送' : where}）`));
      safeCall(() => log('system',
        `发送中（面板 API）→ ${req.url}${req.guessed ? '（地址是补全的，请核对）' : ''}`
        + `${api.model ? ` · ${api.model}` : ''} · ${seg.messages.length} 段`));

      let res;
      try {
        res = await postJson(req.url, { headers: req.headers, body: req.body });
      } catch (err) {
        res = { ok: false, reason: 'net_error', status: null, okHttp: false, statusText: '', text: '', netError: err };
      }
      busy = false;

      if (!res || res.ok === false) {
        if (res && res.reason === 'no_fetch') {
          lastFailure = {
            kind: 'no_host', status: null, message: '本环境没有 fetch',
            hint: '面板没跑在酒馆里（离线预览/harness 属正常）—— 换到酒馆页面再试',
          };
        } else {
          lastFailure = {
            kind: 'network', status: null,
            message: (res && res.netError && res.netError.message) || (res && res.reason) || '请求失败',
            hint: '网络层异常（连接失败 / 超时 / 被 CORS 拦）—— 端点必须允许浏览器直接跨域访问',
          };
        }
        setState('error');
        const t2 = `❌ 生成失败（${FAIL_LABEL[lastFailure.kind] || lastFailure.kind}）：${lastFailure.message}`;
        safeCall(() => note(t2));
        safeCall(() => log('system', `${t2} —— ${lastFailure.hint}`));
        return { ok: false, reason: 'generate_failed', kind: lastFailure.kind, failure: lastFailure };
      }

      const cls = ApiMod.classifyHttp({
        status: res.status, okHttp: res.okHttp, statusText: res.statusText, text: res.text,
      });
      if (cls.kind !== 'ok') {
        lastFailure = cls;
        setState('error');
        const t2 = `❌ 生成失败（${FAIL_LABEL[cls.kind] || cls.kind}）：${cls.message}`;
        safeCall(() => note(t2));
        safeCall(() => log('system', `${t2} —— ${cls.hint}`));

        if (res.text) safeCall(() => log('system', `响应原文（截断）：${asText(res.text).slice(0, 300)}`));
        return { ok: false, reason: 'generate_failed', kind: cls.kind, failure: cls };
      }

      return applyReply({ text: cls.reply, reasoning: cls.reasoning }, actionText, o);
    }

    async function send(action, opts) {
      const o = isObj(opts) ? opts : {};
      const where = asText(o.source) || 'chatbar';

      if (busy) {
        safeCall(() => note('⚠️ 上一次生成还没结束 —— 等它回来再发（不会排队，避免重复推进回合）'));
        return { ok: false, reason: 'busy', kind: 'busy' };
      }

      const act = Prompt.normalizeAction(action);
      if (!act.ok) {
        safeCall(() => note('⚠️ 发言栏是空的 —— 先写点什么再发送'));
        return { ok: false, reason: act.reason, kind: 'empty' };
      }

      const t = now();
      if (o.force !== true && act.text === lastAction && t - lastAt < DUPLICATE_WINDOW_MS) {
        safeCall(() => note('⚠️ 同一句话刚发过 —— 已忽略这次重复点击（避免连打两回合）'));
        return { ok: false, reason: 'duplicate', kind: 'duplicate' };
      }

      let panelCfg = null;
      if (resolveChannel && postJson && hostCaps && ApiMod) {
        const dec = (() => {
          try { return resolveChannel(); } catch (e) { return null; }
        })();
        if (dec && dec.channel === 'panel') {
          panelCfg = dec;
        } else if (dec && dec.note) {

          safeCall(() => note(dec.note));
          safeCall(() => log('system', dec.note));
        }
      }

      if (panelCfg) {
        return await sendViaPanel(panelCfg, act.text, where, o);
      }

      if (!callGenerate && !callGenerateRaw) {
        safeCall(() => note('⚠️ 拿不到宿主的 generate / generateRaw 接口（预览/非酒馆环境）⇒ 草稿已保留，未发送'));
        lastFailure = { kind: 'no_host', status: null, message: 'callGenerate/callGenerateRaw 均未注入', hint: '面板跑在没有 TavernHelper.generate 的环境里' };
        setState('error');
        return { ok: false, reason: 'no_host', kind: 'no_host' };
      }

      busy = true;
      setState('generating');
      const wb = await wbTextOf(o);

      const hostHist = (() => {
        const read = (() => {
          try {
            const fn = d.getChatHistory;
            if (typeof fn !== 'function') return { ok: false, messages: [], reason: '引擎没拿到 getChatHistory' };
            const n = o.maxChatHistory !== undefined ? o.maxChatHistory : getMaxChatHistory();
            return fn(n);
          } catch (e) { return { ok: false, messages: [], reason: asText(e && e.message) }; }
        })();
        const msgs = (isObj(read) && Array.isArray(read.messages)) ? read.messages : [];

        const okRead = isObj(read) && read.ok === true;
        const note = (() => {
          if (!okRead) return '';
          if (asText(read.note)) return asText(read.note);
          if (msgs.length) return `【聊天历史】已随本次请求逐楼附带 ${msgs.length} 楼（role 原样）`;
          const sk = (isObj(read) && isObj(read.skipped)) ? read.skipped : {};
          return `【聊天历史】本次请求**没有**附带聊天楼层（读到 0 楼：隐藏 ${sk.hidden || 0} / 空楼 ${sk.empty || 0} / 无 role ${sk.roleUnknown || 0}）`;
        })();
        return { messages: msgs, text: msgs.map((m) => `[${asText(m.role)}] ${asText(m.content)}`).join('\n'), note };
      })();

      const ctx = {
        action: act.text,
        snapshot: snapshot(),
        matrix: matrix(),
        maxChatHistory: o.maxChatHistory !== undefined ? o.maxChatHistory : getMaxChatHistory(),
        worldbookText: wb.text,

        extra: (() => {
          try { return typeof d.extraSnapshot === 'function' ? d.extraSnapshot() : null; } catch (e) { return null; }
        })(),
        panelText: (() => {
          try {
            const sn = typeof d.panelSnapshot === 'function' ? d.panelSnapshot() : null;
            return isObj(sn) ? asText(sn.text) : '';
          } catch (e) { return ''; }
        })(),
        actionRaw: act.text,

        historyMessages: hostHist.messages,
        historyText: hostHist.text,
        historyNote: hostHist.note,
      };
      const failBuild = (reason) => {
        busy = false;
        return { ok: false, reason, kind: 'build_failed' };
      };
      let req;
      let viaRaw = false;
      if (callGenerateRaw && Prompt.buildRawRequest) {
        req = Prompt.buildRawRequest(ctx);
        viaRaw = true;
      } else {
        req = Prompt.buildGenerateRequest(ctx);
      }
      if (!req.ok) {
        safeCall(() => note(`⚠️ 组装请求失败：${req.reason}`));
        return failBuild(req.reason);
      }

      if (!viaRaw) {
        safeCall(() => log('system', '⚠️ 宿主没有 generateRaw ⇒ 本次走了 generate（会吃当前预设，可能带进 MVU/世界书噪声）'));
      }

      safeCall(() => note(`⏳ 正在生成…（${where === 'chatbar' ? '发送' : where}）`));

      let replyRaw;
      try {
        replyRaw = viaRaw ? await callGenerateRaw(req.params) : await callGenerate(req.params);
      } catch (err) {
        busy = false;
        const f = classifyFailure(err);
        lastFailure = f;
        setState('error');
        const text = `❌ 生成失败（${FAIL_LABEL[f.kind]}）：${f.message}`;
        safeCall(() => note(text));
        safeCall(() => log('system', text + ' —— ' + f.hint));
        return { ok: false, reason: 'generate_failed', kind: f.kind, failure: f };
      }
      busy = false;

      return applyReply(replyRaw, act.text, t);
    }

    function applyReply(replyRaw, actionText, t) {

      const reply = extractReply(replyRaw);

      const reasoning = (() => {
        if (typeof replyRaw === 'string' || !replyRaw || typeof replyRaw !== 'object') return '';
        const x = replyRaw;

        if (typeof x.reasoning === 'string' && x.reasoning.trim()) return x.reasoning;
        const m = (Array.isArray(x.choices) && x.choices[0] && x.choices[0].message)
          ? x.choices[0].message : (typeof x.message === 'object' ? x.message : null);
        if (!m) return '';
        const tries = [m.reasoning_content, m.reasoning, m.thinking];
        for (let i = 0; i < tries.length; i++) {
          if (typeof tries[i] === 'string' && tries[i].trim()) return tries[i];
        }
        if (Array.isArray(m.reasoning_details)) {
          return m.reasoning_details.map((z) => (z && typeof z === 'object' ? asText(z.text) : asText(z)))
            .filter(Boolean).join('\n');
        }
        return '';
      })();
      if (!reply.trim()) {
        lastFailure = { kind: 'empty_reply', status: null, message: '宿主返回了空正文', hint: '模型可能只吐了空格/被过滤；换模型或重发' };
        setState('error');
        safeCall(() => note('⚠️ 生成回来了，但正文是空的 —— 没有喂给解析器（避免把面板推进一回合）'));
        safeCall(() => log('system', '空回复：宿主返回空串（未落地、未推进）'));
        return { ok: false, reason: 'empty_reply', kind: 'empty_reply', reply: '', failure: lastFailure };
      }

      let applied;
      try {

        applied = submitReply(reply, { reasoning });
      } catch (err) {
        setState('error');
        const msg = asText(err && err.message ? err.message : err);
        lastFailure = { kind: 'apply_failed', status: null, message: msg, hint: '解析/落地阶段抛错 —— 这是面板自己的 bug，请把这条日志发给开发者' };
        safeCall(() => note(`❌ 回复落地失败：${msg}`));
        safeCall(() => log('system', `回复落地失败：${msg}`));
        return { ok: false, reason: 'apply_failed', kind: 'apply_failed', reply, failure: lastFailure };
      }

      lastFailure = null;
      setState('idle');
      const advanced = applied && applied.advanced ? applied.advanced : null;
      const appliedN = applied && Number.isFinite(Number(applied.applied)) ? Number(applied.applied) : 0;

      if (!applied || applied.ok === false) {
        lastAction = '';
        lastAt = 0;
        const why = asText(applied && applied.reason) || '解析器没认出任何变更';
        safeCall(() => note(`⚠️ 生成回来了，但没落地：${why}`));
        safeCall(() => log('system', `回复未落地：${why}（正文 ${reply.length} 字）`));

        return {
          ok: true, reason: 'not_applied', kind: 'not_applied',
          reply, applied: appliedN, keepDraft: true,
        };
      }

      lastAction = actionText;
      lastAt = t;
      safeCall(() => note(advanced
        ? `✅ 已结算 ${appliedN} 处变更，回合推进 → 第 ${advanced.round} 轮`
        : `✅ 已结算 ${appliedN} 处变更（本轮未推进）`));
      safeCall(() => log('system', `发送完成：正文 ${reply.length} 字，落地 ${appliedN} 处`
        + (advanced ? `，推进到第 ${advanced.round} 轮` : '，未推进')));
      return {
        ok: true, reason: '', kind: 'ok', reply,
        applied: appliedN,
        decision: applied ? applied.decision : null,
        advanced,
      };
    }

    function settleToMain(summary) {
      const s = isObj(summary) ? summary : {};
      const lines = Array.isArray(s.lines) ? s.lines.filter((x) => asText(x).trim()) : [];
      const given = asText(s.text).trim();
      if (!given && !lines.length) return { ok: false, reason: 'empty', written: 0 };
      if (!callCreateChatMessages) {
        safeCall(() => note('⚠️ 拿不到宿主的 createChatMessages（预览/非酒馆环境）⇒ 摘要没有写回主楼'));
        return { ok: false, reason: 'no_host', written: 0 };
      }

      const text = given || [asText(s.title) || '【战斗结算】', ...lines].join('\n');
      try {
        callCreateChatMessages([{ role: 'assistant', message: text }]);
        safeCall(() => note('✅ 战斗摘要已写回主楼（一条 assistant 消息）'));
        safeCall(() => log('system', `已把战斗摘要写回主楼（${text.length} 字）`));
        return { ok: true, reason: '', written: 1 };
      } catch (err) {
        const msg = asText(err && err.message ? err.message : err);
        safeCall(() => note(`⚠️ 写回主楼失败：${msg}`));
        safeCall(() => log('system', `写回主楼失败：${msg}`));
        return { ok: false, reason: 'write_failed', written: 0 };
      }
    }

    function _reset() {
      busy = false; lastAction = ''; lastAt = 0; state = 'idle'; lastFailure = null;
    }

    return {
      send, settleToMain,
      isBusy, getState, getLastFailure,
      classifyFailure, extractReply, FAIL_LABEL,
      _reset, DUPLICATE_WINDOW_MS,
    };
  }

  const Api = { createEngine, classifyFailure, extractReply, FAIL_LABEL };
  if (typeof window !== 'undefined') window.__BE3_ENGINE__ = Api;
