    if (!url) return avatarPlaceholder(name, { kind, size });
    const cls = ['be3-avatar', `is-${kind}`, `is-${size}`].join(' ');

    return `<span class="${cls}"><img src="${esc(url)}" alt="${esc(name)}" loading="lazy" decoding="async" /></span>`;
  }

  function avatarFromMap(name, o) {
    const nm = asText(name).trim();
    if (!nm) return '';

    const map = isObj(o.avatars) ? o.avatars : (isObj(o.view) && isObj(o.view.avatars) ? o.view.avatars : null);
    if (!map) return '';
    const hit = map[nm];
    if (!isObj(hit)) return '';

    return typeof hit.url === 'string' ? hit.url.trim() : '';
  }

  function avatarUrl(name, opts) {
    const o = isObj(opts) ? opts : {};
    if (!asText(name).trim()) return '';
    const fromMap = avatarFromMap(name, o);
    if (fromMap) return fromMap;
    const A = avatarApi();
    if (!A) return '';
    try { return asText(A.getPresetAvatar(name)); } catch (e) { return ''; }
  }

  function avatarPlaceholder(name, opts) {
    const o = isObj(opts) ? opts : {};
    const kind = ['status', 'hud', 'squad'].indexOf(o.kind) >= 0 ? o.kind : 'status';
    const size = ['lg', 'md', 'sm'].indexOf(o.size) >= 0 ? o.size : 'lg';
    const ch = asText(name).trim().slice(0, 1) || '?';
    return `<span class="be3-avatar is-${kind} is-${size} is-ph" aria-hidden="true">${esc(ch)}</span>`;
  }

  function hpClass(cur, max) {
    const c = Number(cur); const m = Number(max);
    if (!Number.isFinite(c) || !Number.isFinite(m) || m <= 0) return '';
    const p = c / m;
    if (p <= 0.2) return 'is-critical';
    if (p <= 0.5) return 'is-low';
    return '';
  }

  function renderUnit(u) {
    const hasHp = Number.isFinite(Number(u.hp));
    const cur = hasHp ? Number(u.hp) : null;
    const max = Number.isFinite(Number(u.hpMax)) ? Number(u.hpMax) : null;
    const pct = (cur !== null && max && max > 0) ? Math.max(0, Math.min(100, (cur / max) * 100)) : 0;
    const temp = Number.isFinite(Number(u.tempHp)) ? Number(u.tempHp) : 0;

    const hpText = hasHp
      ? `<b>${esc(cur)}</b>${temp > 0 ? `<i class="be3-temp">(+${esc(temp)})</i>` : ''}<span>/ ${esc(max === null ? '--' : max)}</span>`
      : '<span class="be3-dim">--/--</span>';

    const statuses = (Array.isArray(u.statuses) ? u.statuses : []).map((s) => {
      const nm = asText(s && s.name);
      if (!nm) return '';
      const rd = (s && s.剩余回合 !== null && s.剩余回合 !== undefined) ? Number(s.剩余回合) : null;
      return `<span class="be3-chip" title="${esc(nm)}${rd === null ? '（永久/未标注）' : `（剩余 ${rd} 回合）`}">`
        + `${esc(nm)}${rd === null ? '' : `<i>${esc(rd)}</i>`}</span>`;
    }).filter(Boolean).join('');

    const dist = (() => {

      const raw = u.distance;
      const d = (raw === null || raw === undefined || raw === '') ? NaN : Number(raw);
      if (!Number.isFinite(d)) return '';
      const G = geoApi();
      const lab = (G && typeof G.distanceLabel === 'function')
        ? G.distanceLabel(d, { source: 'declared' })
        : { text: `${Math.round(d * 10) / 10} 米`, tierLabel: '' };
      return `<span class="be3-chip is-dist" title="到主角的距离（AI 声明）· ${esc(lab.tierLabel || '')}">${esc(lab.text)}</span>`;
    })();

    const actedCls = u.pending === true ? ' is-pending' : (u.acted === true ? ' is-acted' : '');

    return `<div class="be3-unit be3-kind-${esc(u.kind)}${actedCls}" data-be3-row="${esc(u.name)}">
      <div class="be3-unit-head">
        <span class="be3-kind">${esc(KIND_LABEL[u.kind] || u.kind)}</span>
        <b class="be3-name">${esc(u.name)}</b>
        ${u.level ? `<span class="be3-lv">Lv.${esc(u.level)}</span>` : ''}
        ${u.rank ? `<span class="be3-rank">${esc(u.rank)}</span>` : ''}
        ${u.pending === true ? '<span class="be3-flag">待行动</span>' : ''}
      </div>
      <div class="be3-hp-row">
        <div class="be3-hp-bar"><i class="${hpClass(cur, max)}" style="width:${pct}%"></i></div>
        <span class="be3-hp-text">${hpText}</span>
      </div>
      <div class="be3-chips">${dist}${statuses}</div>
      ${u.ac !== undefined ? `<div class="be3-meta">AC ${esc(u.ac)}${u.posture !== undefined ? ` · 架势 ${esc(u.posture)}%` : ''}</div>` : (u.posture !== undefined ? `<div class="be3-meta">架势 ${esc(u.posture)}%</div>` : '')}
      ${u.surround ? `<div class="be3-meta be3-dim">${esc(u.surround)}</div>` : ''}
    </div>`;
  }

  function renderField(f) {
    const dur = f.duration === null || f.duration === undefined
      ? '永久'
      : `${esc(f.duration)} 回合`;
    return `<div class="be3-field" data-be3-row="${esc(f.name)}">
      <span class="be3-glyph">${esc(f.glyph || (f.kind === 'scene' ? '🏛️' : '🌀'))}</span>
      <b>${esc(f.name)}</b>
      ${f.fieldType ? `<span class="be3-dim">${esc(f.fieldType)}</span>` : ''}
      ${f.radius !== undefined ? `<span class="be3-dim">范围 ${esc(f.radius)} 米</span>` : ''}
      <span class="be3-dur">${dur}</span>
      ${f.effect ? `<div class="be3-meta be3-dim">${esc(f.effect)}</div>` : ''}
    </div>`;
  }

  function skillLevel(sk) {
    const bare = Number.isFinite(Number(sk.当前等级)) ? Number(sk.当前等级) : 0;
    const bonus = Number.isFinite(Number(sk.等级加成)) ? Number(sk.等级加成) : 0;

    const lv = Number.isFinite(Number(sk.有效等级)) ? Number(sk.有效等级) : bare;
    const capped = sk.等级封顶 === true;
    const bits = [`Lv.${lv}`];
    if (bonus > 0) bits.push(`（含装备 +${bonus}，裸 ${bare}）`);
    else bits.push(`（裸 ${bare}）`);
    if (capped) bits.push('· 已封顶');
    return { lv, bonus, bare, capped, tip: bits.join('') };
  }

  function skillAction(isUsed, cooling) {
    if (isUsed && cooling !== true) return 'unuse-skill';
    return 'use-skill';
  }

  function renderSkillBar(plan, view) {
    const p = isObj(plan) ? plan : {};
    const v = isObj(view) ? view : {};
    const used = new Set(Array.isArray(v.used) ? v.used : []);

    const cell = (sk, kind) => {
      if (!sk) return `<div class="be3-skill is-empty ${kind}"></div>`;
      const cooling = sk.cooling === true;
      const isUsed = used.has(sk.name);
      const lvInfo = skillLevel(sk);
      const cls = ['be3-skill', kind, cooling ? 'is-cooling' : '', isUsed ? 'is-used' : ''].filter(Boolean).join(' ');
      const sub = cooling
        ? `<span class="be3-skill-cd">${esc(sk.冷却计数)}</span>`
        : (isUsed ? '<span class="be3-skill-cd is-ok">✓</span>' : '');

      const lvBadge = `<span class="be3-skill-lv${lvInfo.capped ? ' is-capped' : ''}"`
        + ` title="${esc(lvInfo.tip)}">${esc(lvInfo.lv)}</span>`;

      const tip = isUsed && !cooling
        ? `${esc(sk.name)}｜${esc(sk.阶位 || '')} ${esc(lvInfo.tip)}｜点一下取消本回合使用`
        : `${esc(sk.name)}｜${esc(sk.阶位 || '')} ${esc(lvInfo.tip)}${cooling ? `｜冷却 ${esc(sk.冷却计数)} 回合` : ''}`;
      return `<button class="${cls}" data-be3-action="${skillAction(isUsed, cooling)}"
        data-be3-skill="${esc(sk.name)}" title="${tip}">
        <span class="be3-skill-name">${esc(sk.name)}</span>
        ${lvBadge}
        ${sub}
      </button>`;
    };

    if (p.mode === 'classic') {
      const cfg = isObj(p.config) ? p.config : {};
      const mainCount = Math.max(1, Number(cfg.main) || 7);
      const awkCount = Math.max(0, Number(cfg.awakening) || 2);
      const mainCells = (Array.isArray(p.main) ? p.main : []).map((s) => cell(s, 'is-main'));
      const awkCells = (Array.isArray(p.awakening) ? p.awakening : []).map((s) => cell(s, 'is-awk'));

      while (mainCells.length < mainCount) mainCells.push(cell(null, 'is-main is-empty'));
      while (awkCells.length < awkCount) awkCells.push(cell(null, 'is-awk is-empty'));
      return `<div class="be3-skillbar is-classic">
      <div class="be3-skillbar-head">
        <span class="be3-sec-title">技能</span>
        <span class="be3-group">经典</span>
        <span class="be3-display">主动 ${mainCells.length} 格</span>
      </div>
      <div class="be3-skill-row is-main">${mainCells.join('')}</div>
      ${awkCount > 0 ? `<div class="be3-skill-row is-awk">${awkCells.join('')}</div>` : ''}
    </div>`;
    }

    const groupLabel = { alpha: 'A 组', beta: 'B 组', gamma: 'C 组', ultimate: '终式' };
    const slots = (Array.isArray(p.display) ? p.display : []).map((s) => cell(s, 'is-adv'));
    const base = (Array.isArray(p.base) ? p.base : []).map((s) => cell(s, 'is-base'));

    while (slots.length < 3) slots.push(cell(null, 'is-adv'));
    while (base.length < 6) base.push(cell(null, 'is-base'));

    return `<div class="be3-skillbar">
      <div class="be3-skillbar-head">
        <span class="be3-sec-title">技能</span>
        <span class="be3-group">${esc(groupLabel[v.group] || v.group || '—')}</span>
        <span class="be3-display">${v.displaySlot === 'ultimate' ? '终式' : '高级'}</span>
      </div>
      <div class="be3-skill-row is-adv">${slots.join('')}</div>
      <div class="be3-skill-row is-base">${base.join('')}</div>
      ${

         ''}
      ${v.comboHint ? `<div class="be3-skill-hint">ⓘ ${esc(v.comboHint)}</div>` : ''}
    </div>`;
  }

  const KIND_GLYPH = { self: '🛡️', ally: '🤝', summon: '👹', enemy: '⚔️' };

  function renderCanvas(layout, links, extra) {
    const L = isObj(layout) ? layout : {};
    const X = isObj(extra) ? extra : {};
    const pts = Array.isArray(L.points) ? L.points : [];
    const shapesInfo = isObj(X.shapes) ? X.shapes : { shapes: [], missing: [] };
    const shapes = Array.isArray(shapesInfo.shapes) ? shapesInfo.shapes : [];
    const shapeMissing = Array.isArray(shapesInfo.missing) ? shapesInfo.missing : [];
    if (!pts.length && !shapes.length) {
      return '<div class="be3-canvas is-empty"><span>战场画布（导入存档并让 AI 写单位后出现）</span></div>';
    }
    const ls = Array.isArray(links) ? links : [];
    const V = isObj(X.view) ? X.view : {};
    const zoom = Number.isFinite(Number(V.zoom)) ? Number(V.zoom) : 1;
    const panX = Number.isFinite(Number(V.panX)) ? Number(V.panX) : 0;
    const panY = Number.isFinite(Number(V.panY)) ? Number(V.panY) : 0;
    const focus = asText(V.focus);

    const drawTool = asText(X.drawTool);

    const VB = isObj(L.vb) ? L.vb : { w: 100, h: 40, cx: 50, cy: 20 };
    const vw = Number.isFinite(Number(VB.w)) ? Number(VB.w) : 100;
    const vh = Number.isFinite(Number(VB.h)) ? Number(VB.h) : 40;
    const vcx = Number.isFinite(Number(VB.cx)) ? Number(VB.cx) : vw / 2;
    const vcy = Number.isFinite(Number(VB.cy)) ? Number(VB.cy) : vh / 2;

    const worldTf = `translate(${panX} ${panY}) translate(${vcx} ${vcy}) scale(${zoom}) translate(-${vcx} -${vcy})`;

    const shapeHtml = shapes.map((s) => {
      const cls = ['be3-shape', `is-${esc(s.kind)}`, s.dashed ? 'is-dashed' : '',
        s.owner === 'player' ? 'is-player' : '', s.shape ? `is-${esc(s.shape)}` : '']
        .filter(Boolean).join(' ');
      const area = (s.shape === 'rect' && Array.isArray(s.points) && s.points.length >= 3)
        ? `<polygon points="${s.points.map((p) => `${Number(p.x).toFixed(2)},${Number(p.y).toFixed(2)}`).join(' ')}" class="be3-shape-area"/>`
        : `<circle cx="${s.x}" cy="${s.y}" r="${s.r}" class="be3-shape-area"/>`;

      const delBtn = s.owner === 'player'
        ? `<text x="${Number(s.x) + Number(s.r) + 1}" y="${Number(s.y) - Number(s.r) - 1}"
             class="be3-shape-del" data-be3-action="mark-remove"
             data-be3-mark="${esc(s.name)}" data-be3-markkey="${esc(s.markKey || '')}"
             title="删除这个标记（只删你自己画的）">✕</text>`
        : '';
      return `<g class="${cls}">
        <title>${esc(s.label || s.name)}</title>
        ${area}
        <text x="${s.x}" y="${s.y}" class="be3-shape-glyph">${esc(s.glyph)}</text>
        <text x="${s.x}" y="${s.y + Number(s.r) + 3}" class="be3-shape-label">${esc(s.label || s.name)}</text>
        ${delBtn}
      </g>`;
    }).join('');

    const lines = ls.map((k) => {
      const f = k.from; const t = k.to;
      const mx = (f.x + t.x) / 2; const my = (f.y + t.y) / 2;
      const cls = k.dist <= 2 ? 'is-melee' : (k.dist <= 5 ? 'is-near' : '');
      return `<line x1="${f.x}" y1="${f.y}" x2="${t.x}" y2="${t.y}" class="be3-link ${cls}"/>`
        + `<text x="${mx}" y="${my - 1.2}" class="be3-link-label">${esc(k.label)}</text>`;
    }).join('');

    const nodes = pts.map((p) => {
      const isSelf = p.kind === 'self';
      const r = isSelf ? 5.2 : 3.6;
      const glyph = KIND_GLYPH[p.kind] || '•';
      const scale = 100 / (2 * r);

      const hpW = (p.hpPct === null ? 100 : p.hpPct) * 0.08;
      const hpCls = p.hpPct === null ? 'is-unknown'
        : (p.hpPct <= 20 ? 'is-crit' : (p.hpPct <= 50 ? 'is-low' : ''));
      const focused = focus && p.name === focus;
      return `<g class="be3-node is-${esc(p.kind)}${p.pending ? ' is-pending' : ''}${focused ? ' is-focused' : ''}"
          data-be3-action="focus-unit" data-be3-unit="${esc(p.name)}">
        <title>${esc(p.name)}${p.distance !== null ? ` · ${esc(p.distance)} 米` : ''}${p.hpPct !== null ? ` · ${Math.round(p.hpPct)}%` : ''}</title>
        <circle cx="${p.x}" cy="${p.y}" r="${r}" class="be3-node-dot"/>
        <text x="${p.x}" y="${p.y}" class="be3-node-glyph" style="font-size:${scale}px">${glyph}</text>
        <rect x="${p.x - hpW / 2}" y="${p.y + r + 0.8}" width="${Math.max(hpW, 0.6)}" height="1.1"
          rx="0.5" class="be3-node-hp ${hpCls}"/>
        <text x="${p.x}" y="${p.y + r + 4.2}" class="be3-node-name">${esc(p.name)}</text>
      </g>`;
    }).join('');

    const missingAll = (L.missing || []).concat(shapeMissing);
    const missingTip = missingAll.length
      ? `<span class="be3-dim" title="${esc(missingAll.join('、'))}">${missingAll.length} 个无坐标</span>`
      : '';
    return `<div class="be3-canvas">
      <svg viewBox="0 0 ${vw} ${vh}" preserveAspectRatio="xMidYMid meet" aria-label="战场俯视图"
        class="be3-svg${drawTool ? ' is-drawing' : ''}" data-be3-zoom="${zoom}" data-be3-panx="${panX}" data-be3-pany="${panY}"
        data-be3-drawtool="${esc(drawTool)}">
        <g class="be3-world" transform="${worldTf}">
          ${shapeHtml}
          ${lines}
          ${nodes}
        </g>
      </svg>
      <div class="be3-canvas-foot">
        <span class="be3-dim">${pts.length} 个单位${ls.length ? ` · ${ls.length} 条距离线` : ''}${shapes.length ? ` · ${shapes.length} 个场地` : ''}</span>
        <span class="be3-canvas-tools">
          <button class="be3-btn is-mini" data-be3-action="canvas-zoom-out" title="缩小">－</button>
          <span class="be3-dim be3-zoom-label">${Math.round(zoom * 100)}%</span>
          <button class="be3-btn is-mini" data-be3-action="canvas-zoom-in" title="放大">＋</button>
          <button class="be3-btn is-mini" data-be3-action="canvas-reset" title="重置视图">⟲</button>
        </span>
        ${focus ? `<span class="be3-dim">已选中：${esc(focus)}</span>` : ''}
        ${missingTip}
      </div>
    </div>`;
  }

  function renderAwakeningBar(list) {
    const arr = Array.isArray(list) ? list : [];
    if (!arr.length) return '';
    const cells = arr.map((sk) => {
      const cooling = sk.冷却中 === true;
      const isUsed = sk.usedThisRound === true;
      const lvInfo = skillLevel(sk);
      const cls = ['be3-skill', 'is-awk', cooling ? 'is-cooling' : '', isUsed ? 'is-used' : ''].filter(Boolean).join(' ');
      const sub = cooling
        ? `<span class="be3-skill-cd">${esc(sk.冷却计数)}</span>`
        : (isUsed ? '<span class="be3-skill-cd is-ok">✓</span>' : '');

      const lvBadge = `<span class="be3-skill-lv${lvInfo.capped ? ' is-capped' : ''}"`
        + ` title="${esc(lvInfo.tip)}">${esc(lvInfo.lv)}</span>`;
      const tip = isUsed && !cooling
        ? `${esc(sk.name)}｜${esc(sk.阶位 || '觉醒')} ${esc(lvInfo.tip)}｜点一下取消本回合使用`
        : `${esc(sk.name)}｜${esc(sk.阶位 || '觉醒')} ${esc(lvInfo.tip)}${cooling ? `｜冷却 ${esc(sk.冷却计数)} 回合` : ''}`;
      return `<button class="${cls}" data-be3-action="${skillAction(isUsed, cooling)}"
        data-be3-skill="${esc(sk.name)}" title="${tip}">
        <span class="be3-skill-name">${esc(sk.name)}</span>
        ${lvBadge}
        ${sub}
      </button>`;
    }).join('');
    return `<div class="be3-skillbar is-awk">
      <div class="be3-skillbar-head">
        <span class="be3-sec-title">觉醒</span>
        <span class="be3-dim">不参与连击</span>
      </div>
      <div class="be3-skill-row is-awk">${cells}</div>
    </div>`;
  }

  function renderInventory(inv, view) {
    const v = isObj(view) ? view : {};
    if (!inv) {
      return `<div class="be3-sec-title">背包</div>
        <div class="be3-empty">未导入存档（点【导入存档】）</div>`;
    }
    const cur = (v.view || inv.view) === 'warehouse' ? 'warehouse' : 'bag';
    const items = Array.isArray(inv.items) ? inv.items : [];

    const keyword = asText(v.keyword !== undefined ? v.keyword : inv.keyword);
    const curType = asText(v.type !== undefined ? v.type : inv.type) || '全部';

    const expanded = new Set(Array.isArray(v.expanded) ? v.expanded : []);

    const tab = (key, label) => `<button class="be3-tab${cur === key ? ' is-on' : ''}"
      data-be3-action="bag-view" data-be3-view="${key}">${esc(label)}</button>`;

    const types = Array.isArray(inv.types) ? inv.types : [];
    const typeBtn = (t, label, count) => `<button class="be3-chip-btn${curType === t ? ' is-on' : ''}"
      data-be3-action="bag-type" data-be3-type="${esc(t)}">${esc(label)}${count === undefined ? '' : `<i>${esc(count)}</i>`}</button>`;
    const typeBar = typeBtn('全部', '全部')
      + types.map((x) => typeBtn(x.type, x.type || '未分类', x.count)).join('');

    const PAGE = 20;
    const pageCount = Math.max(1, Math.ceil(items.length / PAGE));
    const page = Math.max(0, Math.min(pageCount - 1, Number(v.page) || 0));
    const pageItems = items.slice(page * PAGE, page * PAGE + PAGE);

    const selected = new Set(Array.isArray(v.selected) ? v.selected : []);

    const cells = pageItems.map((it) => {
      const qty = Number(it.数量) || 0;
      const canDrop = qty > 0;
      const eff = asText(it.效果);
      const desc = asText(it.描述);
      const hasDetail = !!eff || !!desc;
      const open = expanded.has(it.name);
      const on = selected.has(it.name);
      const cls = ['be3-bag-cell', it.inWarehouse ? 'is-warehouse' : '',
        open ? 'is-open' : '', on ? 'is-multi' : ''].filter(Boolean).join(' ');
      return `<div class="${cls}" data-be3-row="${esc(it.name)}" data-be3-item="${esc(it.name)}"
          title="${esc(it.name)}${it.类型 ? ` · ${esc(it.类型)}` : ''}${it.品质 ? ` · ${esc(it.品质)}` : ''}">
        <span class="be3-bag-qty">×${esc(qty)}</span>
        <span class="be3-bag-name">${esc(it.name)}</span>
        <span class="be3-bag-ops">
          ${hasDetail ? `<button class="be3-op${open ? ' is-on' : ''}" data-be3-action="bag-detail" data-be3-item="${esc(it.name)}" title="展开效果">详</button>` : ''}
          <button class="be3-op is-danger" data-be3-action="bag-drop" data-be3-item="${esc(it.name)}"
            ${canDrop ? '' : 'disabled'} title="丢弃 1 个">丢</button>
          <button class="be3-op" data-be3-action="bag-move" data-be3-item="${esc(it.name)}"
            data-be3-to="${cur === 'warehouse' ? 'bag' : 'warehouse'}"
            title="${cur === 'warehouse' ? '移回背包' : '移入仓库'}">${cur === 'warehouse' ? '取' : '入'}</button>
        </span>
      </div>`;
    }).join('');

    const details = pageItems.filter((it) => expanded.has(it.name) && (asText(it.效果) || asText(it.描述)))
      .map((it) => {
        const eff = asText(it.效果);
        const desc = asText(it.描述);
        return `<div class="be3-bag-detail" data-be3-row="${esc(it.name)}">
          <div class="be3-bag-detail-head"><b>${esc(it.name)}</b>
            <span class="be3-dim">${esc(it.类型 || '')}${it.品质 ? ` · ${esc(it.品质)}` : ''}</span>
            <span class="be3-spacer"></span>
            <button class="be3-op is-on" data-be3-action="bag-detail" data-be3-item="${esc(it.name)}" title="收起效果">收</button>
          </div>
          ${eff ? `<div class="be3-item-effect">${esc(eff)}</div>` : ''}
          ${desc ? `<div class="be3-meta be3-dim">${esc(desc)}</div>` : ''}
        </div>`;
      }).join('');

    let empty = '';
    if (!items.length) {
      const kw = keyword;
      if (kw) empty = `<div class="be3-empty">没有匹配「${esc(kw)}」的道具</div>`;
      else if (cur === 'warehouse') empty = '<div class="be3-empty">仓库是空的</div>';
      else empty = '<div class="be3-empty">背包是空的（或已全部移入仓库）</div>';
    }

    const otherCount = cur === 'warehouse' ? inv.total : inv.warehouseCount;
    const otherLabel = cur === 'warehouse' ? '在背包' : '在仓库';

    return `<div class="be3-inv">
      <div class="be3-inv-head">
        <span class="be3-sec-title">背包</span>
        ${tab('bag', `背包 ${inv.total}`)}
        ${tab('warehouse', `仓库 ${inv.warehouseCount}`)}
        <span class="be3-spacer"></span>
        <span class="be3-dim">${inv.通用币 !== undefined ? `通用币 ${esc(inv.通用币)}` : ''}</span>
      </div>
      <div class="be3-inv-filter">
        <input class="be3-inv-search" data-be3-input="bag-keyword" value="${esc(keyword)}"
          placeholder="检索（不区分大小写）" />
      </div>
      <div class="be3-chips">${typeBar}</div>
      <div class="be3-bag-grid-wrap" data-be3-scroll="bag">
        ${cells ? `<div class="be3-bag-grid">${cells}</div>` : ''}
        ${details}
        ${cells ? '' : empty}
      </div>
      <div class="be3-pager">
        ${pageCount > 1 ? `<button class="be3-op" data-be3-action="bag-page" data-be3-page="${page - 1}"
          ${page <= 0 ? 'disabled' : ''}>上一页</button>
        <span class="be3-dim">第 ${page + 1} / ${pageCount} 页</span>
        <button class="be3-op" data-be3-action="bag-page" data-be3-page="${page + 1}"
          ${page >= pageCount - 1 ? 'disabled' : ''}>下一页</button>` : ''}
      </div>
      <div class="be3-inv-foot">
        <span class="be3-dim">当前 ${esc(items.length)} / ${esc(inv.totalInView)} 件${otherCount ? ` · 另有 ${esc(otherCount)} 件${otherLabel}` : ''}</span>
        <span class="be3-warn">⚠️ 丢弃/移库只改面板，不写回存档</span>
      </div>
      ${batchBar(Array.from(selected), cur)}
    </div>`;
  }

  function batchBar(sel, cur) {
    const n = Array.isArray(sel) ? sel.length : 0;
    const off = n ? '' : 'disabled';
    const to = cur === 'warehouse' ? 'bag' : 'warehouse';
    const toLabel = cur === 'warehouse' ? '批量取回' : '批量入库';
    return `<div class="be3-bag-batch">
      <span class="be3-dim">框选：在网格里按住拖动${n ? `（已选 <b>${esc(n)}</b> 件）` : ''}</span>
      <span class="be3-spacer"></span>
      <button class="be3-btn is-mini is-danger" data-be3-action="bag-drop-many" ${off}>批量丢弃</button>
      <button class="be3-btn is-mini" data-be3-action="bag-move-many" data-be3-to="${to}" ${off}>${toLabel}</button>
      <button class="be3-btn is-mini" data-be3-action="bag-select-clear" ${off}>清空选中</button>
    </div>`;
  }

  function renderEquipment(eqp) {
    if (!eqp) {
      return `<div class="be3-sec-title">装备</div>
        <div class="be3-empty">未导入存档（点【导入存档】）</div>`;
    }
    const slots = Array.isArray(eqp.slots) ? eqp.slots : [];
    const slotHtml = slots.map((s) => {
      const it = s.item;
      return `<div class="be3-slot${it ? ' is-filled' : ''}">
        <span class="be3-slot-label">${esc(s.label)}</span>
        ${it
    ? `<span class="be3-slot-name" title="${esc(it.名称 || it.name)}">${esc(it.名称 || it.name)}</span>
           ${it.品质 ? `<span class="be3-item-quality">${esc(it.品质)}</span>` : ''}`
    : '<span class="be3-dim">—</span>'}
      </div>`;
    }).join('');

    const box = Array.isArray(eqp.boxItems) ? eqp.boxItems : [];

    const boxHtml = box.length
      ? box.map((it) => `<div class="be3-item is-box">
          <div class="be3-item-head">
            <b class="be3-item-name">${esc(it.名称 || it.name)}</b>
            <span class="be3-dim">${esc(it.部位 || '未分类')}</span>
            ${it.品质 ? `<span class="be3-item-quality">${esc(it.品质)}</span>` : ''}
          </div>
          ${it.效果 ? `<details class="be3-item-detail">
            <summary class="be3-dim">效果</summary>
            <div class="be3-item-effect">${esc(it.效果)}</div>
          </details>` : ''}
        </div>`).join('')
      : '<div class="be3-dim">装备箱是空的</div>';

    const sum = isObj(eqp.summary) ? eqp.summary : {};
    const attrs = isObj(sum.属性) ? sum.属性 : {};
    const attrBits = Object.keys(attrs)
      .filter((k) => Number(attrs[k]) !== 0)
      .map((k) => `<span class="be3-chip">${esc(k)}<i>+${esc(attrs[k])}</i></span>`)
      .join('');
    const tierBits = Object.keys(isObj(sum.阶位) ? sum.阶位 : {})
      .filter((k) => Number(sum.阶位[k]) !== 0)
      .map((k) => `<span class="be3-chip">${esc(k)}技能<i>+${esc(sum.阶位[k])}</i></span>`)
      .join('');
    const unknown = Array.isArray(sum.unknownKeys) ? sum.unknownKeys : [];

    const orph = Array.isArray(eqp.orphans) ? eqp.orphans : [];
    const warnHtml = orph.length
      ? `<div class="be3-warn">⚠️ 部位不在标准槽的已装备：${esc(orph.map((x) => `${x.名称 || x.name}(${x.部位 || '无部位'})`).join('、'))}</div>`
      : '';

    return `<div class="be3-equip">
      <div class="be3-inv-head">
        <span class="be3-sec-title">装备</span>
        <span class="be3-dim">已装备 ${esc(eqp.equipped)} / ${esc(eqp.total)}</span>
        <span class="be3-spacer"></span>
        <span class="be3-chip is-ac">AC ${esc(eqp.ac === null || eqp.ac === undefined ? '--' : eqp.ac)}<i>${esc(eqp.acSource || '')}</i></span>
      </div>
      <div class="be3-slots">${slotHtml}</div>
      ${warnHtml}
      <div class="be3-chips">${attrBits}${tierBits}</div>
      ${Number(sum.生命值上限) ? `<div class="be3-meta">生命值上限 <b>+${esc(sum.生命值上限)}</b></div>` : ''}
      ${unknown.length ? `<div class="be3-meta be3-warn">⚠️ 未识别的加成键（未生效）：${esc(unknown.join('、'))}</div>` : ''}
      <div class="be3-sec-title">装备箱（未穿戴）</div>
      ${boxHtml}
    </div>`;
  }

  function resourceGlyph(r) {
    const t = asText(r && r.类型);
    if (/战斗/.test(t)) return '⚔️';
    if (/生活/.test(t)) return '🧰';
    if (/恢复|治疗/.test(t)) return '✚';
    if (/召唤/.test(t)) return '👹';
    if (/防御|护盾/.test(t)) return '🛡️';
    if (/移动|位移/.test(t)) return '💨';
    return '◈';
  }

  function renderResources(list) {
    const arr = Array.isArray(list) ? list : [];
    const title = '<div class="be3-sec-title">资源技能</div>';
    if (!arr.length) {
      return `${title}<div class="be3-empty">存档里没有资源技能</div>`;
    }
    const cells = arr.map((r) => {
      const exhausted = r.exhausted === true || Number(r.剩余次数) <= 0;
      const isUsed = r.usedThisRound === true;
      const cls = ['be3-res', exhausted ? 'is-out' : '', isUsed ? 'is-used' : '',
        r.low === true ? 'is-low' : ''].filter(Boolean).join(' ');
      const pct = Number.isFinite(Number(r.pct)) ? Math.max(0, Math.min(100, Number(r.pct))) : 0;
      const action = isUsed && !exhausted ? 'unuse-resource' : 'use-resource';
      const tip = isUsed && !exhausted
        ? `${esc(r.name)}｜${esc(r.类型 || '资源')}｜点一下取消本回合使用`
        : `${esc(r.name)}｜${esc(r.类型 || '资源')}｜${esc(r.剩余次数)}/${esc(r.次数上限)}${exhausted ? '（已耗尽）' : ''}`;
      return `<button class="${cls}" data-be3-action="${action}" data-be3-resource="${esc(r.name)}"
        ${exhausted ? 'disabled' : ''}
        title="${tip}">
        <span class="be3-res-icon" aria-hidden="true">${esc(resourceGlyph(r))}</span>
        <span class="be3-res-name">${esc(r.name)}</span>
        <span class="be3-res-bar"><i style="width:${pct}%"></i></span>
        <span class="be3-res-num">${exhausted ? '已耗尽' : `${esc(r.剩余次数)}/${esc(r.次数上限)}`}</span>
      </button>`;
    }).join('');

    return `${title}
      <div class="be3-resbar">
        <div class="be3-resbar-head"><span class="be3-dim">不占槽位 · 不进冷却 · 只有剩余次数（共 ${esc(arr.length)} 个）</span></div>
        <div class="be3-res-row" data-be3-scroll="res">${cells}</div>
      </div>`;
  }

  function renderSelfCard(u, extra) {
    const ex = isObj(extra) ? extra : {};
    const cur = Number.isFinite(Number(u.hp)) ? Number(u.hp) : null;
    const max = Number.isFinite(Number(u.hpMax)) ? Number(u.hpMax) : null;
    const pct = (cur !== null && max && max > 0) ? Math.max(0, Math.min(100, (cur / max) * 100)) : 0;
    const temp = Number.isFinite(Number(u.tempHp)) ? Number(u.tempHp) : 0;
    const hpCls = pct <= 20 ? 'is-critical' : (pct <= 50 ? 'is-low' : '');

    const ac = ex.ac !== null && ex.ac !== undefined ? ex.ac : u.ac;

    const statuses = (Array.isArray(u.statuses) ? u.statuses : []).map((x) => {
      const nm = asText(x && x.name);
      if (!nm) return '';
      const rd = (x && x.剩余回合 !== null && x.剩余回合 !== undefined) ? Number(x.剩余回合) : null;
      return `<span class="be3-chip" title="${esc(nm)}${rd === null ? '（永久/未标注）' : `（剩余 ${rd} 回合）`}">`
        + `${esc(nm)}${rd === null ? '' : `<i>${esc(rd)}</i>`}</span>`;
    }).filter(Boolean).join('');

    const attrs = isObj(u.attrs) ? u.attrs : {};
    const attrHtml = ['力量', '敏捷', '体质', '智力', '感知', '魅力']
      .filter((k) => Number.isFinite(Number(attrs[k])))
      .map((k) => `<span class="be3-attr"><i>${esc(k)}</i><b>${esc(attrs[k])}</b></span>`)
      .join('');

    return `<div class="be3-selfcard">
      <div class="be3-ident">
        ${renderAvatar(u.name, { kind: 'status', size: 'lg', avatars: ex.avatars })}
        <b class="be3-ident-name">${esc(u.name || '（无名）')}</b>
        <span class="be3-ident-sub">${u.level ? `Lv.${esc(u.level)}` : ''}${u.race ? ` · ${esc(u.race)}` : ''}${u.rank ? ` · ${esc(u.rank)}` : ''}</span>
      </div>
      <div class="be3-hpbar">
        <div class="be3-hpbar-bg"><i class="${hpCls}" style="width:${pct}%"></i></div>
        <div class="be3-hpbar-text">
          ${cur !== null ? `<b>${esc(cur)}</b>${temp > 0 ? `<i class="be3-temp">(+${esc(temp)})</i>` : ''}<span>/ ${esc(max === null ? '--' : max)}</span>` : '<span class="be3-dim">--/--</span>'}
          <span class="be3-ac" title="护甲等级">AC ${esc(ac === null || ac === undefined ? '--' : ac)}</span>
        </div>
      </div>
      ${attrHtml ? `<div class="be3-attrs">${attrHtml}</div>` : ''}
      ${statuses ? `<div class="be3-chips">${statuses}</div>` : ''}
    </div>`;
  }

  function refSkillCount(raw) {
    const r = isObj(raw) ? raw : {};
    const own = Object.keys(isObj(r.技能) ? r.技能 : {}).length;
    if (own > 0) return own;
    const tree = isObj(r.技能树) && isObj(r.技能树.技能列表) ? r.技能树.技能列表 : {};
    return Object.keys(tree).length;
  }

  function renderReference(list, selected, opts) {
    const arr = Array.isArray(list) ? list : [];
    const o = isObj(opts) ? opts : {};
    if (!arr.length) {
      return '<div class="be3-empty">存档里没有「羁绊列表 / 附近的人」</div>';
    }
    const sel = new Set(Array.isArray(selected) ? selected : []);
    const nearOnly = o.nearOnly === true;

    const bondsAll = arr.filter((x) => x.source === 'bond');
    const nearsAll = arr.filter((x) => x.source === 'nearby');

    const nearCount = arr.filter((x) => x.nearby === true).length;

    const bonds = nearOnly ? bondsAll.filter((x) => x.nearby === true) : bondsAll;
    const nears = nearOnly ? nearsAll.filter((x) => x.nearby === true) : nearsAll;

    const cardOf = (x) => {
      const on = sel.has(x.name);
      const d = isObj(x.detail) ? x.detail : null;
      const nm = asText(x.name);

      const chk = `<button class="be3-ref-chk${on ? ' is-on' : ''}"
        data-be3-action="ref-toggle" data-be3-ref="${esc(nm)}"
        title="勾选 ⇒ 这个人的资料会作为提示词的一部分发给 AI">${on ? '✓' : ''}</button>`;

      const hp = d ? pct(d.hp, d.hpMax) : 0;
      const hpTxt = (d && num(d.hp) !== null)
        ? `${esc(d.hp)}/${num(d.hpMax) === null ? '--' : esc(d.hpMax)}`
        : '--/--';
      const acTxt = (d && num(d.ac) !== null) ? esc(d.ac) : '--';
      const acTip = (d && d.acSource) ? `AC 来源：${esc(d.acSource)}` : 'AC 未读到';
      const atkCnt = (d && num(d.战斗属性.攻击次数) !== null) ? esc(d.战斗属性.攻击次数) : '--';
      const favTxt = (d && num(d.好感度) !== null) ? `♥${esc(d.好感度)}` : '';

      const san = (d && isObj(d.sanity) && d.sanity.known)
        ? `${esc(d.sanity.cur)}/${esc(d.sanity.max)}` : '--/--';

      const attrKeys = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
      const abbr = { 力量: 'STR', 敏捷: 'DEX', 体质: 'CON', 智力: 'INT', 感知: 'WIS', 魅力: 'CHA' };
      const attrHtml = d ? `<div class="be3-refc-attrs">${attrKeys.map((k) => {
        const v = num(d.属性[k]);
        return `<span class="be3-refc-attr"><i>${esc(abbr[k])}</i><b>${v === null ? '--' : esc(v)}</b></span>`;
      }).join('')}</div>` : '';

      let combatHtml = '';
      if (d) {
        const wp = isObj(d.战斗属性.武器面板) ? d.战斗属性.武器面板 : {};
        const dice = asText(wp.伤害骰);
        const coef = num(wp.等级系数);
        const fixed = num(wp.固定伤害);

        const atkTxt = dice
          ? `${dice}${(coef !== null && coef !== 1) ? `×${coef}` : ''}${(fixed !== null && fixed !== 0) ? `+${fixed}` : ''}`
          : '--';
        const avg = (() => {

          const m = /(\d+)d(\d+)/.exec(dice);
          if (!m) return null;
          const n = Number(m[1]); const f = Number(m[2]);
          const c = (coef === null || coef === 0) ? 1 : coef;
          return Number((c * n * (f + 1) / 2 + (fixed || 0)).toFixed(0));
        })();
        const cb = d.战斗属性;
        const chip = (label, val, tip) => `<span class="be3-refc-chip" title="${esc(tip)}">`
          + `<i>${esc(label)}</i><b>${esc(val)}</b></span>`;
        combatHtml = `<div class="be3-refc-combat">
          ${chip('攻', atkTxt, `武器面板：${dice || '缺'}${fixed !== null ? ` 固伤 ${fixed}` : ''}`)}
          ${avg !== null ? chip('AVG', String(avg), '期望伤害 = 等级系数 × 骰数 × (面数+1)/2 + 固定伤害') : ''}
          ${chip('暴伤', `${num(cb.暴击伤害) === null ? '--' : num(cb.暴击伤害)}x`, '暴击伤害倍率')}
          ${chip('暴击', `${num(cb.暴击阈值) === null ? '--' : num(cb.暴击阈值)}/${num(cb.暴击率) === null ? '--' : num(cb.暴击率)}%`, '暴击阈值 / 暴击率')}
          ${chip('物减', `${num(cb.物理减伤) === null ? '--' : num(cb.物理减伤)}%`, '物理减伤')}
          ${chip('魔减', `${num(cb.魔法减伤) === null ? '--' : num(cb.魔法减伤)}%`, '魔法减伤')}
        </div>`;
      }

      const eqArr = (d && Array.isArray(d.装备)) ? d.装备 : [];
      const eqHtml = `<div class="be3-refc-line"><i>装备</i>${eqArr.length
        ? eqArr.map((e) => `<span class="be3-refc-tag" title="${esc(e.quality ? `品质 ${e.quality}` : '')}">`
          + `${esc(e.slot || '?')}·${esc(asText(e.name).slice(0, 8))}</span>`).join('')
        : '<span class="be3-dim">（无装备）</span>'}</div>`;

      const skArr = (d && Array.isArray(d.技能)) ? d.技能 : [];
      const skHtml = `<div class="be3-refc-line"><i>技能</i>${skArr.length
        ? skArr.map((s) => `<span class="be3-refc-tag is-skill" title="${esc(s.type || '')}">`
          + `${esc(asText(s.name).slice(0, 8))}</span>`).join('')
        : '<span class="be3-dim">（无技能数据）</span>'}</div>`;

      const avatarHtml = renderAvatar(nm, { kind: 'squad', avatars: o.avatars });
      const subBits = [];
      if (d && num(d.等级) !== null) subBits.push(`LV.${d.等级}`);
      if (d && d.种族) subBits.push(d.种族);
      if (d && d.性别) subBits.push(d.性别);

      return `<div class="be3-refc${on ? ' is-on' : ''}" data-be3-refcard="${esc(nm)}">
        <div class="be3-refc-head">
          ${avatarHtml}
          <div class="be3-refc-id">
            <b class="be3-refc-name">${esc(nm)}</b>
            <span class="be3-refc-sub">${esc(subBits.join(' · ')) || '（存档无详细资料）'}</span>
          </div>
          <div class="be3-refc-tags">
            <span class="be3-refc-badge is-bond">${x.source === 'bond' ? '羁绊' : '附近'}</span>
            ${x.nearby === true ? '<span class="be3-refc-badge is-near">就在附近</span>' : ''}
            ${x.nearby === null ? '<span class="be3-refc-badge is-unknown">附近未知</span>' : ''}
          </div>
          ${chk}
        </div>
        <div class="be3-refc-vitals">
          <span class="be3-refc-hpbar"><i style="width:${hp}%"></i></span>
          <span class="be3-refc-vnum">HP ${hpTxt}</span>
          <span class="be3-refc-vnum" title="${acTip}">AC ${acTxt}</span>
          <span class="be3-refc-vnum">攻击 ${atkCnt}</span>
          ${favTxt ? `<span class="be3-refc-vnum" title="好感度">${favTxt}</span>` : ''}
          <span class="be3-refc-vnum" title="存档里没有 SAN 字段 ⇒ 如实显示 --/--">SAN ${san}</span>
        </div>
        ${attrHtml}${combatHtml}
        <div class="be3-refc-line"><i>位置</i><span class="be3-dim">（AI 未标注周边环境）</span></div>
        ${eqHtml}${skHtml}
      </div>`;
    };

    const selOfGroup = (group) => Array.from(sel).filter((n) => group.some((b) => b.name === n)).length;
    const emptyHint = nearOnly
      ? '附近没有羁绊（或存档未标注「附近」）'
      : '存档里没有「羁绊列表 / 附近的人」';

    return `<div class="be3-refwrap">
      <div class="be3-refhead">
        <button class="be3-btn is-mini${nearOnly ? ' is-primary' : ''}"
          data-be3-action="ref-near" data-be3-on="${nearOnly ? '0' : '1'}"
          title="只显示标记为「就在附近」的人">${nearOnly ? '只看附近' : '展示全部'} (${nearOnly ? nearCount : arr.length})</button>
        <span class="be3-spacer"></span>
        <span class="be3-dim">羁绊 ${bondsAll.length}人 · 标记附近 ${nearCount}人`
      + `${sel.size ? ` · 已勾 ${sel.size}` : ''}</span>
        <button class="be3-btn is-mini" data-be3-action="ref-all" data-be3-on="1">全选</button>
        <button class="be3-btn is-mini" data-be3-action="ref-all" data-be3-on="0">全不选</button>
      </div>
      <div class="be3-refc-list" data-be3-scroll="ref">
        ${bonds.length
    ? `<div class="be3-refgroup"><div class="be3-refgroup-head">羁绊角色 ${bonds.length}`
      + `${nearOnly ? '（附近）' : ''}</div>${bonds.map(cardOf).join('')}</div>`
    : ''}
        ${nears.length
    ? `<div class="be3-refgroup"><div class="be3-refgroup-head">附近的人 ${nears.length}</div>`
      + `${nears.map(cardOf).join('')}</div>`
