      : { text: `${Math.round(d * 10) / 10} 米`, tierLabel: '' };
    return `<span class="be3-hud-dist" title="到主角的距离（AI 声明）· ${esc(lab.tierLabel || '')}">${esc(lab.text)}</span>`;
