    }));
    while (mine.length < 3) mine.push({ kind: 'empty', u: null });

    const sanLine = (u) => {
      const s = isObj(u && u.sanity) ? u.sanity : null;
      const known = !!(s && s.known === true && Number(s.max) > 0);
      const p = known ? Math.max(0, Math.min(100, (Number(s.cur) / Number(s.max)) * 100)) : 0;
      return `<span class="be3-sq-line">
