    if (M && typeof M.draw === 'function') return M;

    try {
      if (typeof require === 'function') {
        const R = require('../core/map-draw.js');
        if (R && typeof R.draw === 'function') return R;
      }
    } catch (e) {                                   }
    return null;
  }

  function GeometryApi() {
    try {
      if (typeof require === 'function') return require('../core/geometry.js');
    } catch (e) {                              }
    return (typeof window !== 'undefined' ? window.__BE3_GEOMETRY__ : null) || null;
  }

  const pxX = (u) => `${n2(u)}%`;
  function pyY(vbH) {
    const h = Number.isFinite(Number(vbH)) && Number(vbH) > 0 ? Number(vbH) : 40;
    return (u) => `${n2((Number(u) || 0) / h * 100)}%`;
  }

  const uToYPct = (u, vbH) => n2((Number(u) || 0) / (Number(vbH) || 40) * 100);

  function icoOf(view) {
    const G = GeometryApi();
    const V = isObj(view) ? view : {};
    const zoom = num(V.zoom) === null ? 1 : Number(V.zoom);
    const iconScale = num(V.iconScale) === null ? 1 : Number(V.iconScale);
    if (G && typeof G.iconCounterScale === 'function') return G.iconCounterScale(zoom, iconScale);
    return iconScale / (zoom || 1);
  }

  const ZONE_SW = 2.5;
  const ZONE_DASH = '9 5';

  const LATTICE_RATIO = 0.92;
  const LATTICE_MAX_CQW = 12;

  function sceneSvg(o, vbH) {
    const D = MapDraw();
    if (!D) return '';
    const tint = isObj(o.tint) ? o.tint : D.tintOf('');

    const OUT = Array.isArray(o.zoneOutline) ? o.zoneOutline : [];
    let area = '';
    if (OUT.length >= 3) {

      const pts = OUT.map((p) => `${n2(p.x)},${n2(p.y)}`).join(' ');
      area = `<polygon class="be3-zone-shape" points="${pts}"
        fill="${esc(tint.fill)}" stroke="${esc(tint.line)}"
        stroke-width="${ZONE_SW}" stroke-dasharray="${ZONE_DASH}"></polygon>`;
    } else if (asText(o.shape) === 'rect') {

      area = `<polygon class="be3-zone-shape" points="${(Array.isArray(o.points) ? o.points : [])
        .map((p) => `${n2(p.x)},${n2(p.y)}`).join(' ')}"
        fill="${esc(tint.fill)}" stroke="${esc(tint.line)}"
        stroke-width="${ZONE_SW}" stroke-dasharray="${ZONE_DASH}"></polygon>`;
    } else {

      area = `<circle class="be3-zone-shape" cx="${n2(o.x)}" cy="${n2(o.y)}" r="${n2(o.r)}"
        fill="${esc(tint.fill)}" stroke="${esc(tint.line)}"
        stroke-width="${ZONE_SW}" stroke-dasharray="${ZONE_DASH}"></circle>`;
    }
    return `<svg class="be3-zone-svg" viewBox="0 0 100 ${n2(vbH)}"
      preserveAspectRatio="none" aria-hidden="true">${area}</svg>`;
  }

  function zoneDecorHtml(o, vbH) {
    const dots = (Array.isArray(o.dots) ? o.dots : []).map((d) => `<span class="be3-zone-fill"
      style="left:${pxX(d.x)};top:${pyY(vbH)(d.y)}">${esc(d.emoji)}</span>`).join('');

    const OUT = Array.isArray(o.zoneOutline) ? o.zoneOutline : [];
    let lx = Number(o.x);
    let ly = Number(o.y) + Number(o.r) - uToYPct(1.6, vbH);
    if (OUT.length >= 3) {
      let sx = 0; let sy = 0;
      OUT.forEach((p) => { sx += Number(p.x) || 0; sy += Number(p.y) || 0; });
      lx = sx / OUT.length;
      ly = sy / OUT.length;
    }
    const label = `<span class="be3-zone-label"
      style="left:${pxX(lx)};top:${pyY(vbH)(ly)}">${esc(o.name)}</span>`;
    return dots + label;
  }

  function effectHtml(o, vbH) {
    const w = n2(Number(o.r) * 2);
    const h = uToYPct(Number(o.r) * 2, vbH);
    const dur = o.durationKnown
      ? (o.duration === null ? '永久' : `${o.duration} 回合`) : '';
    const tip = [
      o.name,
      o.rangeMeter !== null ? `范围 ${o.rangeMeter} 米` : '',
      dur ? `持续 ${dur}` : '',
      '点击看详情',
    ].filter(Boolean).join('｜');
    return `<div class="be3-range" role="button" tabindex="0"
      data-be3-action="map-open" data-be3-map="${esc(o.name)}"
      title="${esc(tip)}"
      style="left:${pxX(o.x)};top:${pyY(vbH)(o.y)};width:${w}%;height:${h}%">
      <span class="be3-range-glyph">${esc(o.glyph)}</span></div>`;
  }

  function objLatticeHtml(o, vbH) {
    const L = isObj(o.lattice) ? o.lattice : null;
    if (!L || !Array.isArray(L.points) || L.points.length <= 1) return '';
    const A = isObj(o.anchor) ? o.anchor : { x: 0, z: 0 };
    const sc = Number(o.scale) > 0 ? Number(o.scale) : 1;

    const sp = Number(o.spacing) > 0 ? Number(o.spacing) : 1;
    const dotU = sp * sc;
    const sizePct = Math.min(LATTICE_MAX_CQW, dotU * LATTICE_RATIO);
    const cells = L.points.map((p) => {
      const xU = o.x + (Number(p.x) - Number(A.x)) * sc;
      const yU = o.y + (Number(p.z) - Number(A.z)) * sc;
      return `<span class="be3-lattice-dot"
        style="left:${pxX(xU)};top:${pyY(vbH)(yU)};font-size:${n2(sizePct)}cqw">${esc(p.glyph || o.glyph)}</span>`;
    }).join('');

    return `<div class="be3-lattice-group" data-be3-action="map-open"
      data-be3-map="${esc(o.name)}" title="${esc(o.name)}">${cells}</div>`;
  }

  function objHtml(o, sel, ico, vbH) {
    const D = MapDraw();
    if (!D) return '';
    const isSel = sel && sel === o.name;
    const hasLattice = !!(o.lattice && Array.isArray(o.lattice.points) && o.lattice.points.length > 1);
    const isProp = asText(o.cls) === 'prop';
    const cls = ['be3-mapobj', `is-${esc(o.cls)}`, hasLattice ? 'has-lattice' : '',
      isSel ? 'is-selected' : ''].filter(Boolean).join(' ');
    const box = objBox(o, hasLattice, vbH);

    const showCenter = !hasLattice || isProp;

    const center = showCenter
      ? `<span class="be3-mapobj-glyph${isProp ? ' is-interactive' : ''}">${esc(o.glyph)}</span>`
      : '';

    const label = isProp ? ''
      : `<span class="be3-mapobj-name">${esc(o.name)}${o.rangeMeter !== null ? ` ${o.rangeMeter}m` : ''}</span>`;
    const tip = [
      o.name,
      o.clsLabel,
      o.rangeMeter !== null ? `范围 ${o.rangeMeter} 米` : '',
      o.lethalMeter !== null ? `杀伤 ${o.lethalMeter} 米` : '',
      o.note || '',
    ].filter(Boolean).join('｜');
    return `<div class="${cls}" role="button" tabindex="0"
      data-be3-action="map-open" data-be3-map="${esc(o.name)}" title="${esc(tip)}"
      style="left:${pxX(o.x)};top:${pyY(vbH)(o.y)}">${box}${center}${label}</div>`;
  }

  function objBox(o, hasLattice, vbH) {
    if (hasLattice) return '';
    if (asText(o.cls) === 'prop') return '';
    const w = n2(Number(o.r) * 2);
    const h = uToYPct(Number(o.r) * 2, vbH);
    const rect = asText(o.shape) === 'rect';
    return `<span class="be3-mapobj-box is-fallback${rect ? ' is-rect' : ''}"`
      + ` style="width:${w}%;height:${h}%"></span>`;
  }

  const NODE_CLS = { self: 'is-self', ally: 'is-ally', summon: 'is-summon', enemy: 'is-enemy' };

  function firstChar(name) {
    const t = asText(name).trim();
    if (!t) return '?';

    const arr = Array.from(t);
    return arr.length ? arr[0] : '?';
  }

  const ELEV_MARK = { high: '▲', low: '▼' };

  function elevBadgeHtml(p) {
    const P = isObj(p) ? p : {};
    const cls = asText(P.elev);
    const mark = ELEV_MARK[cls];
    if (!mark) return '';
    const y = num(P.elevY);
    const label = asText(P.elevLabel) || (cls === 'high' ? '高点' : '洼地');
    const tip = `${label}${y === null ? '' : `：高度 Y=${Math.round(Math.abs(y) * 10) / 10} 米`}`;
    return `<i class="be3-node-elev is-${esc(cls)}" title="${esc(tip)}">${mark}</i>`;
  }

  function nodeHtml(p, focus, ico, vbH, measure) {
    const hpPct = p.hpPct === null || p.hpPct === undefined ? null : Number(p.hpPct);

    const tip = [
      p.name,
      p.distance !== null && p.distance !== undefined ? `${p.distance} 米` : '距离未知',
      hpPct !== null ? `HP ${Math.round(hpPct)}%` : '',
      '点击：选中 + 测距（点敌方看全部友方距离；先点友方再点敌方量一对；点空白取消）',
    ].filter(Boolean).join(' · ');

    const M = isObj(measure) ? measure : {};
    const mFrom = M.mode === 'pick' && M.from === p.name;
    const mTo = (M.mode === 'enemy' || M.mode === 'pair') && M.target === p.name;
    const cls = ['be3-node', `is-${esc(p.kind)}`, p.pending ? 'is-pending' : '',
      focus && focus === p.name ? 'is-focused' : '',
      mFrom ? 'is-measure-from' : '', mTo ? 'is-measure-to' : ''].filter(Boolean).join(' ');

    return `<div class="${cls}" role="button" tabindex="0"
      data-be3-action="focus-unit" data-be3-unit="${esc(p.name)}" title="${esc(tip)}"
      style="left:${pxX(p.x)};top:${pyY(vbH)(p.y)}">
      <span class="be3-node-dot">${esc(firstChar(p.name))}</span>
      ${elevBadgeHtml(p)}
      <span class="be3-node-label">${esc(p.name)}</span></div>`;
  }

  const NODE_EMOJI = { ally: '🤝', summon: '👹', enemy: '⚔️' };

  function tierCls(tier) {
    return `is-t${esc(asText(tier) || 'na')}`;
  }

  function distRowHtml(p, opts) {
    const o = isObj(opts) ? opts : {};
    const d = isObj(p) ? p : {};
    const known = Number.isFinite(Number(d.dist));
    const text = asText(d.label) || (known ? `${Math.round(Number(d.dist) * 10) / 10} 米` : '未知');

    const approx = d.approx === true || d.source === 'coords';
    const tier = asText(d.tierLabel) || '';

    const elev = asText(d.elevNote);
    const who = o.showNames === false ? ''
      : `<span class="be3-dist-who">${esc(asText(o.a) || d.a)}<i>⇢</i>${esc(asText(o.b) || d.b)}</span>`;
    return `<div class="be3-dist-row${known ? '' : ' is-unknown'} ${tierCls(d.tier)}">
      ${who}
      <span class="be3-dist-v">${esc(text)}</span>
      ${approx ? '<span class="be3-dist-approx" title="面板按坐标推算（AI 没有声明这一对的距离）">推算</span>' : ''}
      ${tier ? `<span class="be3-dist-tier" title="距离档位（阈值见 TIERS，世界书按档位下发规则）">${esc(tier)}</span>` : ''}
      ${elev ? `<span class="be3-dist-elev" title="地形/高度差（AI 写的地形优先，其次按坐标 y）">${esc(elev)}</span>` : ''}
    </div>`;
  }

  function distLineHtml(ln, vbH, aspect) {
    const L = isObj(ln) ? ln : {};
    const f = isObj(L.from) ? L.from : null;
    const t = isObj(L.to) ? L.to : null;
    if (!f || !t) return '';
    const h = Number.isFinite(Number(vbH)) && Number(vbH) > 0 ? Number(vbH) : 40;

    const yPct = pyY(h);
    const coef = 100 / h;

    const A = Number.isFinite(Number(aspect)) && Number(aspect) > 0.5 ? Number(aspect) : 2.5;
    const dx = Number(t.x) - Number(f.x);
    const dyPct = (Number(t.y) - Number(f.y)) * coef;
    if (!Number.isFinite(dx) || !Number.isFinite(dyPct)) return '';

    const dy = dyPct / A;
    const len = Math.sqrt(dx * dx + dy * dy);
    if (!(len > 0.01)) return '';
    const ang = Math.atan2(dy, dx) * 180 / Math.PI;
    const midX = (Number(f.x) + Number(t.x)) / 2;
    const midY = (Number(f.y) + Number(t.y)) / 2;
    const solo = L.kind === 'solo';
    const approx = L.approx === true || L.source === 'coords';
    const elev = asText(L.elevNote);
    const label = asText(L.label) || '--';
    const tier = asText(L.tierLabel);

    const tip = [
      `${asText(L.a)} ⇢ ${asText(L.b)}：${label}${tier ? `（${tier}）` : ''}`,
      approx ? '面板按坐标推算（AI 没有声明这一对的距离）' : 'AI 声明的距离',
      elev || '',
    ].filter(Boolean).join('\n');
    return '<div class="be3-dline' + (solo ? ' is-solo' : '') + (L.approx ? ' is-approx' : '')
      + '" title="' + esc(tip) + '"'
      + ' style="left:' + pxX(f.x) + ';top:' + pxX(Number(f.y) * coef) + ';width:' + n2(len) + '%;'
      + 'transform:rotate(' + n2(ang) + 'deg)"></div>'
      + '<div class="be3-dline-tag' + (solo ? ' is-solo' : '') + (elev ? ' is-elev' : '')
      + (approx ? ' is-approx' : '') + '" title="' + esc(tip) + '"'
      + ' style="left:' + pxX(midX) + ';top:' + yPct(midY) + '">'
      + esc(label) + (approx ? '<i class="be3-dline-approx">推算</i>' : '') + '</div>';
  }

  function measureHintText(MS) {
    const M = isObj(MS) ? MS : {};
    const mode = asText(M.mode);
    if (!mode) return '';
    const n = Array.isArray(M.rows) ? M.rows.length : 0;
    const title = asText(M.title);

    if (mode === 'pick') return `测距起点：${title || '已选'} —— 再点敌方（点空白取消）`;
    return `测距：${title || '进行中'}（点空白取消）`;
  }

  function distLinesHtml(lines, vbH, aspect) {
    const arr = Array.isArray(lines) ? lines : [];
    const h = Number.isFinite(Number(vbH)) && Number(vbH) > 0 ? Number(vbH) : 40;

    return arr.map((l) => distLineHtml(l, h, aspect)).join('');
  }

  function distBadgesHtml(groups, opts) {
    const G = isObj(groups) ? groups : {};
    const o = isObj(opts) ? opts : {};
    const ally = Array.isArray(G.ally) ? G.ally : [];
    const enemy = Array.isArray(G.enemy) ? G.enemy : [];
    const open = o.open === true;

    const block = (key, label, list, cls) => {
      const rows = list.map((p) => distRowHtml(p)).join('');
      const body = open && list.length
        ? `<div class="be3-dist-list" data-be3-scroll="dist-${esc(key)}">${rows}</div>`
        : '';
      const unknown = list.filter((p) => p.source === 'none').length;
      const lineOn = asText(o.line) === key;
      const btnLabel = key === 'ally' ? '友方内部' : '敌方内部';
      return `<div class="be3-dist-badge ${cls}${open ? ' is-open' : ''}${lineOn ? ' is-lining' : ''}">
        <button class="be3-dist-line-btn is-${esc(key)}${lineOn ? ' is-on' : ''}"
          data-be3-action="dist-line" data-be3-side="${esc(key)}" aria-pressed="${lineOn ? 'true' : 'false'}"
          title="${esc(`${btnLabel}：${list.length} 组 —— 点击在地图上看距离线${lineOn ? '（再点一次关闭）' : ''}`)}">⇢</button>
        <div class="be3-dist-badge-hit" data-be3-action="dist-toggle" data-be3-dist="${esc(key)}"
          title="${esc(`${label}：${list.length} 组${unknown ? `（${unknown} 组未知）` : ''} —— 点击展开/收起清单`)}">
          <span class="be3-dist-k">${esc(label)}</span>
          <i class="be3-dist-n">${list.length}</i>
          ${unknown ? `<i class="be3-dist-unknown" title="${unknown} 组无法确定（AI 没声明、也没有坐标）">?</i>` : ''}
        </div>
      </div>${body}`;
    };
    return `<div class="be3-dist-badges" data-be3-role="dist-badges">
      ${block('ally', '友方内部距离', ally, 'is-ally')}
      ${block('enemy', '敌方内部距离', enemy, 'is-enemy')}
    </div>`;
  }

  function measureOverlayHtml(m, vbH) {
    const M = isObj(m) ? m : {};
    const mode = asText(M.mode);
    if (!mode) return '';
    const rows = Array.isArray(M.rows) ? M.rows : [];
    const list = rows.length
      ? rows.map((p) => distRowHtml(p, { showNames: mode !== 'pair' })).join('')
      : `<div class="be3-measure-empty be3-dim">${
        mode === 'pick' ? '已选起点，等一个敌方单位' : '（这一对没有可用的距离数据）'}</div>`;
    return `<div class="be3-measure" data-be3-role="measure">
      <div class="be3-measure-head">
        <span class="be3-measure-title">${esc(M.title)}</span>
        <span class="be3-spacer"></span>
        <button class="be3-btn is-mini" data-be3-action="measure-clear"
          title="取消测距（也可点地图空白处）">✕</button>
      </div>
      <div class="be3-measure-hint be3-dim">${esc(M.hint)}</div>
      <div class="be3-measure-rows" data-be3-scroll="measure">${list}</div>
    </div>`;
  }

  function linkHtml(k, vbH, ico) {
    const f = isObj(k.from) ? k.from : {};
    const t = isObj(k.to) ? k.to : {};
    const mx = (Number(f.x) + Number(t.x)) / 2;
    const my = (Number(f.y) + Number(t.y)) / 2;
    const cls = k.dist <= 2 ? 'is-melee' : (k.dist <= 5 ? 'is-near' : '');
    return `<svg class="be3-link-layer" viewBox="0 0 100 ${n2(vbH)}" preserveAspectRatio="none" aria-hidden="true">
      <line class="be3-link ${cls}" x1="${n2(f.x)}" y1="${n2(f.y)}" x2="${n2(t.x)}" y2="${n2(t.y)}"></line></svg>`
      + `<span class="be3-link-tag" style="left:${pxX(mx)};top:${pyY(vbH)(my)}">${esc(k.label)}</span>`;
  }

  function iconsHtml(items) {
    const arr = Array.isArray(items) ? items : [];
    if (!arr.length) {
      return `<div class="be3-map-icons" data-be3-role="map-effects" data-be3-scroll="mapeff">`
        + `<div class="be3-map-icons-empty">（无效果）</div></div>`;
    }
    const cells = arr.map((it) => {
      const dur = it.durationKnown ? (it.duration === null ? '∞' : String(it.duration)) : '?';
      const tip = [
        it.name,
        it.rangeMeter !== null ? `范围 ${it.rangeMeter} 米` : '',
        it.durationKnown ? `持续 ${it.duration === null ? '永久' : `${it.duration} 回合`}` : '',
        '点击看详情',
      ].filter(Boolean).join('｜');
      return `<button class="be3-map-icon" data-be3-action="map-open" data-be3-map="${esc(it.name)}"
        title="${esc(tip)}"><span class="be3-map-icon-g">${esc(it.glyph)}</span>`
        + `<i class="be3-map-icon-badge">${esc(dur)}</i></button>`;
    }).join('');
    return `<div class="be3-map-icons" data-be3-role="map-effects" data-be3-scroll="mapeff">${cells}</div>`;
  }

  function listHtml(items, opts) {
    const o = isObj(opts) ? opts : {};
    const arr = Array.isArray(items) ? items : [];
    const mode = asText(o.mode) || 'rows';
    if (mode === 'icons') return iconsHtml(arr);
    const D = MapDraw();
    const head = `<div class="be3-map-list-head"><span>${esc(o.title || '')}</span>`
      + `<span class="be3-dim">${arr.length}</span></div>`;
    if (!arr.length) {
      return `<div class="be3-map-list${o.cls ? ' ' + o.cls : ''}" data-be3-role="${esc(o.role || '')}">`
        + head + `<div class="be3-map-list-empty be3-dim">${esc(o.empty || '（无）')}</div></div>`;
    }
    const rows = arr.map((it) => {

      const badge = !it.durationKnown ? '?' : (it.duration === null ? '∞' : String(it.duration));
      const tint = D ? D.tintOf(it.tintKey || '') : { line: '#a0a6ac' };
      const inner = `<span class="be3-map-list-dot" style="background:${esc(tint.line)}"></span>`
        + `<span class="be3-map-list-n">${esc(it.name)}</span>`
        + `<i class="be3-map-list-badge">${esc(badge)}</i>`;

      return `<div class="be3-map-list-row is-static" title="${esc(it.name)}">${inner}</div>`;
    }).join('');
    return `<div class="be3-map-list${o.cls ? ' ' + o.cls : ''}" data-be3-role="${esc(o.role || '')}">`
      + head + `<div class="be3-map-list-body" data-be3-scroll="${esc(o.scroll || 'maplist')}">${rows}</div></div>`;
  }

  function detailHtml(d) {
    if (!isObj(d)) return '';
    const rows = (Array.isArray(d.rows) ? d.rows : [])
      .map(([k, v]) => `<div class="be3-mapd-row"><i>${esc(k)}</i><b>${esc(v)}</b></div>`).join('');
    const dist = isObj(d.distance) ? d.distance : {};
    const distLine = num(dist.meters) === null
      ? `<div class="be3-mapd-row"><i>距离</i><b class="be3-dim">${esc(dist.reason || '未知')}</b></div>`
      : `<div class="be3-mapd-row"><i>距离</i><b>${esc(dist.meters)} 米</b>`
        + `<span class="be3-dim">（${esc(dist.reason || '')}）</span></div>`;
    const chip = (u) => `<span class="be3-mapd-unit is-${esc(u.kind)}" title="${esc(u.side)}">`
      + `${esc(u.name)}<i>${esc(u.side)}</i></span>`;
    const ins = Array.isArray(d.inside) ? d.inside : [];
    const unk = Array.isArray(d.unknown) ? d.unknown : [];
    const insHtml = ins.length ? ins.map(chip).join('') : '<span class="be3-dim">（无）</span>';
    const unkHtml = unk.length ? unk.map(chip).join('') : '<span class="be3-dim">（无）</span>';
    return `<div class="be3-mapd" data-be3-role="map-detail" data-be3-map="${esc(d.name)}">
