      note('⚠️ 没有发送引擎（预览/harness 环境）⇒ 只做本地推演，没有调用 AI');
      return rn.advance(localOpts || { reason: '玩家点击（本地推演）' });
    }

    const ACTIONS = {

      advance() {
        const rn = R();
        if (!rn) return;
        if (!rn.isInBattle()) {
          rn.beginBattle();
          note('尚未进入战斗 ⇒ 已自动接管（进入战斗）');
        }
        return actWithAi('（玩家点击【推进回合】）请结算本回合的行动，并给出战场变化。',
          { reason: '玩家点击【推进回合】（本地推演）' }, 'advance');
      },

      close() { unmount(); },
      undo() { const rn = R(); if (rn) rn.undo(); },
      redo() { const rn = R(); if (rn) rn.redo(); },

      begin() {
        const rn = R();
        if (!rn) return;
        rn.beginBattle();
        return actWithAi('（玩家点击【进入战斗】）战斗开始，请描述开场并给出第一轮战场状态。',
          { reason: '玩家点击【进入战斗】（本地推演）' }, 'begin');
      },

      end() {
        const r = settleBattle();
        if (r && r.ok) note('战斗结束，摘要已写回主楼');
        else note('战斗结束（摘要没写回主楼 —— 见日志原因）');
      },

      import() {
        const rn = R();
        if (!rn) return;
        const stat = readMvu();
        if (!stat) { note('⚠️ 读不到 MVU 存档（MVU 未就绪或没有 人物 数据）'); return; }
        const r = rn.importSave(stat);
        note(`已导入 ${r.rows} 个单位 / ${r.skills} 个技能 / `
          + `${r.bag} 件道具 / ${r.equipment} 件装备 / ${r.resources} 个资源技能`
          + '（之后战场数据由面板自己维护）');
      },
      clear() {
        const rn = R();
        if (!rn) return;
        const ask = '清空面板？\n\n只清**战场数据**（单位/场地/状态/回合记录）。\n'
          + '存档里的角色属性、技能、背包都不受影响。';

        if (confirmFn) {
          let yes = false;
          try { yes = confirmFn(ask) === true; } catch (e) { yes = false; }
          if (!yes) { note('【清空面板】已取消'); paint(); return; }
        }
        rn.clearAll();
      },
    };

    const PARAM_ACTIONS = {

      'use-skill'(t) {
        const rn = R();
        if (!rn) return { ok: false };
        const name = t.getAttribute('data-be3-skill') || '';
        const r = rn.useSkill(name);

        if (r && r.ok) appendSkillMark(name);
        return r;
      },
      'use-resource'(t) { const rn = R(); return rn ? rn.useResource(t.getAttribute('data-be3-resource') || '') : { ok: false }; },

      'unuse-skill'(t) {
        const rn = R();
        if (!rn) return { ok: false, reason: 'no_runner' };
        const name = t.getAttribute('data-be3-skill') || '';
        const done = rn.unuseSkill(name);
        if (done === true) removeSkillMark(name);
        return done === true ? { ok: true, name } : { ok: false, reason: 'not_used', name };
      },

      'unuse-resource'(t) {
        const rn = R();
        if (!rn) return { ok: false, reason: 'no_runner' };
        const name = t.getAttribute('data-be3-resource') || '';
        const done = rn.unuseResource(name);
        return done === true ? { ok: true, name } : { ok: false, reason: 'not_used', name };
      },
      'bag-view'(t) {
        const rn = R(); if (!rn) return { ok: false };
        rn.setBagView({ view: t.getAttribute('data-be3-view') === 'warehouse' ? 'warehouse' : 'bag' });
        return { ok: true };
      },
      'bag-type'(t) {
        const rn = R(); if (!rn) return { ok: false };
        rn.setBagView({ type: t.getAttribute('data-be3-type') || '全部' });
        return { ok: true };
      },
      'bag-drop'(t) { const rn = R(); return rn ? rn.dropItem(t.getAttribute('data-be3-item') || '', 1) : { ok: false }; },
      'bag-detail'(t) { const rn = R(); return rn ? rn.toggleBagDetail(t.getAttribute('data-be3-item') || '') : { ok: false }; },
      'bag-page'(t) { const rn = R(); if (rn) rn.setBagPage(t.getAttribute('data-be3-page')); return { ok: true }; },
      'bag-move'(t) {
        const rn = R(); if (!rn) return { ok: false };
        const to = t.getAttribute('data-be3-to') === 'bag' ? 'bag' : 'warehouse';
        return rn.moveItem([t.getAttribute('data-be3-item') || ''], to);
      },

      'bag-drop-many'() {
        const rn = R(); if (!rn) return { ok: false, reason: 'no_runner' };
        const names = getBagSelection();
        if (!names.length) { note('还没有选中任何道具 —— 在背包网格里按住拖一个框'); return { ok: false, reason: 'empty' }; }
        const r = rn.dropItems(names, 1);

        if (r && r.ok) clearBagSelection();
        return r;
      },
      'bag-move-many'(t) {
        const rn = R(); if (!rn) return { ok: false, reason: 'no_runner' };
        const names = getBagSelection();
        if (!names.length) { note('还没有选中任何道具 —— 在背包网格里按住拖一个框'); return { ok: false, reason: 'empty' }; }
        const to = t.getAttribute('data-be3-to') === 'bag' ? 'bag' : 'warehouse';
        const r = rn.moveItems(names, to);

        if (r && r.ok) clearBagSelection();
        return r;
      },
      'bag-select-clear'() {
        const rn = R(); if (!rn) return { ok: false, reason: 'no_runner' };
        clearBagSelection();
        note('已清空选中');
        return { ok: true };
      },

      'ref-toggle'(t) { const rn = R(); return rn ? rn.toggleRef(t.getAttribute('data-be3-ref') || '') : { ok: false }; },
      'ref-all'(t) { const rn = R(); return rn ? rn.setRefAll(t.getAttribute('data-be3-on') === '1') : { ok: false }; },

      'ref-near'(t) {
        const rn = R(); if (!rn || !rn.setRefNearOnly) return { ok: false, reason: 'no_runner' };
        const on = t && t.getAttribute ? (t.getAttribute('data-be3-on') === '1') : false;
        rn.setRefNearOnly(on);
        return { ok: true };
      },

      'map-open'(t) {
        const rn = R(); if (!rn || !rn.setMapSel) return { ok: false, reason: 'no_runner' };
        const nm = t && t.getAttribute ? (t.getAttribute('data-be3-map') || '') : '';
        if (!nm) return { ok: false, reason: 'no_map_name' };
        const got = rn.setMapSel(nm);
        note(got ? `已打开「${nm}」的详情` : '已关闭详情');
        return { ok: true, selected: got };
      },

      'map-close'() {
        const rn = R(); if (!rn || !rn.clearMapSel) return { ok: false, reason: 'no_runner' };
        const before = rn.getMapSel ? rn.getMapSel() : '';
        rn.clearMapSel();

        const hadMeasure = !!(rn.getMeasure && asText(rn.getMeasure().mode));
        if (hadMeasure && rn.clearMeasure) rn.clearMeasure();
        return { ok: true, wasOpen: !!before, hadMeasure };
      },

      'skill-cfg'(t) {
        const rn = R(); if (!rn || !rn.setSkillCfg) return { ok: false, reason: 'no_runner' };
        const key = t && t.getAttribute ? (t.getAttribute('data-be3-key') || '') : '';
        const val = t && t.getAttribute ? (t.getAttribute('data-be3-val') || '') : '';
        if (!key) return { ok: false, reason: 'no_key' };
        rn.setSkillCfg(key, val);
        return { ok: true };
      },

      'sb-view'(t) {
        const rn = R(); if (!rn || !rn.setSbView) return { ok: false, reason: 'no_runner' };
        const view = t && t.getAttribute ? (t.getAttribute('data-be3-view') || '') : '';
        const got = rn.setSbView(view);
        note(got === 'equip' ? '装备栏：点【穿上】/【脱下】（只改面板副本，主楼不受影响）' : '已回到状态总览');
        return { ok: true };
      },

      'equip-item'(t) {
        const rn = R(); if (!rn || !rn.toggleEquip) return { ok: false, reason: 'no_runner' };
        const key = t && t.getAttribute ? (t.getAttribute('data-be3-equip-key') || '') : '';
        const slot = t && t.getAttribute ? (t.getAttribute('data-be3-slot') || '') : '';
        const r = rn.toggleEquip(key, true, slot);
        if (!r || !r.ok) note(`⚠️ ${(r && r.reason) || '穿上失败'}`);
        else if (r.changed) note('已穿上（面板自己算的属性，主楼存档不受影响）');
        return r || { ok: false, reason: 'unknown' };
      },

      'unequip-item'(t) {
        const rn = R(); if (!rn || !rn.toggleEquip) return { ok: false, reason: 'no_runner' };
        const key = t && t.getAttribute ? (t.getAttribute('data-be3-equip-key') || '') : '';
        const slot = t && t.getAttribute ? (t.getAttribute('data-be3-slot') || '') : '';
        const r = rn.toggleEquip(key, false, slot);
        if (!r || !r.ok) note(`⚠️ ${(r && r.reason) || '脱下失败'}`);
        else if (r.changed) note('已脱下（面板自己算的属性，主楼存档不受影响）');
        return r || { ok: false, reason: 'unknown' };
      },

      'toggle-side'(t) {
        const rn = R(); if (!rn || !rn.toggleSection) return { ok: false, reason: 'no_runner' };
        const key = t && t.getAttribute ? (t.getAttribute('data-be3-side') || '') : '';
        if (!key) return { ok: false, reason: 'no_key' };
        rn.toggleSection(key);
        return { ok: true };
      },

      'toggle-section'(t) {
        const rn = R(); if (!rn) return { ok: false };
        rn.toggleSection(t.getAttribute('data-be3-section') || '');
        return { ok: true };
      },

      'toggle-settings'() { const rn = R(); if (rn) rn.toggleSettings(); return { ok: true }; },

      'focus-target'(t) {
        const rn = R(); if (!rn) return { ok: false };
        rn.setFocusUnit(t.getAttribute('data-be3-unit') || '');
        return { ok: true };
      },

      'send-chat'() { return sendChat(); },

      'api-add'() {
        return apiMutate((raw) => A.addApi(raw), '已添加一条空的 API 配置 —— 填地址/模型/密钥后点【保存】');
      },

      'api-save'() {
        return apiMutate((raw) => ({ ok: true, api: A.cloneApiBlock(raw) }), '✅ API 配置已保存');
      },

      'api-activate'(t) {
        return apiMutate((raw) => A.activateApi(raw, Number(t.getAttribute('data-be3-api-index'))),
          '已切换「发送」使用的 API');
      },

      'api-toggle'(t) {
        return apiMutate((raw) => A.toggleApi(raw, Number(t.getAttribute('data-be3-api-index'))));
      },

      'api-del'(t) {
        const i = Number(t.getAttribute('data-be3-api-index'));
        return apiMutate((raw) => A.delApi(raw, i), `已删除 API ${i + 1}`);
      },

      'api-models'(t) {
        const i = Number(t.getAttribute('data-be3-api-index'));
        if (!apiModels) {
          note('⚠️ 查模型功能没装配起来（预览/harness 属正常）—— 可以直接手填模型名');
          return { ok: false, reason: 'no_host' };
        }

        paint();
        const p = apiModels(i);

        return Promise.resolve(p).then((r) => {
          if (r && r.ok) note(`✅ 查到 ${r.models.length} 个模型 —— 点模型框右侧箭头即可选`);
          else note(`⚠️ 查询模型失败：${(r && r.reason) || '原因未知'}（可以先手填模型名，不影响发送）`);
          paint();
          return r || { ok: false, models: [], reason: 'no_result' };
        }).catch((e) => {
          note(`⚠️ 查询模型失败：${(e && e.message) || '未知错误'}（可以先手填模型名）`);
          paint();
          return { ok: false, models: [], reason: String(e && e.message) };
        });
      },

      'api-hist'(t) {
        if (!setChatHistoryLimit) {
          note('⚠️ 历史条数设置没装配起来（预览/harness 属正常）');
          return { ok: false, reason: 'no_host' };
        }
        const raw = t && t.tagName === 'INPUT' ? t.value : (t && t.getAttribute ? t.getAttribute('data-be3-hist') : '');
        const n = Number(raw);
        if (!Number.isFinite(n) || n < 0) {
          note('⚠️ 历史条数必须是 ≥ 0 的整数（0 = 全量）');
          return { ok: false, reason: 'bad_number' };
        }
        const lim = setChatHistoryLimit(Math.floor(n));
        note(lim === 0
          ? '✅ 已改为「全量」—— 长档里这会把请求撞爆（实测 116 楼 = 63 万字），建议长档用 20~40'
          : '✅ 已改为最近 ' + lim + ' 楼');
        if (paint) paint();
        return { ok: true, limit: lim };
      },

      'cfg-page'(t) {
        const rn = R(); if (!rn || !rn.setCfgPage) return { ok: false, reason: 'no_runner' };
        if (!rn.getShowSettings || !rn.getShowSettings()) rn.toggleSettings();
        const next = rn.setCfgPage(t.getAttribute('data-be3-page') || '');

        const KEY = { api: 'side-api', preset: 'side-preset', wb: 'side-wb' }[next];
        if (KEY && rn.getCollapsed && rn.getCollapsed()[KEY] === true) rn.toggleSection(KEY);
        return { ok: true, page: next };
      },

      'cfg-close'() {
        const rn = R(); if (!rn || !rn.setCfgPage) return { ok: false, reason: 'no_runner' };
        rn.setCfgPage('');
        return { ok: true };
      },

      'cfg-preset-add'() { return presetOp({ type: 'add' }, '已添加一条（记得填名字与正文）'); },
      'cfg-preset-toggle'(t) { return presetOp({ type: 'toggle', index: idx(t) }); },
      'cfg-preset-del'(t) { return presetOp({ type: 'del', index: idx(t) }, '已删除这一条预设'); },
      'cfg-preset-up'(t) { return presetOp({ type: 'move', index: idx(t), delta: -1 }); },
      'cfg-preset-down'(t) { return presetOp({ type: 'move', index: idx(t), delta: 1 }); },

      'cfg-preset-top'(t) {
        const list = cfgPresetList();
        const i = Number(idx(t));
        const it = list[i];
        if (!it) return { ok: false, reason: 'index' };
        return presetOp({ type: 'moveTo', index: i, id: it.id, pos: 'top' }, `已把「${it.name}」移到最前`);
      },

      'cfg-preset-import-current'() {
        if (!cfg || typeof cfg.importFromCurrent !== 'function') {
          note('⚠️ 预设配置功能没装配起来（预览/harness 属正常）');
          return { ok: false, reason: 'no_host' };
        }
        const r = cfg.importFromCurrent();
        if (!(r && r.ok)) note(`⚠️ ${(r && r.reason) || '导入失败'}`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-import-current-now'() { return ACTIONS['cfg-preset-import-current'](); },

      'cfg-preset-refresh-copy'() {
        if (!cfg || typeof cfg.importFromCurrent !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.importFromCurrent();
        note(r && r.ok ? '✅ 已用酒馆当前的预设刷新玩家副本（战斗扩展条目没动）' : `⚠️ ${(r && r.reason) || '刷新失败'}`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-fill'() {
        if (!cfg || typeof cfg.fillDefaults !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.fillDefaults();
        paint();
        return r || { ok: false };
      },

      'cfg-preset-toliteral'(t) {
        const list = cfgPresetList();
        const it = list[Number(idx(t))];
        if (!it) return { ok: false, reason: 'index' };
        if (!cfg || typeof cfg.toLiteral !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.toLiteral(it.id, promptPreview());
        paint();
        return r || { ok: false };
      },
      'cfg-preset-reset'() { return presetOp({ type: 'reset' }, '已恢复默认预设（世界书 / 契约 / 简报 / 行动）'); },

      'cfg-preset-open'(t) {
        if (!cfg || typeof cfg.setPresetView !== 'function') return { ok: false, reason: 'no_host' };
        const list = cfgPresetList();
        const it = list[Number(idx(t))];
        if (!it) return { ok: false, reason: 'index' };
        cfg.setPresetView({ open: it.id });
        return { ok: true, id: it.id };
      },

      'cfg-preset-import'() {
        if (!cfg || typeof cfg.importPreset !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.importPreset();
        note(r && r.ok ? `✅ 已导入 ${r.count} 条预设` : `⚠️ 导入失败：${(r && r.reason) || '未知原因'}`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-export'() {
        if (!cfg || typeof cfg.exportPreset !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.exportPreset('json');
        note(r && r.ok ? '✅ 已导出 JSON（已复制到剪贴板，也写进了下面的暂存区）'
          : `⚠️ 导出失败：${(r && r.reason) || '未知原因'}`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-export-text'() {
        if (!cfg || typeof cfg.exportPreset !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.exportPreset('text');
        note(r && r.ok ? '✅ 已复制为纯文本（可直接粘到酒馆的提示词管理器）'
          : `⚠️ 导出失败：${(r && r.reason) || '未知原因'}`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-file-import'() {
        if (!cfg || typeof cfg.importFile !== 'function') {
          note('⚠️ 预设配置功能没装配起来（预览/harness 属正常）');
          return { ok: false, reason: 'no_host' };
        }
        cfg.importFile().then((r) => {
          if (r && r.ok) note(`✅ 已从文件导入 ${r.count} 条预设`);
          else if (r && r.reason !== 'cancel') note(`⚠️ 导入失败：${r.reason || '未知原因'}`);
          paint();
        }).catch((e) => {
          note(`⚠️ 导入异常：${e && e.message ? e.message : e}`);
          paint();
        });
        return { ok: true, pending: true };
      },

      'cfg-preset-file-export'() {
        if (!cfg || typeof cfg.exportFile !== 'function') return { ok: false, reason: 'no_host' };
        const r = cfg.exportFile();
        note(r && r.ok ? `✅ 已导出 ${r.name}` : `⚠️ 导出失败：${(r && r.reason) || '未知原因'}（可改用【复制为文本】）`);
        paint();
        return r || { ok: false };
      },

      'cfg-preset-reorder'(t) {
        const from = Number(t.getAttribute('data-be3-from'));
        const to = Number(t.getAttribute('data-be3-to'));
        if (!Number.isInteger(from) || !Number.isInteger(to) || from === to) {
          return { ok: false, reason: 'index' };
        }
        return presetOp({ type: 'moveTo', index: from, pos: to }, '');
      },

      'cfg-preset-preview'() {
        note('✅ 预览已按当前的预设与勾选重算（预览里的 {{roll}} 是原文，不消耗骰子）');
        paint();
        return { ok: true };
      },

      'cfg-wb-current'() {
        if (!wb || typeof wb.selection !== 'function' || typeof wb.apply !== 'function') {
          note('⚠️ 世界书功能没装配起来（预览/harness 属正常）');
          return { ok: false, reason: 'no_host' };
        }
        const books = (() => {
          try {
            const v = wb.viewForRender ? wb.viewForRender() : null;
            return v && Array.isArray(v.books) ? v.books : [];
          } catch (e) { return []; }
        })();
        const bound = books.filter((b) => ['primary', 'additional', 'chat'].indexOf(asText(b && b.source)) >= 0);
        if (!bound.length) { note('⚠️ 没有读到「当前绑定」的世界书（角色卡/聊天可能都没绑）'); return { ok: false, reason: 'none' }; }
        let added = 0;
        bound.forEach((b) => {
          const nm = asText(b && b.name);
          const cur = wb.selection();
          const map = (cur && cur.map) || {};
          if (!nm || Object.prototype.hasOwnProperty.call(map, nm)) return;
          const r = wb.apply({ type: 'follow', book: nm });
          if (r && r.ok && r.changed) added++;
        });
        note(added ? `✅ 已加入 ${added} 本当前使用的世界书（按线上启用状态跟随）`
          : '（这几本已经在参与名单里了）');

        if (wb && typeof wb.loadBook === 'function') {
          const first = asText(bound[0] && bound[0].name);
          if (first) {
            if (typeof wb.setView === 'function') wb.setView({ current: first });
            wb.loadBook(first).then((x) => {
              if (x && x.ok) note(`✅ 正在查看《${first}》，共 ${(x.entries || []).length} 条`);
              paint();
            }).catch(() => paint());
          }
        }
        return { ok: true, added };
      },

      'wb-open'(t) {
        if (!wbOpen) { note('⚠️ 世界书功能没装配起来（预览/harness 属正常）'); return { ok: false, reason: 'no_host' }; }
        wbOpen(t.getAttribute('data-be3-wb-book') || '');
        return { ok: true };
      },

      'wb-book-toggle'(t) {
        const book = t.getAttribute('data-be3-wb-book') || '';
        if (!book) return { ok: false, reason: 'empty' };
        const cur = wbSelection ? wbSelection() : { ok: false, map: {} };
        const map = (cur && cur.map) || {};
        const joined = Object.prototype.hasOwnProperty.call(map, book);

