  const STYLES = "/* ============================================================================\n * Stage_3 · styles.css —— 面板样式\n * ----------------------------------------------------------------------------\n * 用**功能语义**命名变量（不用颜色描述命名）：方便换主题，也让「这是做什么用的」\n * 一眼可见。\n *\n * 🔴🔴 本窗口（第 63 窗口）整体重写：**照 Stage_1 的尺寸与结构**。\n *   前两版的失败都记在这里，别再退回去：\n *     第 1 版 620px 右键小窗 + 10 块平铺  ⇒ 用户「非常乱」\n *     第 2 版 560px 右下 + 单列页签        ⇒ 用户「跟我们原来的面板差的也太多了」\n *   Stage_1 的根容器（`Stage_1/src/ui/styles.css:79-98`）：\n *     fixed 居中 `translate(-50%,-50%)`、`min(1180px, 100vw-48px)` ×\n *     `min(760px, 100vh-48px)`、`border-radius:12px`、`box-shadow:0 12px 40px`\n *   ⇒ 我们照抄这组数值。**窗口本身的大小就是「看起来像不像原来那套」的一半。**\n * ==========================================================================*/\n\n.be3-root {\n  /* ---- 颜色（功能语义命名） ---- */\n  --be3-bg: #14161c;\n  --be3-surface: #1a1f27;\n  --be3-surface-2: #212733;\n  --be3-surface-3: #1e242c;\n  --be3-border: #2e3444;\n  --be3-border-strong: #3a4256;\n  --be3-text: #e6e8ee;\n  --be3-text-muted: #9aa3b5;\n  --be3-accent: #5b8def;\n  --be3-danger: #e05c5c;\n  --be3-warn: #e0a95c;\n  --be3-ok: #4cbf7a;\n  --be3-self: #5b8def;\n  --be3-ally: #4cbf7a;\n  --be3-enemy: #e05c5c;\n  --be3-summon: #a97bd6;\n  --be3-r-md: 8px;\n  --be3-r-lg: 12px;\n  --be3-shadow: 0 12px 40px rgba(0, 0, 0, .55);\n\n  /* ---- 根容器：与 Stage_1 一致的居中大窗 ---- */\n  position: fixed;\n  z-index: 2147482100;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n  width: min(1180px, calc(100vw - 48px));\n  height: min(760px, calc(100vh - 48px));\n  display: flex;\n  flex-direction: column;\n  background: var(--be3-bg);\n  color: var(--be3-text);\n  border: 1px solid var(--be3-border-strong);\n  border-radius: var(--be3-r-lg);\n  box-shadow: var(--be3-shadow);\n  font: 13px/1.55 system-ui, -apple-system, \"Segoe UI\", \"Microsoft YaHei\", sans-serif;\n  overflow: hidden;\n}\n.be3-root *,\n.be3-root *::before,\n.be3-root *::after { box-sizing: border-box; }\n\n/* ============================================================================\n * 顶栏\n * ==========================================================================*/\n.be3-topbar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 9px 12px;\n  background: linear-gradient(180deg, #232b34, #1a2028);\n  border-bottom: 1px solid var(--be3-border);\n  flex: 0 0 auto;\n  cursor: grab;\n  user-select: none;\n}\n.be3-app-title { font-weight: 700; font-size: 14px; letter-spacing: .5px; }\n.be3-meta { color: var(--be3-text-muted); font-size: 12px; }\n.be3-meta > b { color: var(--be3-accent); }\n/*\n * ★★★ 第 119 窗口（用户原话）：「我没点进入战斗！」「顶栏高亮就行了。」\n * 🔴 「阶段」这一个词决定了两件玩家看不见的大事：\n *   ① 连击**完全不切组**（显示槽固定「高级」）② 技能只进冷却、不参与连击。\n *   修前它只是个灰色小字，玩家点四个技能打三轮、技能栏纹丝不动，只能来问为什么。\n * ⇒ 未进入战斗时给它一个**醒目的警示徽标**（琥珀色描边 + 轻微脉冲），一眼可见；\n *   进入战斗后变成安静的绿色「战斗中」。\n * ⚠️ 只提示、**不自动改变状态**（用户明确要求：有时要先加载战场再做决策）。\n */\n.be3-phase { padding: 1px 7px; border-radius: 9px; border: 1px solid transparent; white-space: nowrap; }\n.be3-phase.is-alert {\n  color: var(--be3-warn); border-color: var(--be3-warn);\n  background: rgba(224, 169, 92, .12); font-weight: 600;\n  animation: be3-phase-pulse 2s ease-in-out infinite;\n}\n.be3-phase.is-on { color: var(--be3-ok); border-color: rgba(76, 191, 122, .5); background: rgba(76, 191, 122, .10); }\n@keyframes be3-phase-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .62; } }\n/* 尊重「减少动效」偏好（无障碍，且避免低端机一直重绘） */\n@media (prefers-reduced-motion: reduce) { .be3-phase.is-alert { animation: none; } }\n.be3-spacer { flex: 1 1 auto; }\n\n/* 顶栏圆标按钮 */\n.be3-ico {\n  width: 26px; height: 26px;\n  display: inline-flex; align-items: center; justify-content: center;\n  border-radius: 50%; cursor: pointer;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n  font-size: 13px; line-height: 1;\n}\n.be3-ico:hover { color: var(--be3-text); border-color: var(--be3-accent); }\n.be3-ico.is-on { background: var(--be3-accent); border-color: var(--be3-accent); color: #fff; }\n.be3-ico.is-close:hover { border-color: var(--be3-danger); color: var(--be3-danger); }\n\n/* ============================================================================\n * 三栏体\n * ==========================================================================*/\n.be3-body {\n  display: flex;\n  flex: 1 1 auto;\n  min-height: 0;\n}\n.be3-col { display: flex; flex-direction: column; min-height: 0; }\n\n/* 左栏（配置，默认 hidden） */\n.be3-col-left {\n  flex: 0 0 258px;\n  border-right: 1px solid var(--be3-border);\n  background: #171c22;\n  overflow-y: auto;\n}\n.be3-col-left[hidden] { display: none; }\n.be3-side-head {\n  padding: 8px 10px 6px;\n  font-size: 12px; font-weight: 600; color: var(--be3-text);\n  border-bottom: 1px solid var(--be3-border);\n  background: var(--be3-surface-3);\n}\n.be3-side-body { padding: 8px 10px; display: flex; flex-direction: column; gap: 5px; }\n\n/* 中栏（战斗） */\n/* 🔴🔴 中栏卡片的伸缩策略（第 72 窗口 UI 轮，照用户红线）：\n   只有【战场】弹性吃剩余空间；【小队】与【日志】必须固定高度、绝不压缩。\n   修前所有卡默认 `flex: 0 1 auto`（可收缩）⇒ 战场一旦 `flex: 1` 就把它们压成 0。\n   ⚠️ 这正是我上一轮「战场自适应」失败的真实原因（不是上限没给对）。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"party\"],\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"log\"],\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"hud\"] { flex: 0 0 auto; }\n/* 🔴🔴 战场卡**不可收缩**（`flex: 0 0 auto`）：高度由画布的固定 300px 决定。\n   修前这里写 `flex: 1 1 auto` ⇒ 中栏内容超高时 flex 把它从 300 压到 **167px**，\n   而 SVG 仍按 292px 渲染 ⇒ 底部被 `overflow:hidden` 裁掉（单位图标只剩上半身）。\n   ⇒ 超高时让**中栏自己滚**（见 .be3-col-center 的 overflow-y），而不是压内容。\n   这正是用户说的「多的靠滚轮自己去找」。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"field\"] {\n  flex: 0 0 auto; display: block;\n}\n/* 战场卡内部：卡体要能把高度传给画布 */\n/* 战场卡体：正常流式布局即可（画布是固定高度，不需要 flex 传递）。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"field\"] > .be3-card-body {\n  display: block;\n}\n\n.be3-col-center {\n  /* 中栏 : 右栏 = 7 : 3（用户要求）。\n     🔴 `overflow-y: auto` 会让子项的 `flex: 1` **失效**（滚动容器的高度由内容决定）\n     ⇒ 战场想「吃掉剩余空间」就必须用 `min-height: 0` + `overflow: hidden`\n        让中栏成为确定高度的 flex 容器；滚动交给内层（日志卡自己滚）。\n     ⚠️ 这也正是前几轮 `flex: 1 1 auto` 失败的原因之一。 */\n  flex: 7 1 0;\n  min-width: 0;\n  min-height: 0;\n  /* 🔴 超高时**滚动**而不是压缩子项 —— 用户明确说「多的靠滚轮自己去找」。\n     修前 `overflow: hidden` ⇒ 超出的部分直接被裁（看不见也滚不到）。 */\n  overflow-y: auto;\n  gap: 7px;\n  padding: 7px;\n}\n\n/* 右栏（目标/背包/技能/装备/同伴） */\n.be3-col-right {\n  flex: 3 1 0;\n  /* 最小宽度 320px：再窄「目标状态栏 / 背包 / 同伴卡」会挤成一列竖条。\n     比例优先，但保底可读 —— 面板拉到很窄时中栏先让位。 */\n  min-width: 320px;\n  padding: 10px;\n  gap: 10px;\n  border-left: 1px solid var(--be3-border);\n  background: #171c22;\n  overflow-y: auto;\n}\n\n/* ============================================================================\n * 可折叠卡片（照 Stage_1 `.be-card` 的规格）\n * ==========================================================================*/\n.be3-card {\n  background: var(--be3-surface-2);\n  border: 1px solid var(--be3-border);\n  border-radius: var(--be3-r-md);\n  overflow: hidden;\n  flex: 0 0 auto;\n}\n.be3-card-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  /* 🔴 padding 7 → 4：中栏 4 张卡 ⇒ 省 ~24px，全给战场。\n     卡头只是标题条，不需要 7px 上下留白。 */\n  padding: 4px 10px;\n  background: var(--be3-surface-3);\n  border-bottom: 1px solid var(--be3-border);\n  cursor: pointer;\n  user-select: none;\n}\n.be3-card-head:hover { background: #232b36; }\n.be3-card-icon { font-size: 13px; }\n.be3-card-title { font-weight: 600; font-size: 12.5px; }\n.be3-card-sub {\n  font-size: 11px; color: var(--be3-text-muted);\n  font-variant-numeric: tabular-nums;\n}\n.be3-card-arrow { color: var(--be3-text-muted); font-size: 11px; }\n/* 🔴 卡片体 padding 9 → 7：中栏 4 张卡 ⇒ 省 ~16px。 */\n.be3-card-body { padding: 7px 9px; }\n/* 画布卡的卡体作为工具条的定位锚点（工具条绝对定位到画布左下角）。 */\n/* 画布卡的卡体：定位锚点 + 可伸缩（把可用高度传给画布）。 */\n/* 画布卡的卡体：定位锚点（工具条绝对定位用），**不参与 flex 增长**。 */\n.be3-card-body:has(> .be3-canvas) {\n  position: relative;\n}\n/* 折叠：Head 保留、Body 不占位 */\n.be3-card.is-collapsed .be3-card-body { display: none; }\n.be3-card.is-collapsed .be3-card-head { border-bottom: none; }\n\n/* ============================================================================\n * 中栏：HUD / 小队 / 日志\n * ==========================================================================*/\n.be3-hud-row { display: flex; gap: 7px; overflow-x: auto; padding-bottom: 2px; }\n.be3-hud {\n  flex: 0 0 auto; min-width: 96px;\n  display: flex; flex-direction: column; gap: 3px;\n  padding: 6px 8px;\n  background: var(--be3-surface);\n  color: var(--be3-text);\n  border: 1px solid var(--be3-border);\n  border-left: 3px solid var(--be3-enemy);\n  border-radius: 6px;\n  cursor: pointer;\n  text-align: left;\n}\n.be3-hud:hover { border-color: var(--be3-border-strong); }\n.be3-hud.is-focus {\n  border-color: var(--be3-accent);\n  box-shadow: inset 0 0 0 1px var(--be3-accent);\n}\n.be3-hud-name {\n  font-size: 12px; font-weight: 600;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-hud-hp {\n  display: block; height: 4px; border-radius: 2px;\n  background: var(--be3-bg); overflow: hidden;\n}\n.be3-hud-hp > i { display: block; height: 100%; background: var(--be3-enemy); }\n.be3-hud-num {\n  font-size: 10px; color: var(--be3-text-muted);\n  font-variant-numeric: tabular-nums;\n}\n.be3-hud-dist { font-size: 10px; color: var(--be3-accent); }\n\n/* ⚠️ 这里曾有一份**旧的小队样式**（flex + 104px 固定宽 + 省略号名字），\n   与文件后半「小队：等宽三格 + 大头像」重复定义。CSS 后者胜 ⇒ 旧块本身不生效，\n   但会被「读源码找规则」的判据先命中，也让后来改样式的人改错地方\n   （本文件第 226 行那条注释记过同一个坑：重复定义 ⇒「改了没效果」）。\n   ⇒ 已删除。小队样式**只改后半那一处**。 */\n\n/* ------------------------------------------------ 回合日志（五类 + 筛选页签）\n *\n * ★★ 第 70 窗口（功能 B）：这里是**唯一**的日志样式定义。\n * 🔴 修前 `.be3-log` / `.be3-log-line` 有**两份**（此处 + 约 490 行处），\n *   后者覆盖前者 ⇒ 改第一份「改了没效果」，是最难查的一类假成功。\n *   ⇒ 重复的那份已删掉，改日志样式只改这一处。\n *\n * 五类着色对应 kind：narrative(正文) / aside(旁白) / skill(技能) /\n * resource(资源) / system(系统)。\n * ⚠️ 正文给 accent 色 —— 它是结算的主产物（与 Stage_1 的「一等公民」同口径）；\n *   旁白用斜体 + muted：读得出是「描绘」，但一眼看得出不是正文。\n */\n.be3-log {\n  display: flex; flex-direction: column; gap: 4px;\n  font-size: 11px; max-height: 216px; overflow-y: auto;\n}\n.be3-log-line { font-size: 11px; color: var(--be3-text-muted); }\n.be3-log-line.is-narrative { color: var(--be3-accent); }\n.be3-log-line.is-aside { color: var(--be3-text-muted); font-style: italic; }\n.be3-log-line.is-skill { color: var(--be3-accent); }\n.be3-log-line.is-resource { color: var(--be3-warn); }\n.be3-log-line.is-system { color: var(--be3-text-muted); opacity: .85; }\n/*\n * ★★★ 第 121 窗口（用户要求）：【原始回复】—— 排查对照用的原文。\n * 🔴 必须 `pre-wrap`：`<BattleState>` 与段落分界全靠换行表达，\n *   折成一长条就没法跟「面板读到了什么」逐行对照了。\n * ⚠️ 限高 + 内部滚动：单轮可能 3000+ 字，不限高会把整张卡撑爆。\n */\n.be3-log-line.is-raw {\n  color: var(--be3-text); white-space: pre-wrap; word-break: break-word;\n  background: var(--be3-surface-2); border-left: 2px solid var(--be3-warn);\n  padding: 4px 6px; border-radius: 0 4px 4px 0;\n  max-height: 220px; overflow-y: auto; font-family: ui-monospace, Consolas, monospace;\n}\n.be3-log-rawtag {\n  font-family: system-ui, -apple-system, \"Microsoft YaHei\", sans-serif;\n  font-size: 10px; color: var(--be3-warn); margin-bottom: 3px; font-weight: 600;\n}\n\n/**\n * ★★★ 第 122 窗口：【思维链】—— 与 `is-raw` 同一套排版（`pre-wrap` + 限高滚动），\n * 只换配色与左边框（青蓝系），让玩家一眼分清「原文」与「推演过程」。\n * 🔴 为什么也要 `pre-wrap`：草稿是「① ② ③」逐行写的，\n *   折成一长条就**没法核对**它有没有算持续效果 —— 那正是这个页签存在的理由。\n */\n.be3-log-line.is-cot {\n  color: var(--be3-text); white-space: pre-wrap; word-break: break-word;\n  background: var(--be3-surface-2); border-left: 2px solid var(--be3-accent);\n  padding: 4px 6px; border-radius: 0 4px 4px 0;\n  max-height: 220px; overflow-y: auto; font-family: ui-monospace, Consolas, monospace;\n  opacity: .92;\n}\n.be3-log-line.is-cot .be3-log-rawtag { color: var(--be3-accent); }\n\n/* 筛选页签（挂在卡片头右槽） */\n.be3-log-filter { display: inline-flex; gap: 2px; flex-wrap: wrap; justify-content: flex-end; }\n.be3-log-tab {\n  font-size: 10px; padding: 1px 6px; border-radius: 8px; cursor: pointer;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-border);\n  color: var(--be3-text-muted);\n}\n.be3-log-tab i { font-style: normal; margin-left: 3px; opacity: .7; }\n.be3-log-tab.is-active { border-color: var(--be3-accent); color: var(--be3-accent); }\n\n/* ============================================================================\n * 底部回合条\n * ==========================================================================*/\n.be3-usage {\n  display: flex; align-items: center; gap: 7px;\n  flex: 0 0 auto;\n  padding: 5px 12px 6px;\n  background: #10141a;\n  border-top: 1px solid var(--be3-border);\n  overflow-x: auto;\n}\n.be3-usage-label { font-size: 11px; color: var(--be3-text-muted); }\n.be3-usage-chip {\n  font-size: 11px; padding: 0 7px; border-radius: 9px;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-accent);\n  color: var(--be3-accent);\n}\n.be3-rounds { display: flex; gap: 4px; overflow-x: auto; max-width: 40%; }\n.be3-round-chip {\n  padding: 1px 6px; border-radius: 8px; font-size: 11px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n}\n.be3-round-chip.is-current { background: var(--be3-accent); color: #fff; }\n\n/* ============================================================================\n * 通用控件\n * ==========================================================================*/\n.be3-btn {\n  padding: 3px 10px; border-radius: 6px; cursor: pointer;\n  background: var(--be3-surface-2); color: var(--be3-text);\n  border: 1px solid var(--be3-border); font-size: 12px;\n  white-space: nowrap;\n}\n.be3-btn:hover:not([disabled]) { border-color: var(--be3-accent); }\n.be3-btn.is-primary { background: var(--be3-accent); border-color: var(--be3-accent); color: #fff; }\n.be3-btn.is-mini { padding: 1px 8px; font-size: 11.5px; }\n.be3-btn[disabled] { opacity: .4; cursor: not-allowed; }\n\n.be3-sec-title {\n  font-size: 11px; letter-spacing: 1px; color: var(--be3-text-muted);\n  margin-top: 2px;\n}\n.be3-dim { color: var(--be3-text-muted); }\n.be3-warn { color: var(--be3-warn); }\n.be3-empty { font-size: 12px; color: var(--be3-text-muted); padding: 10px; text-align: center; }\n\n/* ============================================================================\n * 单位卡\n * ==========================================================================*/\n.be3-unit {\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n  border-left: 3px solid var(--be3-border);\n  border-radius: 8px; padding: 7px 9px;\n}\n.be3-kind-self { border-left-color: var(--be3-self); }\n.be3-kind-ally, .be3-kind-summon { border-left-color: var(--be3-ally); }\n.be3-kind-enemy { border-left-color: var(--be3-enemy); }\n.be3-unit.is-pending { box-shadow: inset 0 0 0 1px var(--be3-warn); }\n\n.be3-unit-head { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-kind { font-size: 10px; padding: 0 5px; border-radius: 4px; background: var(--be3-surface-2); color: var(--be3-text-muted); }\n.be3-name { font-size: 14px; }\n.be3-lv, .be3-rank { font-size: 11px; color: var(--be3-text-muted); }\n.be3-flag { font-size: 10px; color: var(--be3-warn); border: 1px solid var(--be3-warn); border-radius: 4px; padding: 0 4px; }\n\n.be3-hp-row { display: flex; align-items: center; gap: 8px; margin: 5px 0 4px; }\n.be3-hp-bar { flex: 1 1 auto; height: 7px; background: var(--be3-surface-2); border-radius: 4px; overflow: hidden; }\n.be3-hp-bar > i { display: block; height: 100%; background: var(--be3-ok); transition: width .18s; }\n.be3-hp-bar > i.is-low { background: var(--be3-warn); }\n.be3-hp-bar > i.is-critical { background: var(--be3-danger); }\n.be3-hp-text { font-variant-numeric: tabular-nums; font-size: 12px; white-space: nowrap; }\n.be3-hp-text b { color: var(--be3-ok); }\n.be3-temp { color: var(--be3-accent); font-style: normal; font-size: 11px; }\n\n.be3-chips { display: flex; flex-wrap: wrap; gap: 4px; }\n.be3-chip {\n  font-size: 11px; padding: 0 6px; border-radius: 9px;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-border);\n}\n.be3-chip > i { font-style: normal; color: var(--be3-warn); margin-left: 3px; }\n.be3-chip.is-dist { border-color: var(--be3-accent); color: var(--be3-accent); }\n.be3-chip.is-ac { border-color: var(--be3-ok); }\n.be3-chip.is-ac > i { color: var(--be3-text-muted); font-style: normal; margin-left: 4px; font-size: 10px; }\n\n.be3-meta { font-size: 11px; color: var(--be3-text-muted); margin-top: 3px; }\n\n/* ============================================================================\n * 主角卡（右栏「目标状态栏」内，照 Stage_1 renderActorPanel 的层级）\n * ==========================================================================*/\n.be3-selfcard { display: flex; flex-direction: column; gap: 8px; }\n.be3-selfcard.is-empty { padding: 16px; text-align: center; color: var(--be3-text-muted); font-size: 12px; }\n.be3-ident { display: flex; align-items: baseline; gap: 8px; }\n.be3-ident-name { font-size: 17px; letter-spacing: .5px; }\n.be3-ident-sub { font-size: 11px; color: var(--be3-text-muted); }\n\n.be3-hpbar { display: flex; align-items: center; gap: 10px; }\n.be3-hpbar-bg {\n  flex: 1 1 auto; height: 13px; border-radius: 7px;\n  background: var(--be3-surface); overflow: hidden;\n  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .4);\n}\n.be3-hpbar-bg > i {\n  display: block; height: 100%;\n  background: linear-gradient(180deg, #5fd08a, var(--be3-ok));\n  transition: width .22s;\n}\n.be3-hpbar-bg > i.is-low { background: linear-gradient(180deg, #f0c070, var(--be3-warn)); }\n.be3-hpbar-bg > i.is-critical { background: linear-gradient(180deg, #f08080, var(--be3-danger)); }\n.be3-hpbar-text {\n  display: flex; align-items: baseline; gap: 5px;\n  font-size: 13px; white-space: nowrap; font-variant-numeric: tabular-nums;\n}\n.be3-hpbar-text b { font-size: 19px; color: var(--be3-ok); line-height: 1; }\n.be3-hpbar-text > span { color: var(--be3-text-muted); font-size: 12px; }\n.be3-ac {\n  margin-left: 6px; padding: 0 6px; border-radius: 4px; font-size: 11px;\n  background: var(--be3-surface); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n}\n.be3-attrs { display: flex; gap: 10px; flex-wrap: wrap; }\n.be3-attr { display: flex; align-items: baseline; gap: 3px; font-size: 11px; }\n.be3-attr > i { font-style: normal; color: var(--be3-text-muted); }\n.be3-attr > b { color: var(--be3-text); font-variant-numeric: tabular-nums; }\n\n/* ============================================================\n * 区块样式（参考名单 / 技能栏 / 画布 / 背包 / 装备 / 资源）\n * 这些区块本身没变，只是外面换了壳（三栏 + 折叠卡）。\n * ============================================================*/\n/* ============================================================================\n * 头像（预设表查图；查不到 ⇒ 首字占位）\n * ----------------------------------------------------------------------------\n * 🔴 尺寸分档位（`.is-lg/.is-md/.is-sm`），**不在渲染层写死内联宽高**：\n *   面板能被拖动缩放，档位只有 CSS 知道；写死宽高会在拉窄后把格子撑破。\n *   · 状态栏：lg 84×96 / md 64×74 / sm 40×40（用户给的规格）\n *   · HUD 横排卡与小队格：40×40（横向空间紧，再大就把名字挤掉）\n * ⚠️ `object-fit: cover` 是必须的：源图比例不统一，`fill` 会把脸拉扁。\n * ==========================================================================*/\n.be3-avatar {\n  flex: 0 0 auto;\n  display: inline-flex; align-items: center; justify-content: center;\n  overflow: hidden; border-radius: 6px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n  font-size: 13px; font-weight: 600; user-select: none;\n}\n.be3-avatar > img { width: 100%; height: 100%; object-fit: cover; display: block; }\n/* 🔴 占位（预设表没收录这个角色）**必须一眼看出是「没有图」而不是「图裂了」**：\n   实线边框 + 大字首字会被误读成「加载失败的图片」。\n   ⇒ 虚线边框 + 半透明底 + 首字，与真图在视觉上明确区分。\n   ⚠️ 这不是审美：玩家看到「方框里一个字」时会以为面板坏了，\n      而它其实是「这个 NPC 不在预设表里」的正常降级。 */\n.be3-avatar.is-ph {\n  border-style: dashed;\n  background: repeating-linear-gradient(45deg, var(--be3-surface-2), var(--be3-surface-2) 4px, var(--be3-bg) 4px, var(--be3-bg) 8px);\n  color: var(--be3-text-muted);\n}\n\n/* ---- 尺寸：`size` 参数（lg/md/sm）驱动，`data-be3-size` 档位再覆盖 ---- */\n.be3-avatar.is-lg { width: 84px; height: 96px; font-size: 26px; }\n.be3-avatar.is-md { width: 64px; height: 74px; font-size: 20px; }\n.be3-avatar.is-sm { width: 40px; height: 40px; font-size: 15px; }\n/* 🔴 小队格的头像**不受上面三档约束**（它要满宽）⇒ 显式盖回 auto。\n   放在这组规则**之后**，同权重下后者胜；不写这一条的话\n   `is-lg`(84×96) 会把满宽头像压回 84px 宽。 */\n.be3-sq-portrait .be3-avatar { width: 100%; height: auto; }\n/* HUD 横排卡：横向空间紧，一律 40×40（不看 size 参数）。\n   🔴 `is-squad` **已从这条规则里摘出**（第 72 窗口 UI 轮）：\n      小队格的头像现在要**铺满卡片宽度**，尺寸由 `.be3-sq-portrait` 那组规则决定\n      （见文件后面的「小队：大头像」小节）。留在这里会被这条 40×40 覆盖回去，\n      而\"覆盖\"不会报错 —— 这正是「头像很小」那个问题的成因。 */\n.be3-avatar.is-hud { width: 40px; height: 40px; font-size: 15px; }\n.be3-hud .be3-avatar.is-hud { margin-bottom: 2px; }\n.be3-avatar.is-status { border-radius: 8px; }\n\n/* 尺寸档位：面板拉窄时状态栏头像缩一档（与 float-window 的 data-be3-size 对齐） */\n.be3-root[data-be3-size=\"mid\"] .be3-avatar.is-status { width: 64px; height: 74px; font-size: 20px; }\n.be3-root[data-be3-size=\"narrow\"] .be3-avatar.is-status { width: 64px; height: 74px; font-size: 20px; }\n.be3-root[data-be3-size=\"tiny\"] .be3-avatar.is-status { width: 40px; height: 40px; font-size: 15px; }\n\n/* ---------------- 参考名单 ---------------- */\n.be3-refwrap { display: flex; flex-direction: column; gap: 6px; }\n.be3-refhead { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-refgroup { display: flex; flex-direction: column; gap: 5px; }\n.be3-ref {\n  display: flex; align-items: center; gap: 7px; font-size: 12px;\n  padding: 3px 7px; border-radius: 6px;\n  background: var(--be3-surface); border: 1px solid transparent;\n}\n.be3-ref.is-on { border-color: var(--be3-accent); background: var(--be3-surface-2); }\n.be3-ref-chk {\n  width: 16px; height: 16px; flex: 0 0 auto; padding: 0; line-height: 14px;\n  font-size: 11px; cursor: pointer; border-radius: 4px;\n  background: var(--be3-bg); color: var(--be3-ok);\n  border: 1px solid var(--be3-border);\n}\n.be3-ref-chk.is-on { border-color: var(--be3-ok); }\n.be3-ref-name { font-size: 12px; }\n\n/* ============================================================================\n * 参考名单：**卡片式列表**（第 72 窗口 UI 轮，照用户线框图）\n *\n * 每人一块卡：头像 / 名字 / LV·种族·性别 / 徽章 / 勾选框\n *             → HP条 + AC + 攻击 + ♥好感 + SAN\n *             → 六维 → 六个战斗小方块 → 位置 → 装备 → 技能\n *\n * 🔴 列表本身**内部滚动**（`max-height` + `overflow-y:auto`）：\n *   11 个人 × 每块约 150px = 1650px，不滚会把右栏撑成一条长卷。\n *   滚动容器带 `data-be3-scroll=\"ref\"` 才能被 `scroll-keep.js` 找回位置。\n * ==========================================================================*/\n.be3-refc-list {\n  display: flex; flex-direction: column; gap: 7px;\n  max-height: 430px;                 /* 约 3 块卡，再多就滚 */\n  overflow-y: auto; overflow-x: hidden;\n  padding-right: 2px;\n}\n.be3-refgroup-head {\n  font-size: 11px; color: var(--be3-text-muted);\n  padding: 2px 0 1px; border-bottom: 1px dashed var(--be3-border);\n}\n.be3-refc {\n  display: flex; flex-direction: column; gap: 4px;\n  padding: 6px 7px; border-radius: 7px;\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n}\n.be3-refc.is-on { border-color: var(--be3-accent); background: var(--be3-surface-2); }\n\n/* ① 头：头像 + 名字/副标题 + 徽章 + 勾选框 */\n.be3-refc-head { display: flex; align-items: center; gap: 7px; }\n.be3-refc-id { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1 1 auto; }\n.be3-refc-name { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.be3-refc-sub { font-size: 11px; color: var(--be3-text-muted); }\n.be3-refc-tags { display: flex; gap: 3px; flex: 0 0 auto; flex-wrap: wrap; justify-content: flex-end; }\n.be3-refc-badge {\n  font-size: 10px; padding: 1px 5px; border-radius: 8px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n}\n.be3-refc-badge.is-bond { color: var(--be3-accent); border-color: var(--be3-accent); }\n.be3-refc-badge.is-near { color: var(--be3-ok); border-color: var(--be3-ok); }\n.be3-refc-badge.is-unknown { opacity: .7; }\n\n/* ② 资源窄行：HP条 + HP/AC/攻击/♥/SAN */\n.be3-refc-vitals { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 11px; }\n.be3-refc-hpbar {\n  flex: 1 1 60px; min-width: 50px; height: 5px; border-radius: 3px;\n  background: var(--be3-bg); overflow: hidden;\n}\n.be3-refc-hpbar > i { display: block; height: 100%; background: var(--be3-ok); }\n.be3-refc-vnum { color: var(--be3-text-muted); font-variant-numeric: tabular-nums; }\n\n/* ③ 六维单行 */\n.be3-refc-attrs { display: flex; gap: 8px; flex-wrap: wrap; font-size: 11px; }\n.be3-refc-attr { display: inline-flex; align-items: baseline; gap: 3px; }\n.be3-refc-attr > i { font-style: normal; color: var(--be3-text-muted); font-size: 10px; }\n.be3-refc-attr > b { font-variant-numeric: tabular-nums; }\n\n/* ④ 六个战斗小方块（与队友卡同一套口径：攻/AVG/暴伤/暴击/物减/魔减） */\n.be3-refc-combat { display: flex; gap: 3px; flex-wrap: wrap; }\n.be3-refc-chip {\n  display: inline-flex; align-items: baseline; gap: 3px;\n  padding: 1px 5px; border-radius: 5px; font-size: 10px;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-border);\n}\n.be3-refc-chip > i { font-style: normal; color: var(--be3-text-muted); }\n.be3-refc-chip > b { font-variant-numeric: tabular-nums; }\n\n/* ⑤ 位置 / 装备 / 技能 行 */\n.be3-refc-line { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; font-size: 11px; }\n.be3-refc-line > i {\n  font-style: normal; color: var(--be3-text-muted);\n  flex: 0 0 auto; font-size: 10px; min-width: 22px;\n}\n.be3-refc-tag {\n  padding: 1px 5px; border-radius: 5px; font-size: 10px;\n  background: var(--be3-bg); border: 1px solid var(--be3-border);\n  color: var(--be3-text);\n}\n.be3-refc-tag.is-skill { border-color: var(--be3-accent); }\n.be3-round-chip {\n  padding: 1px 6px; border-radius: 8px; font-size: 11px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n}\n.be3-round-chip.is-current { background: var(--be3-accent); color: #fff; }\n\n.be3-btn {\n  padding: 3px 10px; border-radius: 6px; cursor: pointer;\n  background: var(--be3-surface-2); color: var(--be3-text);\n  border: 1px solid var(--be3-border); font-size: 12px;\n}\n.be3-btn:hover { border-color: var(--be3-accent); }\n.be3-btn.is-primary { background: var(--be3-accent); border-color: var(--be3-accent); color: #fff; }\n.be3-btn.is-danger:hover { border-color: var(--be3-danger); color: var(--be3-danger); }\n\n/* ⚠️ 这里曾有旧的两栏骨架遗留（`.be3-body` 全量定义 + `.be3-col { flex: 1 1 50% }`），与第 96/104/120/128 行的三栏正式定义**重复**。\n   `flex: 1 1 50%` 会给未显式设宽的列一个 50% 基准 ⇒ 与「中栏:右栏 = 7:3」打架（且不报错，只是比例悄悄不对）。⇒ 已删除，栏宽**只改上面那一处**。 */\n.be3-sec-title {\n  font-size: 11px; letter-spacing: 1px; color: var(--be3-text-muted);\n  border-bottom: 1px solid var(--be3-border); padding-bottom: 3px; margin-top: 4px;\n}\n\n.be3-unit {\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n  border-left: 3px solid var(--be3-border);\n  border-radius: 8px; padding: 7px 9px;\n}\n.be3-kind-self { border-left-color: var(--be3-self); }\n.be3-kind-ally, .be3-kind-summon { border-left-color: var(--be3-ally); }\n.be3-kind-enemy { border-left-color: var(--be3-enemy); }\n.be3-unit.is-pending { box-shadow: inset 0 0 0 1px var(--be3-warn); }\n\n.be3-unit-head { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-kind { font-size: 10px; padding: 0 5px; border-radius: 4px; background: var(--be3-surface-2); color: var(--be3-text-muted); }\n.be3-name { font-size: 14px; }\n.be3-lv, .be3-rank { font-size: 11px; color: var(--be3-text-muted); }\n.be3-flag { font-size: 10px; color: var(--be3-warn); border: 1px solid var(--be3-warn); border-radius: 4px; padding: 0 4px; }\n\n.be3-hp-row { display: flex; align-items: center; gap: 8px; margin: 5px 0 4px; }\n.be3-hp-bar { flex: 1 1 auto; height: 7px; background: var(--be3-surface-2); border-radius: 4px; overflow: hidden; }\n.be3-hp-bar > i { display: block; height: 100%; background: var(--be3-ok); transition: width .18s; }\n.be3-hp-bar > i.is-low { background: var(--be3-warn); }\n.be3-hp-bar > i.is-critical { background: var(--be3-danger); }\n.be3-hp-text { font-variant-numeric: tabular-nums; font-size: 12px; white-space: nowrap; }\n.be3-hp-text b { color: var(--be3-ok); }\n.be3-temp { color: var(--be3-accent); font-style: normal; font-size: 11px; }\n\n.be3-chips { display: flex; flex-wrap: wrap; gap: 4px; }\n.be3-chip {\n  font-size: 11px; padding: 0 6px; border-radius: 9px;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-border);\n}\n.be3-chip > i { font-style: normal; color: var(--be3-warn); margin-left: 3px; }\n.be3-chip.is-dist { border-color: var(--be3-accent); color: var(--be3-accent); }\n\n.be3-meta { font-size: 11px; color: var(--be3-text-muted); margin-top: 3px; }\n.be3-dim { color: var(--be3-text-muted); }\n.be3-empty { font-size: 12px; color: var(--be3-text-muted); padding: 8px; text-align: center; }\n\n.be3-field {\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n  border-radius: 8px; padding: 6px 9px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px;\n}\n.be3-glyph { font-size: 16px; }\n.be3-dur { font-size: 11px; color: var(--be3-warn); margin-left: auto; }\n\n/* ⚠️ `.be3-log` / `.be3-log-line` 的样式**只在上面「回合日志（五类 + 筛选页签）」那一节**。\n   修前这里还有一份重复定义（`font-size` / `max-height:220px` / `.is-system`），\n   它会覆盖上面那份 ⇒ 改上面「改了没效果」。已删除，不要再加回来。 */\n.be3-matrix-line { font-size: 11px; padding: 2px 0; }\n\n/* ---------------- 技能栏（6+3） ---------------- */\n.be3-skillbar {\n  background: var(--be3-surface);\n  border: 1px solid var(--be3-border);\n  border-radius: 8px;\n  padding: 7px 9px;\n}\n.be3-skillbar-head { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }\n.be3-group, .be3-display {\n  font-size: 10px; padding: 0 5px; border-radius: 4px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n}\n.be3-group { color: var(--be3-accent); }\n.be3-skill-row { display: flex; gap: 4px; margin-top: 4px; }\n.be3-skill {\n  position: relative;                 /* 等级徽标绝对定位靠它 */\n  flex: 1 1 0; min-width: 0; height: 40px;\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 1px; padding: 2px;\n  background: var(--be3-surface-2);\n  border: 1px solid var(--be3-border);\n  border-radius: 6px;\n  color: var(--be3-text);\n  cursor: pointer; font-size: 11px;\n  overflow: hidden;\n}\n.be3-skill.is-adv { border-color: var(--be3-accent); }\n.be3-skill:hover:not(.is-empty) { border-color: var(--be3-text); }\n.be3-skill.is-empty { opacity: .25; cursor: default; }\n.be3-skill.is-cooling {\n  opacity: .55; cursor: not-allowed;\n  background: repeating-linear-gradient(45deg, var(--be3-surface-2), var(--be3-surface-2) 4px, var(--be3-bg) 4px, var(--be3-bg) 8px);\n}\n.be3-skill.is-used { outline: 1px solid var(--be3-ok); }\n.be3-skill-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }\n.be3-skill-cd { font-size: 10px; color: var(--be3-warn); font-variant-numeric: tabular-nums; }\n.be3-skill-cd.is-ok { color: var(--be3-ok); }\n/* 等级徽标：显示的是**有效等级**（裸 + 装备阶位加成）。\n   🔴 封顶用不同颜色标出来 —— 否则「Lv.3」看起来像「还没练满」，\n      而它其实是「再练也不会涨」（觉醒系上限 3）。\n   🔴 为什么绝对定位到**右上角**而不是留在流里（截图逼出来的）：\n      格子只有 40px 高、三样东西（名字 / 等级 / 冷却）竖排时，\n      第三样会被 `overflow:hidden` 裁掉一半 —— 而「元素存在、innerText 正常」\n      的判据**全部通过**（Stage_1 的网格文字消失是同一类：只能靠截图发现）。\n      角标只吃角落那一点空间，名字仍占满宽度。 */\n.be3-skill-lv {\n  position: absolute; top: 1px; right: 2px;\n  font-size: 9.5px; line-height: 1.25; padding: 0 3px; border-radius: 7px;\n  background: var(--be3-bg); color: var(--be3-accent);\n  font-variant-numeric: tabular-nums;\n}\n.be3-skill-lv.is-capped { color: var(--be3-warn); background: rgba(224, 169, 92, .16); }\n/* 冷却计数留在流里、贴在名字下面；名字要给它让出高度（否则两者重叠） */\n.be3-skill-name { max-height: 13px; }\n\n/* 觉醒槽：与 6+3 视觉上要能一眼区分（紫边、不参与连击） */\n.be3-skillbar.is-awk { border-color: var(--be3-summon); }\n.be3-skill.is-awk { border-color: var(--be3-summon); }\n.be3-skill.is-awk:hover:not(.is-empty) { border-color: var(--be3-text); }\n.be3-skill-row.is-awk .be3-skill { flex: 0 1 25%; }\n\n/* ============================================================================\n * ★★ 第 77 窗口：本段**整段替换**（旧的三段：第 74 窗口「主图+右侧两清单」、\n *   第 75 窗口「宽扁 + 角部浮层」、第 76 窗口「flex 兄弟项 + 负 margin」）。\n *   ⚠️ 旧那三段**不是叠加**，而是同一个容器结构的三次修订 —— 留着它们会让\n *   「同一属性多处定义」（第 73 窗口 10 轮里 5 轮的根因，改一处不生效）。\n * ==========================================================================*/\n/* ============================================================================\n * 战场画布 · 第 77 窗口 **整体重写**（照 Stage_1 的「三层 + 一个变换层」）\n * ----------------------------------------------------------------------------\n * 用户原话：\n *   「这跟 Stage_1 的 preview.html 效果还是有差距。…… 基于我们 Stage_3 的项目结构\n *     进行还原复刻，用于指导未来窗口。只做战场和地图绘制效果。」\n *   「北墙 / 石屋 / 小河 / 瓦砾堆 / 篝火圈渲染出来内部都有一个圈，很丑很难看。」\n *   「战场右上角持续效果/天气的图标样式也不好看。」\n * 参照物：`Stage_1/src/ui/styles.css`（`.be-fieldmap` / `.be-zone-*` / `.be-field-*`）\n *        与 `Stage_1/drawing-reference/css/*`（可直接抄的切片）。\n *\n * 🔴🔴 结构（**与渲染层逐层对应，改一处要改两处**）：\n *   .be3-canvas                 外层（边框 + 高度 + 脚部计数）\n *     .be3-map-body             只剩一行\n *       .be3-fieldmap           ★ 裁剪框（overflow:hidden，定位参照）\n *         .be3-field-viewport   ★ 变换层（translate + scale —— **唯一**施加 zoom 的层）\n *           .be3-zone-layer       区块（SVG，最底：它是「地面」）\n *           .be3-range-layer      效果范围（div 圆 + 圆心图标）\n *           .be3-scene-layer      建筑/道具 emoji 点阵\n *           .be3-measure-layer    距离连线（默认空）\n *           .be3-token-layer      单位圆点（永远最上、永远可点）\n *         .be3-map-side         角部浮层（右上效果图标 / 右下区块清单）—— **不随缩放**\n *         .be3-map-zoom         左下控件 —— 不随缩放\n *         .be3-mapd             详情浮层 —— 不随缩放\n *\n * 🔴 为什么必须多一个 `.be3-field-viewport`（Stage_1 的原话，别省掉）：\n *   内容元素各自的 `transform` 是 `translate(-50%,-50%)`（把自己对到锚点上）。\n *   若把 `scale(zoom)` 也写在它们身上，两者会以**各自的 transform-origin** 复合\n *   ⇒ 位置全乱。用一个独立的变换层，就把「视口变换」与「元素自身定位」彻底分开。\n *\n * 🔴 图层顺序 = 命中优先级：\n *   区块层 `pointer-events: none`（它是地面，不吃点击 —— 用户：「不可在地图上点击互动」）\n *   建筑/道具层 `none`（容器不吃）但**每个 emoji 点 `none`**、只有**对象标签**吃\n *   token 层 `none` 但 token 自己 `auto`（单位永远可点）。\n *   ⚠️ 「铺满型容器绝不能 auto」—— 否则地图空白处全点不动（Stage_1 P91 同型）。\n * ==========================================================================*/\n\n.be3-canvas {\n  position: relative;\n  background: radial-gradient(circle at 50% 50%, #1a2029 0%, var(--be3-bg) 72%);\n  border: 1px solid var(--be3-border);\n  border-radius: 8px;\n  padding: 4px;\n  overflow: hidden;\n  /* 🔴 高度 **300px**（用户第 74 窗口原话「画布确实继续加高」）。\n     ⚠️ 与 Stage_1 的 `aspect-ratio: 5/2` 不同 —— 那是 Stage_1 按栏宽自适应；\n        我们按用户拍板保留定高，宽高比由 `canvas-drag` 量出来回写几何层\n        （`runner.setCanvasAspect`），所以**这里不要**写 aspect-ratio，\n        否则两个来源打架（第 75 窗口踩过）。 */\n  height: 300px;\n  flex: 0 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n.be3-canvas.is-empty {\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; color: var(--be3-text-muted); text-align: center; padding: 12px;\n}\n/* 主图区：吃满整宽（角部浮层是**绝对定位**盖在它上面的，不占列宽） */\n.be3-map-body {\n  position: relative;\n  flex: 1 1 auto;\n  min-height: 0;\n  display: flex;\n  align-items: stretch;\n}\n\n/* ★★ 裁剪框（Stage_1 的 `.be-fieldmap`）：\n *   底色 = **28px 网格 + 底部辉光**。这两条是 Stage_1 观感的底座：\n *   网格让「距离/方位」有参照，底部径向渐变让画面重心下沉（像「地面」而不是一张纸）。\n *   ⚠️ 网格尺寸 28px 与 Stage_1 逐字一致（`drawing-reference/css/00-tokens.css`）。 */\n.be3-fieldmap {\n  position: relative;\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  /* ★★ 第 81 窗口：默认**不是 grab** —— 完整适配时画布拖不动（与 Stage_1 一致），\n     光标必须如实反映这一点。能拖时由 `.is-pannable` 切回 grab（见下面那条）。 */\n  cursor: default;\n  background:\n    linear-gradient(rgba(111, 168, 220, .05) 1px, transparent 1px) 0 0 / 100% 28px,\n    linear-gradient(90deg, rgba(111, 168, 220, .05) 1px, transparent 1px) 0 0 / 28px 100%,\n    radial-gradient(ellipse at 50% 100%, #1d2530, #0e1217 72%);\n  border: 1px solid var(--be3-border);\n  border-radius: 6px;\n}\n/* ★★ 变换层：`transform` 由渲染层内联写（`translate(x%,y%) scale(z)`），\n *   这里只给 `transform-origin`（默认 50% 50% 正是几何层 panLimit 的推导前提）。\n * 🔴 **不要**在这里再加 `scale(var(--be3-ico))` —— 图标反向缩放只施加一次，\n *   施加点是下面各图层的 `calc(基准px * var(--be3-ico))`（布局式）。 */\n.be3-field-viewport {\n  position: absolute;\n  inset: 0;\n  transform-origin: 50% 50%;\n  transition: transform .14s ease-out;\n  /* ★ 图标反向缩放系数的兜底值：渲染层没注入时退化成「不缩放」\n     （与「没有这个功能」等价，不会算成 0 把图标抹掉）。 */\n  --be3-ico: 1;\n}\n/* 拖拽中关掉过渡（否则「跟手迟滞」，Stage_1 的 `.is-panning` 同款） */\n.be3-fieldmap.is-panning .be3-field-viewport { transition: none; }\n/* ★★ 第 81 窗口：**「能不能拖」必须看出来**。\n *   用户拍板「放大后才能拖」⇒ 完整适配时如果仍是 grab 手型光标，\n *   玩家按下去一动不动就是「坏了」（第 78 窗口 `.be3-node` 那条 disabled 注释同型）。\n *   基础规则已经是 `cursor: default`，这里只在能拖时切 grab —— 两处一改一读，不会打架。 */\n.be3-fieldmap.is-pannable { cursor: grab; }\n.be3-fieldmap.is-panning { cursor: grabbing; }\n\n/* 五个图层：都铺满视口、都不吃事件（事件由各自的内容元素单独接管） */\n.be3-zone-layer,\n.be3-range-layer,\n.be3-scene-layer,\n.be3-measure-layer,\n.be3-token-layer {\n  position: absolute;\n  inset: 0;\n}\n.be3-zone-layer { z-index: 0; pointer-events: none; }\n.be3-range-layer { z-index: 0; pointer-events: none; }\n.be3-scene-layer { z-index: 1; pointer-events: none; }\n/* ★★★ 第 81 窗口：**测距虚线层** —— 压在场景 emoji 之上、单位之下。\n   理由与 Stage_1 的 `.be-measure-line z-index:2` 完全相同：\n   测距是玩家**正在做**的操作，被地形 emoji 盖住会让玩家觉得「点了没反应」；\n   而单位永远最上（它要可点）。 */\n.be3-dline-layer { z-index: 2; pointer-events: none; }\n.be3-measure-layer { z-index: 2; pointer-events: none; }\n.be3-token-layer { z-index: 4; pointer-events: none; }\n\n/* ---------------------------------------------------------------- 区块（A2）\n * ★ Stage_1 的三条观感细节（逐条对应，别自己发明）：\n *   ① 填充 **alpha ≈ 0.14** 的半透明色（不是实心 hex）—— 一片 30 米森林\n *      若用实心色，会变成「一整块不透明绿墙」，盖住底下所有单位与网格\n *   ② 描边 **2.5px 虚线（9 实 5 空）**（用户点名的「加粗虚线」）\n *   ③ `vector-effect: non-scaling-stroke` ⇒ 缩放时线**不变粗**\n * 🔴 选择器写成 `.be3-fieldmap .be3-zone-svg`（父级限定，specificity `0,2,0`）：\n *   Stage_1 第 27 窗口的**真 bug** 就是单类选择器（`0,1,0`）被更早的\n *   `.be-scope svg { width:16px }`（`0,1,1`）压过 ⇒ SVG 被塞进 16×16 再拉伸\n *   ⇒ **圆形区块被拉成 0.4 比例的椭圆**，判据全绿只有截图能看出来。\n * ------------------------------------------------------------------------- */\n.be3-fieldmap .be3-zone-svg {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n.be3-zone-shape {\n  stroke-linejoin: round;\n  vector-effect: non-scaling-stroke;\n}\n/* 区块的**装饰层**（填充 emoji + 名字）—— 与形状层分开的一层 DOM。\n *\n * ★★ 第 77 窗口（第二轮修）：**必须用 DOM，不能用 SVG `<text>`**。\n * 🔴🔴 修前我把填充 emoji 写成 `<text style=\"font-size:calc(14px * ico)\">🌲</text>`\n *   放进 `viewBox=\"0 0 100 40\"` 的 SVG 里 —— 截图里整张地图被**满屏大树**糊死。\n *   原因：**SVG 的 `font-size` 单位是 viewBox 单位，不是 CSS 像素**。\n *     `14px` ⇒ 14 个 viewBox 单位 ⇒ 画布宽的 14%；\n *     再被 `preserveAspectRatio=\"none\"` 拉伸约 11 倍 ⇒ 屏幕上 ≈ 154px。\n *   而判据当时全绿（节点在、`font-size` 字符串也在）——\n *   「写了一个字号」与「这个字号有多大」是两件事，只有截图能发现。\n * ⇒ 正解与 Stage_1 一致（`drawing-reference/css/03-zones.css`）：\n *   形状留在 SVG（要 `stroke-dasharray`），**emoji / 名字走 DOM** ——\n *   这里的 `14px` 就是屏幕上的 14 像素，不需要知道 viewBox 缩放比。\n */\n.be3-zone-decor {\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n  pointer-events: none;\n}\n.be3-zone-fill {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  /* 🔴 14px 与 Stage_1 的 `.be-zone-fill-emoji { font-size: 14px }` 同值；\n     乘 `--be3-ico` 是**布局式**施加（它不在 token 里，必须自己缩一次）。 */\n  font-size: calc(14px * var(--be3-ico));\n  line-height: 1;\n  /* 🔴 填充 emoji 要**比建筑 emoji 更淡** —— 用户说区块是「大致场景」、emoji 是\n     「点缀」，若两者一样亮，玩家分不清「这是主体还是装饰」（Stage_1 原话，alpha .82）。 */\n  opacity: .82;\n  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .55));\n  pointer-events: none;\n  user-select: none;\n}\n/* 区块名：低对比小字（它只是「这里叫什么」的提示，不是信息主体） */\n.be3-zone-label {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  font-size: calc(9.5px * var(--be3-ico));\n  line-height: 1.2;\n  color: var(--be3-text-muted);\n  background: rgba(10, 13, 17, .55);\n  border-radius: 3px;\n  padding: 0 3px;\n  white-space: nowrap;\n  pointer-events: none;\n  user-select: none;\n}\n\n/* ---------------------------------------------------------------- 效果范围（A1）\n * ★ Stage_1 的 `.be-field-range`：\n *   `border: 1px dashed rgba(217,164,65,.55)` +\n *   `radial-gradient(circle, .14 → .03 70% → transparent)` —— 中心亮、边缘淡。\n * 🔴 半径由渲染层给 **width 与 height 两个百分比**（等比投影下数值应相等），\n *   **不能**用 `aspect-ratio: 1`：那样宽度是容器宽度的百分比、高度由 ratio 反推，\n *   而容器不是正方形 ⇒ 又变成椭圆（Stage_1 `drawing-reference/05-circles.md`）。\n * ------------------------------------------------------------------------- */\n.be3-range {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  border-radius: 50%;\n  border: 1px dashed rgba(217, 164, 65, .55);\n  background: radial-gradient(circle, rgba(217, 164, 65, .14), rgba(217, 164, 65, .03) 70%, transparent);\n  pointer-events: auto;          /* ★ 用户要「点击展开该效果详细说明」⇒ 必须能点 */\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.be3-range:hover { border-style: solid; border-color: var(--be3-warn); }\n/* 圆心图标：**20px**（Stage_1 的 `.be-field-range-icon svg`），按 ico 反向缩放 */\n.be3-range-glyph {\n  font-size: calc(20px * var(--be3-ico));\n  line-height: 1;\n  opacity: .75;\n  filter: drop-shadow(0 0 3px rgba(217, 164, 65, .5));\n}\n\n/* ---------------------------------------------------------------- 建筑 / 道具（A3/A4）\n * ★★ 本窗口的核心观感改动：**点阵本身就是表达，不再画范围圈**。\n *   （修前每个对象都额外画一个 `circle/rect` 范围底 ⇒ 用户说的\n *     「内部都有一个圈，很丑很难看」。）\n * 🔴 对象容器本身**不吃事件**（它只有锚点大小，没有面积）；\n *   真正吃事件的是「中心图标 + 名字」这两个**子元素** —— 玩家点墙上那块砖\n *   应该能打开详情（`data-be3-action=\"map-open\"` 在容器上，子元素自然冒泡）。\n *   ⚠️ 但 emoji 点**不接管**：一排 50 个砖块各吃一次事件会让拖拽误触。\n * ------------------------------------------------------------------------- */\n/* ★★ 第 78 窗口：**点阵组容器**（满尺寸 + 不吃事件）。\n *\n * 🔴 为什么必须是「满尺寸」而不是 0 尺寸：\n *   点阵点的 `left/top` 是**视口百分比**，而百分比相对「包含块」尺寸算 ——\n *   容器 0 尺寸 ⇒ 全部塌到左上角（第 77 窗口实测，一个都看不见）。\n * 🔴 为什么必须是「祖先」而不是兄弟：`:hover` 只能沿祖先链命中 ——\n *   点阵与对象容器是兄弟的话，「鼠标移到 emoji 上高亮」这条需求**做不了**。\n * ⚠️ 容器 `pointer-events: none`、点 `auto`：\n *   只有 emoji 本身吃事件，空白处照常拖拽平移\n *   （Stage_1 `08-layers-and-hit-testing.md`：「铺满型容器绝不能 auto」）。\n */\n.be3-lattice-group {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n}\n.be3-lattice-group .be3-lattice-dot { pointer-events: auto; cursor: pointer; }\n/* 悬停点阵任意一块 ⇒ 整组高亮（「这一串是墙」） */\n.be3-lattice-group:hover .be3-lattice-dot {\n  filter: drop-shadow(0 0 3px rgba(217, 164, 65, .9)) brightness(1.25);\n}\n.be3-mapobj {\n  position: absolute;\n  transform: translate(0, 0);\n  width: 0;\n  height: 0;\n  pointer-events: none;\n  cursor: pointer;\n}\n/* 点阵里的一个 emoji：以对象锚点为原点做偏移（渲染层算好的百分比）。\n *\n * ★★ 第 78 窗口：字号改成**内联 `cqw`**（容器查询单位 = 容器宽度的 1%），\n *   由渲染层按「点距 × 0.92」算好。\n *\n * 🔴🔴 修前这里写死 `calc(12px * var(--be3-ico))` —— 用户本轮原话\n *   「画的也不够好看，密度和排布比较松散」的真因就是它：\n *   点距是**米**（测试包 1 米 ≈ 24px），而字号固定 12px ⇒ 比例只有 **0.5**，\n *   砖与砖之间空出一半 ⇒ 看起来是「一排棋子」而不是「一道墙」。\n *   Stage_1 的比例是 **0.92**（第 76 窗口放大截图逐块量出来的）。\n * ⚠️ 为什么用 `cqw` 而不是 `px`：`cqw` 是「容器宽度的 1%」，\n *   与画布多宽无关 ⇒ 比例 0.92 在窄面板/宽面板上都成立。\n *   用 px 就必须知道画布像素宽（渲染层拿不到）。\n * ⚠️ `--be3-ico`（图标缩放旋钮）仍然生效 —— 见下面的 `calc(... * var(--be3-ico))`：\n *   内联给的是「几何比例」，再乘一次旋钮系数（布局式，只施加一次）。\n */\n/* ★ `container-type: inline-size`（**只**按宽度建容器，不是 `size`）：\n *   `size` 要求元素**两个方向都有确定尺寸**，而 `.be3-fieldmap` 的高度是\n *   `aspect-ratio` 反推的 —— 用 `size` 在某些浏览器里会让高度塌成 0。\n *   我们只用 `cqw`（宽度单位），`inline-size` 就够，且没有副作用。 */\n.be3-fieldmap { container-type: inline-size; }\n.be3-lattice-dot {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  /* 内联写 `font-size: N cqw`（N = 点距 × 0.92）；这里的兜底值只在渲染层没给时用 */\n  font-size: calc(2.4cqw * var(--be3-ico));\n  line-height: 1;\n  pointer-events: none;\n  user-select: none;\n  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .55));\n}\n/* 中心图标（道具 / 无点阵的对象）+ 名字：这两个是**可点**的部分 */\n.be3-mapobj-glyph {\n  position: absolute;\n  left: 0; top: 0;\n  transform: translate(-50%, -50%);\n  font-size: calc(16px * var(--be3-ico));\n  line-height: 1;\n  pointer-events: auto;\n  cursor: pointer;\n  filter: drop-shadow(0 0 2px rgba(0, 0, 0, .7));\n}\n/* ★★ 第 78 窗口：**道具 = emoji + 外围加粗虚线圈**（Stage_1 的 `.be-interactive-mark`）。\n * 用户原话：「【神秘水晶】【炸药桶】也像 stage_1 的一样，emoji + 外围加粗虚线圈起来，表达特殊」。\n * 🔴 为什么道具要单独一圈：它和「布景 emoji」的区别是**这个能操作**。\n *   加粗虚线圈 = 「这一个特殊、能点」的唯一视觉信号。\n * ⚠️ 圈画在 emoji **外面**（用伪元素），不占布局、不影响 emoji 尺寸。 */\n.be3-mapobj-glyph.is-interactive::after {\n  content: '';\n  position: absolute;\n  left: 50%; top: 50%;\n  width: calc(30px * var(--be3-ico));\n  height: calc(30px * var(--be3-ico));\n  transform: translate(-50%, -50%);\n  border-radius: 50%;\n  border: 2px dashed rgba(217, 164, 65, .85);\n  background: rgba(10, 13, 17, .45);\n  box-shadow: 0 0 8px rgba(217, 164, 65, .35);\n  pointer-events: none;\n  z-index: -1;\n  transition: border-color .14s ease, box-shadow .14s ease, transform .14s ease;\n}\n.be3-mapobj:hover .be3-mapobj-glyph.is-interactive::after {\n  border-color: #ffd79a;\n  box-shadow: 0 0 12px rgba(217, 164, 65, .6);\n  transform: translate(-50%, -50%) scale(1.12);\n}\n.be3-mapobj.is-selected .be3-mapobj-glyph.is-interactive::after {\n  border-style: solid;\n  border-color: #ffd79a;\n}\n/* 名字药丸\n *\n * ★★ 第 78 窗口：**默认隐藏**（用户原话：「小河/瓦砾堆/篝火圈/石屋/...\n *   在地图上默认隐藏名字，鼠标移到相关 emoji 上高亮，点击展开详情」）。\n *\n * 🔴 为什么必须默认隐藏（不是「为了好看」）：\n *   五座建筑的名字药丸在 780px 画布上会互相压住（实测「北墙 1.5m」与「石屋 1.5m」几乎贴住）；\n *   而玩家看地图时首先要知道「这是一道墙」，不是「它叫什么」——\n *   名字是**核对用**的信息，应该按需出现。\n * ⚠️ 仍然**渲染出节点**（这里只是 `opacity: 0`，不是 `display:none`）：\n *   ① 「名字存在」的结构判据与「默认不显示」的视觉判据互不干扰；\n *   ② 悬停/选中时一条规则就放出来，不需要 JS 重建 DOM；\n *   ③ `display:none` 会让 `getBoundingClientRect` 返回 0 —— 真机判据量不了它。\n */\n.be3-mapobj-name {\n  position: absolute;\n  left: 0; top: calc(10px * var(--be3-ico));\n  transform: translate(-50%, 0);\n  font-size: calc(9.5px * var(--be3-ico));\n  white-space: nowrap;\n  color: var(--be3-text-muted);\n  background: rgba(10, 13, 17, .55);\n  border-radius: 3px;\n  padding: 0 3px;\n  pointer-events: auto;\n  cursor: pointer;\n  opacity: 0;\n  transition: opacity .14s ease;\n}\n/* 🔴 悬停对象 / 选中对象 ⇒ 名字浮现（「鼠标移到相关 emoji 上高亮」的落地）。\n   选择器挂在 `.be3-mapobj` 上而不是 emoji 上：玩家的鼠标常常落在点阵的某一块砖上，\n   而那整组都是「这个对象」—— 只要在对象范围内就显示，不必精确压到中心图标。 */\n.be3-mapobj:hover .be3-mapobj-name,\n.be3-mapobj.is-selected .be3-mapobj-name { opacity: 1; }\n/* 「范围底」—— **只在没有形状点阵时**出现（老数据：只写了中心 + 范围）。\n * 🔴 它比修前**淡得多**（alpha .06 / 虚线 1px），一眼能看出「这是兜底表达」\n *   而不是「正式画法」，避免它又变成用户说的那个「难看的圈」。 */\n.be3-mapobj-box {\n  position: absolute;\n  left: 0; top: 0;\n  transform: translate(-50%, -50%);\n  border-radius: 50%;\n  border: 1px dashed rgba(224, 169, 92, .35);\n  background: rgba(224, 169, 92, .06);\n  pointer-events: none;\n}\n.be3-mapobj-box.is-rect { border-radius: 4px; }\n/* 悬停 / 选中：只提亮中心图标与名字，**不改点阵**（点阵是「地形」，不该忽明忽暗） */\n.be3-mapobj:hover .be3-mapobj-glyph { filter: drop-shadow(0 0 4px rgba(217, 164, 65, .95)); }\n.be3-mapobj.is-selected .be3-mapobj-glyph { filter: drop-shadow(0 0 5px rgba(255, 255, 255, .9)); }\n.be3-mapobj.is-selected .be3-mapobj-name { color: var(--be3-text); }\n/* ★★ 第 78 窗口：**鼠标移到点阵 emoji 上 ⇒ 整组高亮**（用户原话「鼠标移到相关 emoji 上高亮」）。\n * 🔴 为什么高亮的是**整组点阵**而不是被指到的那一个 emoji：\n *   玩家想知道的是「这一串是墙」—— 高亮单块砖会让人以为「这一块砖特殊」。\n *   ⇒ 悬停对象容器时，把整组点阵提亮一点（filter），同时名字浮现。\n * ⚠️ 用 `filter: brightness()` 而不是改 `color`：emoji 是彩色字形，\n *   改 `color` 对它无效（`fill`/`color` 都不影响彩色 emoji 的渲染色）。\n *   而 `brightness` 对彩色 emoji 生效，且不会把它变成单色。 */\n.be3-mapobj:hover .be3-lattice-dot {\n  filter: drop-shadow(0 0 3px rgba(217, 164, 65, .9)) brightness(1.25);\n}\n\n/* ---------------------------------------------------------------- 单位（A0）\n * ★★ Stage_1 的 `.be-token`，**尺寸单位是 px**（30×30 圆 / 2px 边框 / 11px 首字 / 10px 名字）。\n * 🔴 「图标反向缩放」在这里是**布局式**：`width/height/font-size` 都乘 `--be3-ico`，\n *   **不再**加 `transform: scale(var(--be3-ico))` —— 那会与 `translate(-50%,-50%)`\n *   复合，缩两次 ⇒ 屏幕尺寸 = 30/zoom ⇒ 功能等于没做（Stage_1 P84/P99 同族）。\n * ⚠️ token 自己 `pointer-events: auto`：单位永远可点（z-index 4 高于其他所有层）。\n * ------------------------------------------------------------------------- */\n.be3-node {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: calc(3px * var(--be3-ico));\n  pointer-events: auto;\n  cursor: pointer;\n}\n.be3-node-dot {\n  width: calc(30px * var(--be3-ico));\n  height: calc(30px * var(--be3-ico));\n  border-radius: 50%;\n  border: max(1px, calc(2px * var(--be3-ico))) solid var(--be3-enemy);\n  background: #2a1e1e;\n  color: var(--be3-enemy);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: calc(11px * var(--be3-ico));\n  font-weight: 700;\n  transition: box-shadow .14s ease, border-color .14s ease;\n}\n.be3-node.is-ally .be3-node-dot,\n.be3-node.is-summon .be3-node-dot {\n  border-color: var(--be3-self); background: #1a2430; color: var(--be3-self);\n}\n.be3-node.is-self .be3-node-dot {\n  border-color: var(--be3-ally); background: #1a2a22; color: var(--be3-ally);\n  box-shadow: 0 0 0 calc(3px * var(--be3-ico)) rgba(76, 191, 122, .18);\n}\n/* ★ 第 84 窗口：hover 也**外扩 3px** ⇒ 鼠标扫过时圆点会「鼓」一下（与选中同一个问题）。\n *   改成只提亮，不改外轮廓：悬停时玩家要判断的是「这是谁」，不是「图标变大了」。 */\n.be3-node:hover .be3-node-dot { border-color: rgba(255, 255, 255, .75); }\n/* ★★★ 第 84 窗口：**选中态不再「浮起来」**（用户：「点击地图上的单位，会浮起来…这个效果不要」）\n *\n * 🔴 修前是 `box-shadow: 0 0 0 3px rgba(255,255,255,.35)` —— 一圈**3px 白色外扩**，\n *   在深色画布上像「圆点底下垫了个亮点」⇒ 视觉上浮起一截。\n * ⇒ 改成**不改变外轮廓**的做法：只把描边**提亮**（`border-color`），\n *   圆点的**尺寸与位置一个像素都不动** —— 玩家看到的是「这个圈更亮了」，\n *   而不是「这个圈飘起来了」。\n * ⚠️ `box-shadow` 那一条**不再是 3px 外扩**；若要「选中更醒目」，可以加 `inset`\n *   （向内发光，绝不外扩）。\n */\n.be3-node.is-focused .be3-node-dot {\n  border-color: #fff;\n  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .55);\n}\n.be3-node.is-pending .be3-node-dot { border-style: dashed; }\n\n/* ------------------------------------------------------------------ 高地 / 洼地角标\n * ★★★ 第 81 窗口（用户第 1 条）：照 Stage_1 的 `.be-token-height` 复刻。\n *\n * Stage_1 的三条观感（`Stage_1/src/ui/styles.css:2505-2528`，逐条抄，别自己发明）：\n *   ① 小方块 + 8.5px 加粗符号，**贴在圆圈旁边**（高处在右上 `right:-12px; top:-6px`）\n *   ② **高处琥珀 / 洼地青蓝** —— 两种颜色一眼可分（Stage_1 第一版共用一个紫色是 bug）\n *   ③ 洼地的角标挪到**左下**（`left:-12px; bottom:-6px`）——\n *      「位置本身也带语义」：右上 = 站得高，左下 = 蹲得低\n *\n * 🔴 尺寸也要跟 `--be3-ico` 走（与其他图标同一条纪律：只施加一次，用布局式 calc，\n *   **不用 transform** —— transform 会与 `.be3-node` 的 `translate(-50%,-50%)` 复合）。\n * ⚠️ 只画**符号**（▲/▼），不带米数（用户原话「加了 △ 图标」）；\n *   米数在 `title` 里（悬停可见），由渲染层从 `geometry.elevationOf` 的 `y` 给出。\n */\n.be3-node-elev {\n  position: absolute;\n  right: calc(-12px * var(--be3-ico));\n  top: calc(-6px * var(--be3-ico));\n  padding: 0 calc(3px * var(--be3-ico));\n  border-radius: 3px;\n  color: #0d1117;\n  font-size: calc(8.5px * var(--be3-ico));\n  font-style: normal;\n  font-weight: 700;\n  line-height: calc(12px * var(--be3-ico));\n  white-space: nowrap;\n  pointer-events: none;\n}\n/* 高处：琥珀（暖色 = 向上、有优势的地形）—— 与 Stage_1 同一个色值 */\n.be3-node-elev.is-high { background: rgba(217, 164, 65, .9); }\n/* 洼地：青蓝（冷色 = 向下），并且移到**左下**（位置也带语义） */\n.be3-node-elev.is-low {\n  background: rgba(111, 168, 220, .9);\n  right: auto;\n  left: calc(-12px * var(--be3-ico));\n  top: auto;\n  bottom: calc(-6px * var(--be3-ico));\n}\n/* ★★ 第 78 窗口：**地图上不画血条**（用户原话：「地图上不显示血条」）。\n *\n * 🔴 为什么删掉是对的（不是单纯「用户不喜欢」）：\n *   ① 血条在 30px 圆点下只有 3px 高，在 780px 画布上几乎看不清\n *      —— 「看不清的信息」比「没有信息」更糟（玩家会以为血条坏了）；\n *   ② HP 是**数值信息**，属于【当前目标 HUD】与【目标状态栏】，不属于**空间**地图；\n *      Stage_1 的 `.be-token` 也只有「圆圈 + 首字 + 名字」，没有血条；\n *   ③ 20 个单位同屏时，20 条血条会把地图糊成一片细线。\n * ⇒ 血条数据（`p.hpPct`）**照旧存在**，只是地图上不画：\n *   悬停时的 `title` 仍带 `HP 34%`，HUD / 状态栏 / 详情框照常显示。\n * ⚠️ 旧的 `.be3-node-hp` 四条规则**已删除**（不是注释掉）——\n *   留着它们会让下一个人以为「血条还能开回来」，而且 `_t_render` 里\n *   「每个单位带血条」那条判据也会继续绿（假绿）。\n */\n/* 名字药丸（Stage_1 的 `.be-token-label`）：深底 + 圆角，压在背景上也读得清。\n * 🔴 显隐由**这一条**规则管（渲染层总是输出节点，CSS 收起）——\n *   判据只写一处，而且「结构存在」与「默认不显示」两条判据互不干扰。 */\n.be3-node-label {\n  font-size: calc(10px * var(--be3-ico));\n  line-height: 1.2;\n  color: var(--be3-text-muted);\n  background: rgba(10, 13, 17, .8);\n  padding: 1px calc(5px * var(--be3-ico));\n  border-radius: 3px;\n  white-space: nowrap;\n}\n.be3-canvas:not(.is-names-on) .be3-node-label { display: none; }\n/**\n * ★★★ 第 85 窗口（用户自己定位到了根因）：\n *   「我发现了这个浮起来好像是**显示名字**的效果」\n *\n * 🔴 完全正确。修前有两处**绕过「角色名开关」强行显示名字**的规则：\n *   · `.be3-node.is-focused .be3-node-label`（点中谁就露出谁的名字）\n *   · `.be3-canvas.is-measuring .be3-node-label`（一测距就全露出）\n *\n *   而 `.be3-node` 是 `flex-direction: column` 的竖排容器：\n *   圆点下面多出一行名字 ⇒ **整个 token 纵向变长**，圆点相对画布中心\n *   被「顶高」了一截 ⇒ 玩家看到的就是「点击后浮起来了」。\n *   （`translate(-50%,-50%)` 是按**整个 token** 居中，token 一长，圆点就上移。）\n *\n * ⇒ 现在：**名字只由左下角 `Aa` 开关决定**，点谁都不再改变 token 的高度。\n *   ⚠️ 这与用户第 74 窗口「名字默认隐藏」+ 第 78 窗口「名字用一条 CSS 规则管」\n *      是同一条纪律的收口：**显隐只能有一个开关**。\n */\n/* （原 `.be3-node.is-focused .be3-node-label` 的强制显示已删除 —— 见上面） */\n\n/* ---------------------------------------------------------------- 距离连线（默认空）\n * 宽度是**屏幕像素**（带 `non-scaling-stroke`）：1px 虚线 + 药丸标签。\n * ⚠️ 默认不出现在画面上（开关在 runner 的 `canvasView.links`）。\n * ------------------------------------------------------------------------- */\n.be3-fieldmap .be3-link-layer {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  overflow: visible;\n}\n.be3-link {\n  stroke: var(--be3-warn);\n  stroke-width: 1.2;\n  stroke-dasharray: 5 4;\n  vector-effect: non-scaling-stroke;\n  opacity: .8;\n}\n.be3-link.is-near { opacity: .9; }\n.be3-link.is-melee { stroke: var(--be3-danger); stroke-dasharray: none; opacity: .95; }\n.be3-link-tag {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  padding: 0 4px;\n  border-radius: 8px;\n  background: rgba(10, 13, 17, .86);\n  border: 1px solid rgba(224, 169, 92, .5);\n  color: var(--be3-warn);\n  font-size: calc(10px * var(--be3-ico));\n  line-height: 1.4;\n  white-space: nowrap;\n  pointer-events: none;\n}\n\n/* ---------------------------------------------------------------- 脚部计数 */\n.be3-canvas-foot {\n  display: flex; justify-content: space-between; gap: 8px;\n  font-size: 10px; padding: 1px 4px 3px;\n  min-height: 14px;\n}\n.be3-warn { color: var(--be3-warn); }\n\n/* ---------------------------------------------------------------- 角部浮层\n * ★★ 第 77 窗口：**回到绝对定位**（Stage_1 的 `.be-field-icons` / `.be-zone-icons`\n *   就是浮在画布角上的）。第 76 窗口为了「百分比高度算不出来」把它改成了\n *   `flex` 兄弟项 + 132px 负 margin —— 那套修法能跑，但代价是：\n *     · 地图被「布局上」吃掉 132px（靠负 margin 骗回来，很容易再次踩坑）\n *     · 右上与右下被绑在同一列里，两者的**默认位置**互相牵制\n *   ⇒ 现在两角**各自独立绝对定位**、各自 `max-height` 用**像素**（不用百分比），\n *     这正是第 76 窗口那条教训的正解：「要么给父容器确定 height，要么让 flex 算，\n *     不要让 CSS 猜」—— 这里父容器（`.be3-fieldmap`）**有确定高度**（撑满 300px 画布），\n *     所以绝对定位 + px 上限是安全的。\n * ⚠️ 两者都是 `pointer-events: none`（容器），只有清单本体 `auto`：\n *   否则整块右上角都点不到地图。\n * ------------------------------------------------------------------------- */\n.be3-map-side {\n  position: absolute;\n  inset: 6px 6px 6px auto;\n  width: 132px;\n  z-index: 5;\n  display: flex;\n  flex-direction: column;\n  pointer-events: none;\n}\n.be3-map-side > .be3-map-icons,\n.be3-map-side > .be3-map-list {\n  pointer-events: auto;\n  min-width: 0;\n  max-width: 100%;\n  box-sizing: border-box;\n}\n\n/* ★ 右上角「持续效果 / 天气」—— Stage_1 的 `.be-field-icons` / `.be-field-icon`\n * 三件套（缺一条就「不好看」）：\n *   ① 30px 圆 + 1px 淡金边 + 深底\n *   ② **默认 45% 不透明 + 70% 去饱和**（「有就显示」的信息角标，不该抢眼）\n *   ③ 悬停 → 100% + 放大 1.12 + 金色外发光\n * 🔴 修前我们是 40px、完全不透明、亮黄边 —— 在深色画布上非常刺眼，用户说的\n *   「图标样式也不好看」就是这个。 */\n.be3-map-icons {\n  flex: 0 1 auto;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 4px;\n  max-height: 132px;\n  overflow-y: auto;\n  overflow-x: hidden;\n  scrollbar-width: none;\n  padding-right: 4px;\n}\n.be3-map-icons::-webkit-scrollbar { width: 0; height: 0; }\n.be3-map-icon {\n  position: relative;\n  flex: 0 0 auto;\n  width: 30px;\n  height: 30px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  border: 1px solid rgba(217, 164, 65, .45);\n  background: rgba(20, 24, 30, .82);\n  color: var(--be3-warn);\n  cursor: pointer;\n  padding: 0;\n  opacity: .45;\n  filter: grayscale(.7);\n  transition: opacity .16s ease, filter .16s ease, transform .16s ease, box-shadow .16s ease;\n}\n.be3-map-icon:hover {\n  opacity: 1;\n  filter: none;\n  transform: scale(1.12);\n  box-shadow: 0 0 10px rgba(217, 164, 65, .5);\n}\n.be3-map-icon-g { font-size: 16px; line-height: 1; }\n/* 持续回合徽标：13px 小圆压在右下角**外侧**（Stage_1 的 `right:-3 bottom:-3`） */\n.be3-map-icon-badge {\n  position: absolute;\n  right: -3px;\n  bottom: -3px;\n  min-width: 13px;\n  height: 13px;\n  padding: 0 2px;\n  border-radius: 7px;\n  background: var(--be3-warn);\n  color: #14181e;\n  font-size: 8.5px;\n  font-style: normal;\n  font-weight: 700;\n  line-height: 13px;\n  text-align: center;\n}\n.be3-map-icons-empty {\n  padding: 2px 4px;\n  font-size: 10px;\n  color: var(--be3-text-muted);\n  text-align: right;\n}\n\n/* ★ 右下角「区块 / 场景清单」—— Stage_1 的 `.be-zone-icons` / `.be-zone-icon`\n *   **色块 + 名字 + 徽标**（不是右上那种大图标：区块是玩家要**对上号**的一块地，\n *   颜色就是它的身份）。\n * 🔴 区块图标**不做**暗色虚化（Stage_1 的原话：它是「有就显示」的信息角标；\n *   而区块是玩家会去对应地图的东西，虚化过头会被误认为禁用态）。 */\n.be3-map-list {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  flex: 0 1 auto;\n  max-height: 132px;\n  margin-top: auto;          /* 🔴 贴底（父容器高度确定，所以成立） */\n  border-radius: 4px;\n  overflow: hidden;\n}\n.be3-map-list.is-bottom { margin-top: auto; }\n.be3-map-list-head {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 4px;\n  padding: 0 2px 2px;\n  font-size: 9.5px;\n  color: var(--be3-text-dim, var(--be3-text-muted));\n}\n.be3-map-list-body {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n  overflow-x: hidden;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 4px;\n  padding-right: 4px;\n  scrollbar-width: none;\n}\n.be3-map-list-body::-webkit-scrollbar { width: 0; height: 0; }\n.be3-map-list-row {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  height: 22px;\n  padding: 0 7px 0 5px;\n  border-radius: 4px;\n  border: 1px solid rgba(150, 172, 140, .5);\n  background: rgba(20, 24, 30, .86);\n  color: #b7c9ac;\n  font-size: 10px;\n  white-space: nowrap;\n}\n.be3-map-list-row.is-static { cursor: default; }\n.be3-map-list-sw,\n.be3-map-list-dot {\n  width: 9px;\n  height: 9px;\n  border-radius: 2px;\n  flex: 0 0 auto;\n  border: 1px solid rgba(255, 255, 255, .25);\n}\n.be3-map-list-n {\n  max-width: 88px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.be3-map-list-badge {\n  position: absolute;\n  right: -3px;\n  bottom: -3px;\n  min-width: 13px;\n  height: 13px;\n  padding: 0 2px;\n  border-radius: 7px;\n  background: #96ac8c;\n  color: #14181e;\n  font-size: 8.5px;\n  font-style: normal;\n  font-weight: 700;\n  line-height: 13px;\n  text-align: center;\n}\n.be3-map-list-empty { padding: 2px 4px; font-size: 10px; text-align: right; }\n\n/* ============================================================================\n * ★★ 第 80 窗口：**距离系统**（左上角两行标识 / 测距浮层 / 单位测距高亮）\n * ----------------------------------------------------------------------------\n * 用户原话：\n *   「地图左上角出现两行标识（类似区块列表），1.友方内部距离 2.显示敌方内部距离。」\n *   「地图上点击，选中任意敌方单位时，出现所有友方单位对于该敌对单位的距离，\n *     点击其他空白处取消。」\n *   「先点击友方单位，再点击敌方单位，出现该友方单位和该敌方单位的距离，点击其他空白处取消。」\n *\n * 🔴 三条设计决定（每条都对应一个「不这么做就会难看/看不懂」）：\n *   ① 左上角标识**默认收起**：展开时两块清单会占掉画布左上 132px 宽，\n *      而画布只有 300px 高 —— 收起态只留一行「友方内部距离 3」，\n *      点开才列出明细。这与右下角区块清单的 `max-height: 132px` 是同一条考虑。\n *   ② 与**右下角区块清单同构**（同样的行样式、同样的滚动、同样的色块语义）：\n *      用户说「类似区块列表」⇒ 玩家不该学第二套读法。\n *   ③ 档位配色**只做视觉分级**，语义永远是 `TIERS[i].label` 的中文\n *      （见 `geometry.TIERS` 的注释：档位是**战斗规则**，世界书按档位下发规则）。\n * ==========================================================================*/\n\n/* ---------------------------------------------------------------- 左上角两行标识 */\n.be3-dist-badges {\n  position: absolute;\n  inset: 6px auto 6px 6px;          /* 左上角 */\n  /* 🔴 宽度 132 → 168（第 80 窗口截图抓到的可读性问题）：\n     132px 是照右下角区块清单定的，但**距离行比区块行更长** ——\n     「矿洞守卫·斥候⇢深渊石像鬼」在 132px 里被截成「矿洞守卫·斥候⇢深渊石像…」，\n     而玩家正是靠名字判断「这是哪一对」。\n     ⚠️ 168 是「装得下 6 字名字 + 箭头 + 6 字名字」的实测宽度；\n       再宽就会压到画布中央的单位（画布只有 100u 宽）。 */\n  width: 168px;\n  z-index: 5;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  pointer-events: none;             /* 容器不吃事件（否则左上角点不到地图） */\n  /**\n   * 🔴 容器**自己滚动**，而不是让子项被压缩（第 80 窗口截图抓到的真问题）：\n   *   第一版给容器 `max-height: calc(100% - 12px)` + 子项 `flex: 0 1 auto`\n   *   ⇒ flex 为了塞进高度把**清单压扁**，于是「敌方内部距离」那一块只剩两行半，\n   *     第三行被裁成半截、文字压在下面的区块 emoji 上（截图里那团糊）。\n   *   ⇒ 正解：子项 `flex: 0 0 auto`（**永不压缩**）+ 容器 `overflow-y: auto`\n   *     ⇒ 放不下时滚动，而不是切行。「切一半的行」比「要滚一下」难读得多。\n   */\n  overflow-y: auto;\n  overflow-x: hidden;\n  scrollbar-width: none;\n  max-height: calc(100% - 12px);\n}\n.be3-dist-badges::-webkit-scrollbar { width: 0; height: 0; }\n.be3-dist-badge {\n  pointer-events: auto;             /* 只有标识本体吃事件 */\n  flex: 0 0 auto;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  height: 22px;\n  padding: 0 6px;\n  border-radius: 4px;\n  border: 1px solid var(--be3-border);\n  background: rgba(20, 24, 30, .88);\n  font-size: 10px;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: border-color .14s ease, background .14s ease;\n}\n.be3-dist-badge:hover { border-color: var(--be3-accent); }\n.be3-dist-badge.is-ally { color: var(--be3-ally); border-color: rgba(76, 191, 122, .45); }\n.be3-dist-badge.is-enemy { color: var(--be3-enemy); border-color: rgba(214, 92, 92, .45); }\n.be3-dist-badge.is-open { background: rgba(30, 36, 46, .95); }\n/* ★★★ 第 81 窗口：徽章内的**两个命中区**（渲染层把它们拆成了两个按钮）\n *   · `.be3-dist-line-btn` ⇢  —— 在画布上画这一边的距离线（`dist-line`）\n *   · `.be3-dist-badge-hit`   —— 展开/收起这块清单（`dist-toggle`）\n * 🔴 `.be3-dist-badge` 本身**不再**带 `data-be3-action`（它的两个子元素各带一个），\n *   否则点 ⇢ 时 `closest('[data-be3-action]')` 会先命中外层，把「画线」变成「展开清单」\n *   —— 那正是用户抱怨的「不是弹窗，是显示距离线」被做反的形态。\n * ⚠️ `cursor` 分两种：⇢ 是「切换显示」，横条是「展开」。 */\n.be3-dist-line-btn {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 18px;\n  height: 18px;\n  padding: 0;\n  border-radius: 3px;\n  border: 1px solid var(--be3-border);\n  background: rgba(255, 255, 255, .04);\n  color: var(--be3-text-dim);\n  font-size: 11px;\n  line-height: 1;\n  cursor: pointer;\n}\n.be3-dist-line-btn:hover { border-color: var(--be3-accent); color: var(--be3-text); }\n/* 开着的时候**必须一眼看出来**（与 `.be3-ctl-btn.is-on` 同一档的强调） */\n.be3-dist-line-btn.is-on.is-ally {\n  border-color: var(--be3-ally); color: #0d1117; background: var(--be3-ally);\n}\n.be3-dist-line-btn.is-on.is-enemy {\n  border-color: var(--be3-enemy); color: #0d1117; background: var(--be3-enemy);\n}\n.be3-dist-badge-hit {\n  flex: 1 1 auto;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  height: 100%;\n  cursor: pointer;\n}\n.be3-dist-badge.is-lining { background: rgba(34, 42, 54, .96); }\n.be3-dist-k {\n  flex: 1 1 auto;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  color: var(--be3-text-muted);\n}\n.be3-dist-badge.is-ally .be3-dist-k { color: var(--be3-ally); }\n.be3-dist-badge.is-enemy .be3-dist-k { color: var(--be3-enemy); }\n.be3-dist-n {\n  flex: 0 0 auto;\n  font-style: normal;\n  font-variant-numeric: tabular-nums;\n  font-weight: 700;\n}\n.be3-dist-unknown {\n  flex: 0 0 auto;\n  font-style: normal;\n  width: 12px;\n  height: 12px;\n  line-height: 12px;\n  text-align: center;\n  border-radius: 6px;\n  background: rgba(224, 169, 92, .22);\n  color: var(--be3-warn);\n  font-size: 9px;\n}\n\n/* 展开后的明细清单（**可滚动**，与右下角区块清单同一套观感）\n * 🔴 必须有**不透明底**（第 80 窗口截图抓到的真问题）：\n *   第一版只给了 `background: transparent`，于是展开后清单里的文字与\n *   底下的区块 emoji / 区块名**叠在一起**（截图里「中距」和「苔原空地」糊成一团）。\n *   这不是配色问题 —— 是「文字压在图形上」的可读性问题。\n *   ⇒ 与 `.be3-map-list-row` 同一档的不透明底（rgba(20,24,30,.94)）+ 圆角 + 内边距，\n *     让它读起来是「一块面板」而不是「浮在地图上的散字」。\n * ------------------------------------------------------------------------- */\n.be3-dist-list {\n  pointer-events: auto;\n  /* 🔴 `0 0 auto`（**不许被压缩**）：列表自己滚动，父容器不压它。\n     用 `0 1 auto` 会让 flex 把清单压扁 ⇒ 行被切一半。 */\n  flex: 0 0 auto;\n  min-height: 0;\n  /**\n   * 🔴🔴 **列表自己也有上限 + 内部滚动**（第 80 窗口截图抓到的第三个问题）。\n   *   修前只给容器 `max-height` + `overflow-y: auto` ⇒ 两块徽章 + 两块清单\n   *   的总高度超过画布 300px 时，**容器**滚动，于是第一块的清单被**切一半**\n   *   （截图里「平地→高点·高差 3 米」下面露出半行，正好压在「敌方内部距离」徽章上）。\n   *   ⇒ 现在：每块清单最多 78px 自己滚 ⇒ 容器高度可控（22+78+22+78+间距 ≈ 208px），\n   *     两块徽章**永远完整可见**，「哪一块是哪一块」不会糊。\n   *   ⚠️ 78px ≈ 3 行（每行 24px 左右）—— 「3 条以内一眼看全、多了滚动」是合理取舍。\n   */\n  max-height: 78px;\n  overflow-y: auto;\n  overflow-x: hidden;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 3px 4px;\n  border-radius: 4px;\n  border: 1px solid var(--be3-border);\n  background: rgba(20, 24, 30, .94);\n  scrollbar-width: none;\n}\n.be3-dist-list::-webkit-scrollbar { width: 0; height: 0; }\n\n/* 一条距离（**两处共用**：左上角清单 + 测距浮层） */\n.be3-dist-row {\n  display: flex;\n  align-items: baseline;\n  flex-wrap: wrap;\n  gap: 3px;\n  padding: 1px 4px;\n  border-radius: 3px;\n  /* 🔴 每条也带底：清单整体有底了，但行与行之间靠这点色差才分得开\n     （截图里「≈9.1 米 推算 中距」挤成一条时，没有行底色就分不清是两行还是三行） */\n  background: rgba(255, 255, 255, .05);\n  font-size: 9.5px;\n  line-height: 1.5;\n}\n.be3-dist-row.is-unknown { opacity: .6; }\n.be3-dist-who {\n  color: var(--be3-text-muted);\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.be3-dist-who i { font-style: normal; color: var(--be3-text-dim, #6b7785); margin: 0 1px; }\n/* 🔴 名字与数字要**分两行**（`flex-wrap: wrap` 已给）：\n *   截图里「矿洞守卫·斥候⇢深渊石像鬼 9 米 中距 平地→洼地·高差 3 米」挤成一行时，\n *   数字被名字挤到看不见。给 `.be3-dist-v` 一点左右留白，让「数字」永远是行首可读的。 */\n.be3-dist-v {\n  color: var(--be3-text);\n  font-weight: 700;\n  font-variant-numeric: tabular-nums;\n  margin-left: 2px;\n}\n/* 推算角标（**第 80 窗口第①条纪律**：AI 声明优先，推算必须标明） */\n.be3-dist-approx {\n  font-size: 8.5px;\n  padding: 0 3px;\n  border-radius: 4px;\n  background: rgba(224, 169, 92, .18);\n  color: var(--be3-warn);\n}\n/* 档位（配色只做分级；文字永远来自 TIERS[i].label） */\n.be3-dist-tier {\n  font-size: 8.5px;\n  padding: 0 3px;\n  border-radius: 4px;\n  background: rgba(255, 255, 255, .07);\n  color: var(--be3-text-muted);\n}\n.be3-dist-row.is-tmelee .be3-dist-tier { background: rgba(214, 92, 92, .22); color: #e88; }\n.be3-dist-row.is-tnear .be3-dist-tier { background: rgba(224, 169, 92, .2); color: var(--be3-warn); }\n.be3-dist-row.is-tmid .be3-dist-tier { background: rgba(91, 141, 239, .2); color: var(--be3-accent); }\n.be3-dist-row.is-tfar .be3-dist-tier,\n.be3-dist-row.is-textreme .be3-dist-tier,\n.be3-dist-row.is-tbvr .be3-dist-tier { background: rgba(255, 255, 255, .06); }\n/* 高差说明（「高点→洼地·高差 3 米」）—— 用户第 3 条点名要的东西 */\n.be3-dist-elev {\n  font-size: 8.5px;\n  color: #8fa6c0;\n}\n\n/* ---------------------------------------------------------------- 测距虚线（第 81 窗口）\n * ★★★ 用户原话：「做距离线渲染。……【友方内部】【敌方内部】不是弹窗，\n *   只是点一下显示距离线，照 Stage_1 的效果来。」\n *\n * 形态逐条照 Stage_1（`Stage_1/src/ui/styles.css:2217-2265`）：\n *   · 虚线本体 = `height:0` + `border-top: 1px dashed` + `transform-origin: 0 0`\n *     ⇒ 渲染层只需给 `left/top/width/rotate`（角度在 u 空间算，见 `distLineHtml`）\n *   · 中点药丸 = 深底 + 等宽字体 + 边框（**琥珀** = 成对；**蓝** = 单个敌人的那批）\n *   · 有高差的药丸换**琥珀强调色**（`is-elev`）—— 只换色、**不改尺寸**：\n *     尺寸一变，有无高差的标签在视觉上就不等重了（Stage_1 的原话）\n *\n * 🔴 `pointer-events: none` 必须给足：这一层铺满画布，吃事件会让\n *   「点地图空白处取消测距」彻底失效（Stage_1 P91 同型：铺满型容器绝不能 auto）。\n * ⚠️ 字号跟 `--be3-ico` 走（与其他图标同一条纪律：只施加一次）。\n */\n.be3-dline {\n  position: absolute;\n  height: 0;\n  /**\n   * ★★★ 第 85 窗口（用户：「距离线的虚线有些太细了，可以再放大和加粗一点」）。\n   *\n   * 🔴 修前是 `1px dashed` —— 在 300px 高的画布上、深色底上，1px 的虚点几乎糊成一条灰影，\n   *   而这条线是玩家**唯一**能看出「谁离谁多远」的依据。\n   * ⇒ 加粗到 **2px**，并显式给 `dash` 间隔（默认间隔按 1px 宽算，2px 时会显得太密）。\n   * ⚠️ 用 `border-top` + `dashed` 而**不是** CSS 的 `dashed` 默认节奏：\n   *   `border-style: dashed` 的虚线段长由浏览器按线宽推算，**不可控**；\n   *   要「看得清的长虚线」得用 `background: repeating-linear-gradient` 自己画。\n   *   ⇒ 这里改成渐变实现：线段 7px、间隔 5px，粗细 2.4px，**两端都是可控的**。\n   *   （`transform-origin: 0 0` 与 `width:L%` 的用法不变，渲染层无需改动。）\n   */\n  height: 3px;\n  border-top: 0;\n  /* 🔴 颜色与节奏都走变量：solo / approx 只需改变量，不必重写整条规则 */\n  --dl-c: var(--be3-warn);\n  --dl-a: 7px;\n  --dl-b: 12px;\n  background-image: repeating-linear-gradient(\n    90deg,\n    var(--dl-c) 0 var(--dl-a),\n    transparent var(--dl-a) var(--dl-b)\n  );\n  background-size: 100% 2.4px;\n  background-repeat: no-repeat;\n  background-position: 0 1px;\n  transform-origin: 0 0;\n  pointer-events: none;\n  opacity: .95;\n}\n/* 单个敌人 ⇒ 它到全部友方的那一批：主色（与「成对」的琥珀区分开） */\n.be3-dline.is-solo { --dl-c: var(--be3-accent); }\n/* 推算值（AI 没声明、面板按坐标算的）：虚线换成点线、更淡 —— 「不确定」要看得出来 */\n/* 推算值：**更短的虚点 + 更淡**（「不确定」要看得出来）。节奏靠变量，不再改 border-style。 */\n.be3-dline.is-approx { opacity: .6; --dl-a: 3px; --dl-b: 9px; }\n.be3-dline-tag {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  padding: 0 calc(5px * var(--be3-ico));\n  border-radius: 3px;\n  background: rgba(10, 13, 17, .88);\n  border: 1px solid var(--be3-warn);\n  color: var(--be3-warn);\n  font-size: calc(9.5px * var(--be3-ico));\n  line-height: calc(15px * var(--be3-ico));\n  font-weight: 400;\n  white-space: nowrap;\n  pointer-events: none;\n  z-index: 1;\n}\n.be3-dline-tag.is-solo { border-color: var(--be3-accent); color: var(--be3-accent); }\n.be3-dline-tag.is-elev { border-color: #d9a441; color: #ffd79a; font-weight: 700; }\n.be3-dline-approx {\n  font-style: normal;\n  margin-left: 3px;\n  padding: 0 3px;\n  border-radius: 2px;\n  background: rgba(224, 169, 92, .22);\n  color: var(--be3-warn);\n  font-size: calc(8px * var(--be3-ico));\n}\n\n/* ---------------------------------------------------------------- 测距浮层\n * 🔴 位置：**左下角上方**（`bottom: 34px` 与详情浮层同一档，两者不同时出现）。\n *   为什么不做成左上/右上：左上已被距离标识占、右上被效果图标占、右下被区块清单占。\n *   测距浮层与详情浮层**互斥**（详情一开就不在测距），所以可以共用这块位置。\n * ------------------------------------------------------------------------- */\n.be3-measure {\n  position: absolute;\n  z-index: 8;\n  left: 8px;\n  bottom: 34px;\n  width: min(74%, 380px);\n  max-height: 58%;\n  overflow-y: auto;\n  padding: 6px 8px;\n  border-radius: 8px;\n  background: rgba(14, 18, 24, .96);\n  border: 1px solid var(--be3-border);\n  box-shadow: 0 6px 18px rgba(0, 0, 0, .55);\n  font-size: 11px;\n}\n.be3-measure-head { display: flex; align-items: center; gap: 6px; }\n.be3-measure-title { font-weight: 700; color: var(--be3-text); }\n.be3-measure-hint { font-size: 9.5px; margin: 2px 0 3px; line-height: 1.4; }\n.be3-measure-rows {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  max-height: 150px;\n  overflow-y: auto;\n  scrollbar-width: none;\n}\n.be3-measure-rows::-webkit-scrollbar { width: 0; height: 0; }\n.be3-measure-empty { font-size: 10px; padding: 2px 0; }\n\n/* ---------------------------------------------------------------- 测距高亮（单位 token）\n * ★★★ 第 84 窗口（用户原话）：\n *   「点击地图上的单位，会**浮起来，还会虚化**，导致不是很明显，这个效果我们也可以**不要**\n *     （点击浮空 + 虚化）。」\n *\n * 🔴 修前有两处「点击后变形」的效果，**都删掉**：\n *   ① **虚化**：`.be3-canvas.is-measuring .be3-node:not(...) { opacity: .55 }`\n *      —— 点一个单位，**其它所有单位都变淡 45%**。用户说的「不明显」就是指这个：\n *      想对比距离，结果旁边的人先糊掉了。\n *   ② **浮空**：`.is-measure-from/.is-measure-to` 的 `0 0 0 2px + 0 0 10px` 外发光\n *      —— 圆点外面套一圈光晕，视觉上像「飘起来」了一截。\n *\n * ⇒ 现在：**点击不再改变任何单位的观感**。\n *   起点/目标靠**线本身**（+ 中点米数药丸）表达 —— 这正是 Stage_1 的做法：\n *   它没有给 token 加过任何测距态样式。\n * ⚠️ 但 class 仍然**会发**（`is-measure-from` / `is-measure-to` / `is-focused`）：\n *   · 判据要验「点了谁」（结构事实，与观感无关）\n *   · 将来若要做「只加一圈细描边、不加光晕」也有挂钩点\n *   ⇒ 删的是**样式**，不是状态。\n */\n/* （原 `.is-measure-from` / `.is-measure-to` 的发光规则已删除 —— 见上面 ②） */\n/* （原 `.is-measuring ... { opacity: .55 }` 的虚化规则已删除 —— 见上面 ①） */\n/* 🔴 第 85 窗口：`.is-measuring` 也**不再强行显示名字**（那会让 token 变高 ⇒ 「浮起来」）。\n   名字一律只由 `Aa` 开关管。 */\n\n/* 测距/详情打开时把角部浮层让位（与 `.is-detail-open` 同一条规矩） */\n.be3-canvas.is-measuring .be3-map-side,\n.be3-canvas.is-measuring .be3-dist-badges { opacity: .4; }\n\n/* ---------------------------------------------------------------- 左下控件条\n * ★ Stage_1 的 `.be-field-ctl`：22×22 方钮 + 3px 间隔 + 中间一条分隔线。\n * 🔴 三组旋钮视觉上必须分得开（Stage_1 原话）：左边管**地图**、中间管**图标**、\n *   右边是**两个开关**（名字 / 距离线）。图标组用紫色，开关用绿色（`is-on`）。\n * ------------------------------------------------------------------------- */\n.be3-map-zoom {\n  position: absolute;\n  left: 6px;\n  bottom: 6px;\n  z-index: 6;\n  display: flex;\n  align-items: center;\n  gap: 3px;\n}\n.be3-ctl-btn {\n  width: 22px;\n  height: 22px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: 1px solid var(--be3-border);\n  background: rgba(20, 24, 30, .88);\n  color: var(--be3-text-muted);\n  cursor: pointer;\n  padding: 0;\n  font-size: 12px;\n  line-height: 1;\n  transition: color .14s ease, border-color .14s ease, background .14s ease;\n}\n.be3-ctl-btn:hover:not(:disabled) { color: var(--be3-primary, var(--be3-accent)); border-color: var(--be3-accent); }\n.be3-ctl-btn:disabled { opacity: .35; cursor: default; }\n.be3-ctl-zoom {\n  min-width: 34px;\n  text-align: center;\n  font-size: 9.5px;\n  color: var(--be3-text-muted);\n  font-variant-numeric: tabular-nums;\n  user-select: none;\n}\n.be3-ctl-sep {\n  width: 1px;\n  height: 14px;\n  margin: 0 2px;\n  background: var(--be3-border-strong);\n  flex: 0 0 auto;\n}\n/* 图标缩放组：紫色（与地图缩放的中性色区分） */\n.be3-ctl-btn.is-ico { color: var(--be3-summon); border-color: rgba(169, 123, 214, .45); }\n.be3-ctl-btn.is-ico:hover:not(:disabled) { color: var(--be3-summon); border-color: var(--be3-summon); }\n/* 开关（Aa / ⇢）：关着是中性的，打开是绿色 + 淡绿底 */\n.be3-ctl-btn.is-names,\n.be3-ctl-btn.is-links { color: var(--be3-text-muted); }\n.be3-ctl-btn.is-names.is-on,\n.be3-ctl-btn.is-links.is-on {\n  color: var(--be3-ok);\n  border-color: var(--be3-ok);\n  background: rgba(76, 191, 122, .14);\n}\n\n/* ---------------------------------------------------------------- 详情浮层\n * 🔴 尺寸：**只占下半部分**（`max-height: 62%` + 靠左下）。\n *   修前 `left/right: 8px` 铺满整张画布 ⇒ 详情一开地图基本看不见，\n *   而玩家点详情正是想「边看说明边看地图」（实测截图：浮层盖掉大半个战场）。\n * ------------------------------------------------------------------------- */\n.be3-mapd {\n  position: absolute;\n  z-index: 8;\n  left: 8px;\n  bottom: 34px;\n  width: min(74%, 420px);\n  max-height: 62%;\n  overflow-y: auto;\n  padding: 6px 8px;\n  border-radius: 8px;\n  background: rgba(14, 18, 24, .96);\n  border: 1px solid var(--be3-border);\n  box-shadow: 0 6px 18px rgba(0, 0, 0, .55);\n  font-size: 11px;\n}\n.be3-mapd-head { display: flex; align-items: center; gap: 6px; }\n.be3-mapd-glyph { font-size: 15px; }\n.be3-mapd-title { font-weight: 700; }\n.be3-mapd-cls {\n  font-size: 10px; padding: 0 5px; border-radius: 6px;\n  background: rgba(91, 141, 239, .18); color: var(--be3-accent);\n}\n.be3-mapd-note { margin: 3px 0; color: var(--be3-text); line-height: 1.5; }\n.be3-mapd-rows { display: flex; flex-direction: column; gap: 1px; }\n.be3-mapd-row { display: flex; align-items: baseline; gap: 6px; }\n.be3-mapd-row i {\n  flex: 0 0 56px; font-style: normal; color: var(--be3-text-muted); font-size: 10px;\n}\n.be3-mapd-row b { font-weight: 600; }\n.be3-mapd-sec { margin-top: 4px; }\n.be3-mapd-sec > i {\n  font-style: normal; color: var(--be3-text-muted); font-size: 10px;\n  display: block; margin-bottom: 2px;\n}\n.be3-mapd-units { display: flex; flex-wrap: wrap; gap: 3px; }\n.be3-mapd-unit {\n  display: inline-flex; align-items: center; gap: 2px;\n  padding: 0 5px; border-radius: 6px; font-size: 10px;\n  background: rgba(255, 255, 255, .06);\n  border: 1px solid var(--be3-border);\n}\n.be3-mapd-unit i { font-style: normal; font-size: 9px; color: var(--be3-text-muted); }\n.be3-mapd-unit.is-self { border-color: var(--be3-self); }\n.be3-mapd-unit.is-enemy { border-color: var(--be3-enemy); }\n.be3-mapd-unit.is-ally, .be3-mapd-unit.is-summon { border-color: var(--be3-ally); }\n.be3-mapd-why { font-size: 9.5px; line-height: 1.45; }\n/* 详情打开时把角部浮层让位（否则浮层与清单打架） */\n.be3-canvas.is-detail-open .be3-map-side { opacity: .35; pointer-events: none; }\n\n/* ---------------- 画布缩放控件（旧结构残留，仍被 render.js 的旧渲染器用到） ----------------\n * 🔴 保留这几条是因为 `render.js` 的 `renderCanvas`（map-render 缺失时的降级路径）\n *   仍然会输出 `.be3-canvas-tools` / `.be3-zoom-label`。\n *   ⚠️ 不要因为「新渲染器不用它」就删掉 —— 删了降级路径会变成「有按钮但没样式」。\n * ------------------------------------------------------------------------- */\n.be3-canvas-tools { display: flex; align-items: center; gap: 3px; }\n.be3-btn.is-mini { padding: 0 5px; font-size: 11px; line-height: 16px; }\n.be3-zoom-label { font-variant-numeric: tabular-nums; min-width: 30px; text-align: center; }\n.be3-btn.is-ico { color: var(--be3-summon); border-color: rgba(169, 123, 214, .45); }\n\n/* ---------------- 背包 / 装备 / 资源技能 ---------------- */\n.be3-inv, .be3-equip, .be3-resbar {\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n  border-radius: 8px; padding: 7px 9px;\n}\n.be3-inv-head { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-tab {\n  padding: 1px 8px; border-radius: 7px; cursor: pointer; font-size: 11px;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n}\n.be3-tab.is-on { background: var(--be3-accent); border-color: var(--be3-accent); color: #fff; }\n.be3-inv-filter { margin: 5px 0 4px; }\n.be3-inv-search {\n  width: 100%; box-sizing: border-box; padding: 3px 7px; font-size: 12px;\n  background: var(--be3-bg); color: var(--be3-text);\n  border: 1px solid var(--be3-border); border-radius: 6px;\n}\n.be3-inv-search:focus { outline: none; border-color: var(--be3-accent); }\n.be3-chip-btn {\n  font-size: 10px; padding: 0 6px; border-radius: 9px; cursor: pointer;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border);\n}\n.be3-chip-btn.is-on { border-color: var(--be3-accent); color: var(--be3-accent); }\n.be3-chip-btn > i { font-style: normal; opacity: .65; margin-left: 3px; }\n\n/* ============================================================================\n * 背包网格（4 列 · 方格 · 数量角标 · 名称两行截断）\n * ----------------------------------------------------------------------------\n * 🔴🔴 **本段最难查的一个真 bug（Stage_1 真机踩过，原注释在\n *   `Stage_1/src/ui/styles.css:3608-3644`）——照抄结论，别重犯**：\n *   `max-height` / `overflow` **绝不能加在 `.be3-bag-grid` 自己身上**，\n *   必须加在外层 `.be3-bag-grid-wrap`。\n *\n *   踩坑经过：给网格加 `max-height + overflow-y:auto` 之后，\n *   **格子里的道具名全部不显示**（有边框、有数量角标，就是没有字）。\n *   而三条最自然的判据**全部通过**：\n *     · 格子数对（52 个都在）\n *     · 格子尺寸正常（88×88）\n *     · 格子 `innerText` 正常（文字在，只是没画出来）\n *   根因：`overflow-y:auto` 让网格成为独立合成层，而子项用了\n *   `aspect-ratio:1` + `-webkit-line-clamp`（`display:-webkit-box`）\n *   ⇒ Chromium 在该组合下把文字画到了错误的层级/位置。\n *   🔴 **唯一能抓到它的手段是截图肉眼看**（把 max-height 去掉，字立刻出现）。\n *\n *   ⇒ 修法：外面套一层滚动容器（wrap），网格本身 `display:grid` 且\n *     **不裁剪、不滚动**。可滚的是 wrap，框选方框也挂在 wrap 上。\n *   ⚠️ 回归防线：改这段之后**必须截图看一眼**，判据抓不到这一条。\n * ==========================================================================*/\n.be3-bag-grid-wrap {\n  position: relative;          /* 框选方框的包含块（必须） */\n  max-height: 286px;           /* ≈ 3 行方格（含间隙），超出自己滚 */\n  overflow-y: auto;\n  overflow-x: hidden;\n  padding-right: 2px;          /* 给滚动条留余量，别贴住卡片边 */\n  margin-top: 4px;\n}\n/* 🔴 网格自己**不裁剪、不滚动** —— 见上面那段说明（直接给它 overflow 会让文字消失） */\n.be3-bag-grid-wrap > .be3-bag-grid { overflow: visible; max-height: none; }\n\n.be3-bag-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 5px;\n  /* 拖选时浏览器默认会选中文本（整片蓝底），手感立刻变「黏」 */\n  user-select: none; -webkit-user-select: none;\n}\n.be3-bag-cell {\n  position: relative;\n  aspect-ratio: 1;\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 1px; padding: 3px;\n  background: #10141a;\n  border: 1px solid var(--be3-border);\n  border-radius: 6px;\n  color: var(--be3-text-dim, var(--be3-text-muted));\n  cursor: pointer;\n  overflow: hidden;            /* ⚠️ 这一条在**格子**上是对的：它裁的是自己的内容，不是网格 */\n}\n.be3-bag-cell:hover { border-color: var(--be3-accent); color: var(--be3-text); }\n.be3-bag-cell.is-warehouse { opacity: .72; border-style: dashed; }\n.be3-bag-cell.is-open { border-color: var(--be3-accent); background: var(--be3-surface-2); }\n/* 框选选中态：实心底 + 左上角勾。\n   ⚠️ 与 `is-open`（详情展开）**刻意用不同视觉**：选中 = 批量操作会作用于它，\n      展开 = 详情区显示它。两者可同时成立，所以是两个独立的类。 */\n.be3-bag-cell.is-multi {\n  border-color: var(--be3-accent); background: #1d2c3d; color: var(--be3-text);\n  box-shadow: inset 0 0 0 1px var(--be3-accent);\n}\n.be3-bag-cell.is-multi::after {\n  content: '✓'; position: absolute; top: 0; left: 0;\n  padding: 0 3px; font-size: 9px; line-height: 1.4;\n  border-radius: 0 0 4px 0;\n  background: var(--be3-accent); color: #0d1117; font-weight: 700;\n}\n/* 拖选时禁止格子自己的过渡（快速划过会闪成一片） */\n.be3-bag-cell.is-multi { transition: none; }\n\n/* 数量角标：左上角，小圆角，不占布局（绝对定位） */\n.be3-bag-qty {\n  position: absolute; top: 1px; left: 1px;\n  font-size: 9.5px; line-height: 1.35; padding: 0 3px;\n  border-radius: 5px;\n  background: var(--be3-bg); color: var(--be3-accent);\n  font-variant-numeric: tabular-nums;\n  max-width: 80%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n/* 名称：**两行截断**（一行装不下中文道具名，三行会把 88px 的格子撑破） */\n.be3-bag-name {\n  font-size: 10.5px; line-height: 1.25; text-align: center;\n  width: 100%; padding: 0 1px;\n  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;\n  overflow: hidden; word-break: break-all;\n}\n/* 操作按钮：默认半透明，hover 才完全显形（小格子里三个按钮常驻太吵） */\n.be3-bag-ops {\n  display: flex; gap: 2px; justify-content: center;\n  opacity: .55; transition: opacity .12s;\n}\n.be3-bag-cell:hover .be3-bag-ops { opacity: 1; }\n.be3-bag-ops .be3-op { padding: 0 3px; line-height: 14px; font-size: 9.5px; }\n\n/* 展开的效果正文：放在**网格下方**，不塞进格子里（否则整行被撑高、邻格被挤扁） */\n.be3-bag-detail {\n  margin-top: 6px; padding: 5px 7px;\n  background: var(--be3-surface); border: 1px solid var(--be3-border);\n  border-radius: 6px;\n}\n.be3-bag-detail-head { display: flex; align-items: center; gap: 6px; font-size: 11px; margin-bottom: 3px; }\n\n/* 框选方框：**绝不吃指针事件**（否则它会盖住格子，hover 效果在框选时消失） */\n.be3-bag-marquee {\n  position: absolute;\n  z-index: 5;\n  pointer-events: none;\n  border: 1px solid var(--be3-accent);\n  background: rgba(91, 141, 239, .16);\n  border-radius: 2px;\n}\n\n.be3-item-list { max-height: 260px; overflow: auto; margin-top: 4px; }\n.be3-item { border-top: 1px solid var(--be3-border); padding: 2px 0; }\n.be3-item:first-child { border-top: none; }\n.be3-item.is-warehouse { opacity: .78; }\n.be3-item.is-open { background: var(--be3-surface-2); border-radius: 5px; padding: 2px 5px; }\n.be3-item-head { display: flex; align-items: center; gap: 5px; min-width: 0; }\n.be3-item-name {\n  font-size: 12px; font-weight: 500;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  flex: 0 1 auto; min-width: 0;\n}\n.be3-item-qty {\n  font-variant-numeric: tabular-nums; color: var(--be3-accent);\n  font-size: 11px; flex: 0 0 auto;\n}\n.be3-item-quality { font-size: 10px; color: var(--be3-warn); flex: 0 0 auto; }\n.be3-item-ops { display: flex; gap: 2px; flex: 0 0 auto; }\n.be3-op {\n  padding: 0 5px; line-height: 16px; font-size: 10px; cursor: pointer;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border); border-radius: 4px;\n}\n.be3-op:hover:not([disabled]) { color: var(--be3-text); border-color: var(--be3-text-muted); }\n.be3-op.is-on { color: var(--be3-accent); border-color: var(--be3-accent); }\n.be3-op.is-danger:hover:not([disabled]) { color: var(--be3-danger); border-color: var(--be3-danger); }\n.be3-op[disabled] { opacity: .35; cursor: not-allowed; }\n.be3-item-detail { padding: 4px 2px 5px; }\n.be3-item-effect {\n  font-size: 11px; line-height: 1.65; color: var(--be3-text);\n  background: var(--be3-bg); border-radius: 4px; padding: 5px 7px;\n  white-space: pre-wrap; word-break: break-word;\n}\n.be3-inv-foot {\n  display: flex; justify-content: space-between; gap: 8px;\n  font-size: 10px; margin-top: 5px; flex-wrap: wrap;\n}\n\n.be3-slots { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; margin: 5px 0; }\n.be3-slot {\n  display: flex; align-items: center; gap: 4px; font-size: 11px;\n  background: var(--be3-surface-2); border: 1px solid var(--be3-border);\n  border-radius: 5px; padding: 1px 6px; min-width: 0;\n}\n.be3-slot.is-filled { border-color: var(--be3-accent); }\n.be3-slot-label { color: var(--be3-text-muted); font-size: 10px; flex: 0 0 auto; }\n.be3-slot-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.be3-chip.is-ac { border-color: var(--be3-ok); }\n.be3-chip.is-ac > i { color: var(--be3-text-muted); font-style: normal; margin-left: 4px; font-size: 10px; }\n\n/* ============================================================================\n * 资源技能：**统一大小 + 网格化 + 过多时纵向滚动**（第 72 窗口 UI 轮，用户要求）\n *\n * 🔴 修前是 `flex: 1 1 30%` 的横向换行：格子宽度随名字长短变化\n *   （「吟行」2 字 vs 「单翼的闪耀一击」7 字 ⇒ 宽度差一倍），排出来参差不齐；\n *   数量一多就把卡片撑得很高，把下面的技能栏挤没。\n * ⇒ 现在 `display:grid` + `auto-fill/minmax` 定宽列：\n *   ① **每格等宽等高**（`align-items:stretch` + 固定行高），视觉整齐；\n *   ② **列数自适应**（面板窄时自动降列数，不用 JS 算、不处理 resize）；\n *   ③ **超过 4 行就内部滚动**（`max-height` + `overflow-y:auto`），\n *      不再无限增高 —— 与背包/日志同一条纪律。\n * ⚠️ 滚动容器必须带 `data-be3-scroll=\"res\"`：面板每次重绘都换 `innerHTML`，\n *   不标记就找不回滚动位置（`scroll-keep.js` 认这个属性）。\n * ==========================================================================*/\n.be3-res-row {\n  display: grid;\n  /* ① 定宽列：`auto-fill` 让列数随容器变化，`minmax(104px, 1fr)` 保证不挤成一团 */\n  grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));\n  gap: 4px;\n  margin-top: 4px;\n  /* ③ 多了就滚：约 4 行高（每行 46px + 间隙） */\n  max-height: 208px;\n  overflow-y: auto;\n  overflow-x: hidden;\n  /* 滚动条不与圆角/border 打架 */\n  padding-right: 2px;\n}\n.be3-res {\n  position: relative;                    /* 图标绝对定位靠它 */\n  /* ② 等高：grid 的 stretch 是默认值，这里显式写出来表明是**有意**的 */\n  align-self: stretch;\n  min-height: 46px;                      /* 统一高度：不满一行的格子也要一样高 */\n  display: flex; flex-direction: column; align-items: stretch; gap: 2px;\n  padding: 4px 6px 4px 26px;             /* 左侧留出图标的位置 */\n  cursor: pointer; text-align: left;\n  background: var(--be3-surface-2); color: var(--be3-text);\n  border: 1px solid var(--be3-border); border-radius: 6px;\n  border-left: 3px solid var(--be3-ok);\n  font-size: 11px;\n  /* 内容不许把格子撑破（名字太长时省略号，见 .be3-res-name） */\n  overflow: hidden;\n}\n/* 资源技能的**等宽独立图标**：与 6+3/觉醒在视觉上立刻可辨，\n   而不是靠读「不占槽位」那行小字（玩家实战中不会读）。\n   ⚠️ 绝对定位到左侧：留在流里会**独占一行**（图标 18px + 名字 + 条 + 数字\n      竖着排，把卡片撑高一截，截图里一眼就看得见）。\n   ⚠️ 名字与图标**都保留**：图标只做「一眼分类」，可读信息不许只放在图标里。 */\n.be3-res-icon {\n  position: absolute; left: 7px; top: 5px;\n  width: 18px; height: 18px; line-height: 18px;\n  text-align: center; font-size: 12px;\n  border-radius: 5px; background: var(--be3-bg);\n}\n.be3-res.is-out .be3-res-icon { opacity: .5; }\n.be3-res:hover:not([disabled]) { border-color: var(--be3-text); }\n.be3-res.is-low { border-left-color: var(--be3-warn); }\n.be3-res.is-out { opacity: .45; cursor: not-allowed; border-left-color: var(--be3-border); }\n.be3-res.is-used { outline: 1px solid var(--be3-ok); }\n.be3-res-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.be3-res-bar { display: block; height: 3px; background: var(--be3-bg); border-radius: 2px; overflow: hidden; flex: 0 0 auto; }\n.be3-res-bar > i { display: block; height: 100%; background: var(--be3-ok); }\n.be3-res.is-low .be3-res-bar > i { background: var(--be3-warn); }\n.be3-res.is-out .be3-res-bar > i { background: var(--be3-danger); }\n.be3-res-num { font-size: 10px; color: var(--be3-text-muted); font-variant-numeric: tabular-nums; flex: 0 0 auto; margin-top: auto; }\n\n/* 资源技能与 6+3 / 觉醒的视觉区分：绿色左条 + 「不占槽位」说明 */\n.be3-resbar-head { margin-bottom: 2px; }\n\n/* 分页条 */\n.be3-pager { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 6px; }\n\n\n/* ============================================================================\n * 第 64 窗口：骨架补充（顶栏元信息 / 左栏小节 / HUD 空态 / 小队空位 /\n *                     底部两条通栏 / 发言栏 / 四角缩放）\n * ==========================================================================*/\n\n/* ---- 顶栏元信息 ---- */\n.be3-meta > b { font-weight: 600; color: var(--be3-text); max-width: 260px;\n  display: inline-block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  vertical-align: bottom; }\n\n/* ---- 左栏小节 ---- */\n.be3-side-section { border-bottom: 1px solid var(--be3-border); }\n.be3-side-section:last-child { border-bottom: none; }\n.be3-side-head {\n  display: flex; align-items: center; gap: 6px;\n  padding: 9px 10px;\n  font-size: 12.5px; font-weight: 600;\n  background: var(--be3-surface-3);\n  cursor: pointer; user-select: none;\n}\n.be3-side-head:hover { background: #232b36; }\n.be3-side-arrow { color: var(--be3-text-muted); font-size: 10px; }\n.be3-side-body { padding: 9px 10px; display: flex; flex-direction: column; gap: 6px; }\n\n/* ---- HUD 空态：**一行矮横条**（不是大方框）----\n * 🔴 实测史（第 72 窗口 UI 轮）：原来是「大图标 + 两行说明 + padding 26x2」⇒ 整块 110px，\n *   把【战场】和【小队】都推出首屏；而它要表达的只是「暂无敌人」。\n *   用户要求「点开就能同时看到战场和小队头像」⇒ 空态不许比真实内容还高。\n * ⇒ 现在图标与文字**同一行**（row + wrap），高度约 34px，省出 ~76px。\n * ⚠️ 空态**不能删**：删了「暂无敌人」与「面板坏了」就无法区分。\n * ========================================================================*/\n.be3-hud-empty {\n  display: flex; flex-direction: row; align-items: center; justify-content: center;\n  flex-wrap: wrap; gap: 5px; padding: 3px 10px;\n  background: var(--be3-surface);\n  border: 1px dashed var(--be3-border);\n  border-radius: 6px;\n  font-size: 12px;\n}\n.be3-hud-empty-icon { font-size: 22px; color: var(--be3-text-muted); opacity: .6; }\n.be3-hud-bar { display: block; height: 4px; border-radius: 2px; background: var(--be3-bg); overflow: hidden; }\n.be3-hud-bar > i { display: block; height: 100%; background: var(--be3-enemy); }\n\n/* ============================================================================\n * 小队：**等宽三格 + 大头像**（第 72 窗口 UI 轮，照用户线框图）\n *\n * 线框图版式（逐块照抄）：\n *   ┌─────────────┐\n *   │             │\n *   │  [ 头像 ]   │  ← 头像占主体、居中\n *   │             │\n *   ├─────────────┤\n *   │ 拉缇娜 [主角]│  ← 名字 + 角色标签（标签不与名字抢宽度）\n *   │ HP  ■■■ 828 │  ← HP 条 + 数字\n *   │ SAN [  ]--  │  ← SAN 条 + 数字（**读不到就 --/--**）\n *   └─────────────┘\n *\n * 🔴 修前的问题（用户为什么要求改）：\n *   ① 头像很小、与名字挤一行 ⇒ 认不出是谁，辨识度全靠读名字；\n *   ② **没有 SAN 行**（线框图明确要求）；\n *   ③ 名字与标签同级，长名字会把标签挤掉。\n * ==========================================================================*/\n.be3-squad {\n  display: grid;\n  /* 🔴 必须给**最小宽度**（minmax），不能写 1fr：\n     面板拉窄时 1fr 会把每格压到 ~78px，名字与「主角」标签直接重叠\n     （实测截图：拉缇娜 和 主角 叠在一起）。\n     minmax(104px, 1fr) ⇒ 窄到放不下就**横向滚动**（沿用原设计的 overflow-x），\n     而不是把内容挤烂。104px 是「三字名 + 两字标签」在 11.5px 下的实测下限。 */\n  /* 🔴 第 72 窗口（UI 轮二次）：**收窄每格**以适配竖长头像。\n     用户原话：「你可以适当收缩小队栏内每个子单位卡片的宽度，以适配头像」。\n     写法：给 max 上限（140px）+ `space-between` ⇒ 宽面板时格子**保持窄**、\n     多余宽度变成间隙；而不是像 `1fr` 那样把格子拉宽、把头像拉成横长条。 */\n  /* 🔴 与【当前目标】同一套规则（用户明确要求）：\n     定宽 + 紧凑 gap + **多了横向滚动**，不用 `space-between` 撑开。\n     修前 `space-between` 会把三格分散到整行两端，队友之间空很远。 */\n  grid-auto-flow: column;\n  grid-auto-columns: 104px;\n  grid-template-columns: none;\n  justify-content: start;\n  gap: 6px;\n  overflow-x: auto;\n  padding-bottom: 2px;\n}\n.be3-sq {\n  /* 🔴 gap/padding 收得很紧：文字区整体只有 ~40px，靠这三行撑住（见下）。 */\n  display: flex; flex-direction: column; gap: 0;\n  padding: 0 0 2px; min-width: 0; overflow: hidden;\n  background: var(--be3-surface);\n  border: 1px solid var(--be3-border);\n  border-left: 3px solid var(--be3-ally);\n  border-radius: 7px;\n}\n.be3-sq.is-self { border-left-color: var(--be3-self); }\n.be3-sq.is-empty {\n  border-left-color: var(--be3-border);\n  border-style: dashed;\n  align-items: center; justify-content: center;\n  text-align: center; min-height: 100px; padding: 6px 6px;\n}\n.be3-sq-ph { font-size: 16px; opacity: .85; }\n.be3-sq.is-empty .be3-sq-ph { color: var(--be3-border-strong); }\n\n/* ============================================================================\n * ① 头像区：**铺满卡片宽度、无留白**（第 72 窗口 UI 轮复核）\n *\n * 🔴 修前这里是「62×62 小图 + 居中 + padding:8px 0 6px」\n *   ⇒ 用户对比图一眼看出「头像很小一个放在中间上部」。\n * 🔴 用户的参考图里头像是**满宽**的：从卡片左边缘到右边缘，约占卡片 55% 高度。\n * ⇒ 现在：\n *    · 容器 `padding: 0`（无留白）；\n *    · 头像用**固定宽高比**（`aspect-ratio: 1 / 1`）撑满宽度，而不是写死 px ——\n *      三格并排时每格宽度随面板变（~120px 起），写死 62px 就会在小面板上显得更小；\n *    · `object-fit: cover` 裁切不变形（头像原图多为竖构图，不裁会留黑边）。\n * ⚠️ `aspect-ratio` 必须带 `width:100%`，否则 flex 容器里会塌成 0 高。\n * ⚠️ 圆角只给**上方两角**：下边缘要与名字区贴合（参考图就是这样）。\n * ==========================================================================*/\n.be3-sq-portrait {\n  display: block; width: 100%;\n  /* 6px 小内边距：参考图里头像四周有一圈卡片底色（不是贴边到边框）。\n     同一处改了两轮，两次都错在同一个方向，记下来：\n       · 第一版 padding 8px 0 6px + 62x62 小图 => 头像很小一个、居中上部；\n       · 第二版 padding 0 + aspect-ratio 1/1 铺满 => 头像过高，\n         把名字/HP/SAN 全挤出小队卡可见区（截图里只剩一个头像）。\n     => 现在的口径：满宽 + 固定高度 + 6px 边距，高度按参考图实测\n       （182x255 的卡，头像约 166x140 => 占高 55%、占宽 91%）。 */\n  padding: 6px 6px 5px;\n  background: var(--be3-bg);\n}\n.be3-sq-portrait .be3-avatar.is-squad {\n  display: block; width: 100%;\n  /* 固定高度而不是 aspect-ratio：三格并排时格子宽度随面板变（约 150-240px），\n     aspect-ratio 会让头像高度跟着宽度膨胀，宽面板时又把下面的行挤没了。\n     固定 132px => 无论面板多宽，头像高度恒定，下面三行永远看得见。 */\n  /* 🔴 头像:文字 = **八二开**（用户明确要求）。\n     150px 是配合下面「文字区压到 ~40px」算出来的：\n     头像块 150+9(内边距) = 159；文字区 ≈ 40 ⇒ 159/199 ≈ 80%。\n     实测过的两档反例：62px(太小)、116px(约 68:32，用户说「仍然很宽」)。 */\n  /* 🔴 头像:文字 = **八二开**（用户明确要求）。\n     178px + 上下 padding 11 = 189；实测文字区 ≈ 48 ⇒ 189/237 ≈ 0.80。\n     三档实测反例：62px(太小) / 116px(0.74，用户说「仍然很宽」) / 150px(0.77，仍偏宽)。 */\n  /* 🔴 用户第二轮：「整体高度还可以调一调，再压缩一些」，同时要求保持八二开。\n     150px + 上下 padding 11 = 161；文字区 ~40 ⇒ 161/201 ≈ 0.80（仍达标）。\n     四档实测：62px(太小) / 116px(0.74 偏宽) / 150px(0.77) / 178px(0.81 但整体过高)。 */\n  /* 🔴 用户用红线标了期望比例：战场更矮、小队更高（约 1 : 1.8）。\n     168 + 上下 padding 11 = 179；文字区 ~39 ⇒ 179/218 ≈ 0.82（仍守住八二开）。 */\n  /* 🔴 168 → 76：用户要求「小队整体单位高度至少砍一半」（218 → ~104）。\n     76 + 上下 padding 11 = 87；文字区 17 ⇒ 87/104 ≈ 0.84 —— **八二开保住**。\n     ⚠️ 试过 54px：比例掉到 0.61（判据当场红）—— 头像不能压得比文字区还小。 */\n  height: 76px;\n  border-radius: 6px;               /* 参考图里头像是四角圆的独立块 */\n  border: 1px solid var(--be3-border);\n}\n.be3-sq-portrait .be3-avatar.is-squad > img {\n  display: block; width: 100%; height: 100%;\n  object-fit: cover;\n  object-position: center top;      /* 脸在上半部，宁可裁下不裁上 */\n  border-radius: 6px;\n}\n\n/* ② 名字 + 角色标签：**分两行层级**（标签不再和名字抢宽度） */\n.be3-sq-id {\n  /* 🔴 名字与标签**同一行**（参考图就是这样），不换行。\n     窄格（三格并排时每格约 120px）靠字号与内边距让步来塞下，\n     不靠换行 —— 换行会让「主角」掉到第二行，与参考图不符。 */\n  /* 🔴 名字与标签合并成**一行**（卡高被砍半，三行放不下）：\n     用 `1fr` 让名字吃掉剩余宽度、标签固定宽度贴右。 */\n  display: flex; align-items: baseline; gap: 3px;\n  padding: 0 4px; min-width: 0; line-height: 1.0;\n}\n/* 🔴 名字**不截断**（修前 `text-overflow: ellipsis` 把「拉缇娜」压成「拉...」，\n   而人名是卡上最主要的识别信息）。用 `nowrap` + 可收缩 + 最小字号保证整名显示；\n   实在放不下时由 flex 让标签换行（`flex-wrap` 在标签上单独控制）。 */\n.be3-sq-name {\n  font-size: 10.5px; font-weight: 600; min-width: 0; flex: 0 1 auto;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.0;\n}\n.be3-sq-tag {\n  flex: 0 0 auto;\n  font-style: normal; font-size: 8.5px; font-weight: 400;\n  padding: 0 3px; border-radius: 3px; line-height: 1.4;\n  background: var(--be3-surface-2); color: var(--be3-text-muted);\n  white-space: nowrap;\n}\n.be3-sq-tag.is-self { color: var(--be3-self); }\n.be3-sq-lv {\n  font-size: 10px; color: var(--be3-text-muted);\n  padding: 0 7px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n\n/* ③ 资源行（HP / SAN）：标签 + 条 + 数字，**三格等宽对齐** */\n/* 🔴 文字区三行必须是**最小可读行高**：用户要「整体再压一些」同时保「八二开」，\n   两头夹的结果就是这里。再小字号就不可读了，所以压行高而不是字号。 */\n/* 🔴 HP 与 SAN **并排一行**：卡高砍半后垂直空间不够放两行。\n   横排后：HP 条 + 数值 · SAN 条 + 数值，各占一半宽度。 */\n/* 🔴 文字区总高必须 ~17px（名字行 11 + vitals 行 10 − 重叠）。\n   靠 `line-height: 1` + 零 gap 挤出来，**不再缩字号**（9px 是可读下限）。 */\n/* ★★ 第 81 窗口：**HP 与 SAN 必须**分两行**（用户第 5 条原话：\n *   「HP 828/828 和 San --/-- 在视觉上连一起了，稍微分开点距离」）。\n *\n * 🔴 修前是 `display:flex` + 两个 `flex:1 1 0` 的子行 ⇒ 两行**并排**挤在\n *   约 110px 宽的卡片底部：左边 `HP ▬ 828/828`、右边 `SAN ▬ --/--`，\n *   而两段的字都是 9px 灰字 ⇒ 看起来就是 `HP 828/828SAN --/--` 粘成一串。\n *   🧪 这也是「结构判据全绿、只有截图能看出」的典型：DOM 里两行都在、文字都对。\n * ⇒ 改成**竖排**（`flex-direction: column`），两行各占一行、行距 3px；\n *   条（bar）在行内继续 `flex: 1 1 auto` 撑开 ⇒ 数字仍然右对齐，读起来是两行账。\n */\n.be3-sq-vitals {\n  display: flex;\n  flex-direction: column;\n  align-items: stretch;\n  gap: 3px;\n  padding: 1px 4px 2px;\n  line-height: 1;\n}\n.be3-sq-vitals > .be3-sq-line { flex: 0 0 auto; min-width: 0; gap: 4px; padding: 0; }\n.be3-sq-line { display: flex; align-items: center; gap: 4px; padding: 0 4px; line-height: 1.0; }\n.be3-sq-k { font-size: 9px; color: var(--be3-text-muted); flex: 0 0 auto; }\n.be3-sq-bar { flex: 1 1 auto; height: 4px; border-radius: 2px; background: var(--be3-bg); overflow: hidden; }\n.be3-sq-bar > i { display: block; height: 100%; background: var(--be3-ok); }\n/* 🔴 SAN 未知：条**不填色**且加斜纹，避免「空条」被误读成「理智耗尽」 */\n.be3-sq-bar.is-san.is-unknown {\n  background: repeating-linear-gradient(45deg, var(--be3-bg), var(--be3-bg) 3px,\n    var(--be3-surface-2) 3px, var(--be3-surface-2) 6px);\n}\n.be3-sq-num { font-size: 9px; color: var(--be3-text-muted); font-variant-numeric: tabular-nums; flex: 0 0 auto; }\n\n/* ---- 底部两条通栏 ---- */\n.be3-usage {\n  display: flex; align-items: center; gap: 8px;\n  flex: 0 0 auto;\n  padding: 5px 12px;\n  background: #10141a;\n  border-top: 1px solid var(--be3-border);\n  overflow-x: auto;\n  font-size: 11.5px;\n}\n.be3-usage.is-second { padding-top: 0; border-top: none; }\n.be3-usage-item { color: var(--be3-text-muted); white-space: nowrap; }\n.be3-usage-item > b { color: var(--be3-text); }\n.be3-usage-idx { font-variant-numeric: tabular-nums; color: var(--be3-text-muted); min-width: 34px; text-align: center; }\n\n/* ---- 发言栏 ---- */\n.be3-chatbar {\n  display: flex; gap: 8px; align-items: stretch;\n  flex: 0 0 auto;\n  padding: 5px 12px 6px;\n  background: #12161b;\n  border-top: 1px solid var(--be3-border);\n}\n.be3-chat-input {\n  /* 🔴 min-height 42 → 32：660 高面板下要腾 10px 给【小队】进首屏。\n     32px 仍能显示两行（12.5px × 1.5 ≈ 19/行），不影响输入。 */\n  flex: 1 1 auto; resize: vertical; min-height: 32px; max-height: 120px;\n  padding: 6px 9px; font-size: 12.5px; line-height: 1.5;\n  font-family: inherit;\n  background: var(--be3-bg); color: var(--be3-text);\n  border: 1px solid var(--be3-border); border-radius: 6px;\n}\n.be3-chat-input:focus { outline: none; border-color: var(--be3-accent); }\n.be3-chat-side { display: flex; flex-direction: column; gap: 4px; flex: 0 0 auto; }\n/* ★★ 第 109 窗口：发言栏右侧那个按钮从「本地推进一回合」（7 字）变成\n   「结算战场（只看）」（8 字 + 括号）⇒ 窄面板下会被折成两行，把整条发言栏顶高。\n   🔴 理由同第 87 窗口那条真机观感 bug（`is-mini` 在窄容器里折行）：\n      只给**发言栏这两个按钮**加 nowrap，别动全局 `.be3-btn`（纯符号小方块不需要）。 */\n.be3-chat-side .be3-btn { white-space: nowrap; }\n.be3-chat-hint { font-size: 9.5px; max-width: 130px; line-height: 1.35; }\n\n/* ---- 发送状态徽标（顶栏「生成中… / 上次生成失败」） ---- */\n/*\n * 🔴 为什么必须有视觉反馈：`generate` 可能一等等十几秒。玩家看不到任何动静时\n *   会以为「按钮坏了」而连点 —— 而连点会被引擎挡掉，表现就是\n *   「点了很多次，什么都没发生」。徽标让「在跑」这件事**看得见**。\n * ⚠️ 用 `animation` 而不是 `setInterval` 改文字：动画不占 JS 线程，\n *    生成期间主线程正忙着等 await，别再抢它。\n */\n.be3-gen {\n  font-size: 10.5px; padding: 1px 7px; border-radius: 9px;\n  border: 1px solid var(--be3-border);\n  white-space: nowrap;\n}\n.be3-gen.is-busy {\n  color: var(--be3-accent);\n  border-color: var(--be3-accent);\n  animation: be3-gen-pulse 1.1s ease-in-out infinite;\n}\n.be3-gen.is-error { color: var(--be3-danger); border-color: var(--be3-danger); }\n@keyframes be3-gen-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .42; } }\n\n/* ---- 左栏配置页（第 67 窗口：从占位符变成真的能看） ---- */\n/*\n * ★★ 第 69 窗口（功能 A）：**API 配置卡片**（与主楼错开）。\n * 🔴 为什么不复用 `.be3-cfg-row`：这一节有 3 个输入框 + 4 个按钮 + 2 个徽标，\n *   套「一行键值」的样式会挤成一团。\n * ⚠️ 输入框必须**看得见自己填了什么**（深底浅字 + 明显边框）——\n *   地址填错是这一功能最常见的失败，看不见就是让玩家盲填。\n */\n.be3-api-item {\n  border: 1px solid var(--be3-border); border-radius: 6px;\n  padding: 6px 7px; margin: 5px 0; background: rgba(255, 255, 255, .02);\n}\n.be3-api-item.is-active-api { border-color: var(--be3-accent); }\n.be3-api-item.is-off { opacity: .62; }\n.be3-api-head { display: flex; align-items: center; gap: 5px; margin-bottom: 4px; }\n.be3-api-radio {\n  background: none; border: none; color: var(--be3-text-muted);\n  cursor: pointer; font-size: 12px; padding: 0 2px; line-height: 1;\n}\n.be3-api-radio.is-on { color: var(--be3-accent); }\n.be3-api-name { font-size: 11.5px; font-weight: 600; }\n.be3-api-tag {\n  font-size: 9.5px; padding: 0 5px; border-radius: 8px;\n  color: var(--be3-accent); border: 1px solid var(--be3-accent);\n}\n.be3-api-badge {\n  font-size: 9.5px; padding: 0 5px; border-radius: 8px;\n  color: var(--be3-text-muted); border: 1px solid var(--be3-border);\n}\n.be3-api-badge.is-on { color: #4cbf7a; border-color: #4cbf7a; }\n.be3-api-lab { font-size: 10px; color: var(--be3-text-muted); margin-top: 3px; display: block; }\n.be3-api-input {\n  width: 100%; box-sizing: border-box; padding: 4px 6px; margin-top: 1px;\n  font-size: 11px; font-family: inherit;\n  background: var(--be3-bg); color: var(--be3-text);\n  border: 1px solid var(--be3-border); border-radius: 4px;\n}\n.be3-api-input:focus { outline: none; border-color: var(--be3-accent); }\n/* 🔴 「我们会 POST 到」那一行必须显眼：地址补全猜错时这是玩家唯一的线索 */\n.be3-api-ep { font-size: 9.5px; color: var(--be3-text-muted); margin-top: 4px; line-height: 1.4; }\n.be3-api-ep b { color: var(--be3-accent); word-break: break-all; }\n.be3-api-bad {\n  font-size: 10px; color: var(--be3-danger); border: 1px solid var(--be3-danger);\n  border-radius: 4px; padding: 3px 5px; margin: 3px 0; line-height: 1.4;\n}\n.be3-cfg-row {\n  display: flex; align-items: baseline; gap: 6px;\n  padding: 1.5px 0; font-size: 11px;\n}\n.be3-cfg-k { flex: 0 0 auto; color: var(--be3-text-muted); }\n.be3-cfg-v {\n  flex: 1 1 auto; color: var(--be3-text); text-align: right;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-cfg-preview { margin-top: 4px; }\n.be3-cfg-preview > summary {\n  cursor: pointer; font-size: 11px; color: var(--be3-accent);\n  padding: 2px 0; user-select: none;\n}\n.be3-cfg-pre {\n  margin: 4px 0 0; padding: 6px 7px;\n  max-height: 240px; overflow: auto;\n  font: 10.5px/1.5 ui-monospace, Consolas, monospace;\n  white-space: pre-wrap; word-break: break-word;\n  background: var(--be3-bg); color: var(--be3-text-muted);\n  border: 1px solid var(--be3-border); border-radius: 5px;\n}\n\n/* ---- 四角缩放抓手（照 Stage_1 .be-rs） ---- */\n/*\n * ★★★ 第 112 窗口（用户原话）：「就四个角像浏览器那样放大缩小？以及点击顶部拖动窗口位置？」\n *\n * 🔴🔴 修前这里有两处让玩家觉得「功能没做」：\n *   ① `.be3-root { resize: both; }` —— 这是 **CSS 原生**缩放。它只在**右下角**\n *      画一个按钮，与自绘抓手 `se` **重叠**（两个都会响应，拉起来打架），\n *      而且它会把 `overflow` 改掉、打乱本面板的**分层滚动**（中栏/右栏各自滚）。\n *      ⇒ 已删除（JS 自绘四角才是唯一实现，见 `float-window.makeResizable`）。\n *   ② 抓手是 `16×16` **全透明**块 ⇒ 玩家不悬停到像素级根本发现不了「这角能拉」。\n *      ⇒ 现在**平时给一个很淡的角标记**（不刺眼），悬停/拖动时变亮变长 ——\n *        像浏览器那样「看一眼就知道能拉」，但不抢面板内容的注意力。\n */\n.be3-rs {\n  position: absolute; width: 16px; height: 16px;\n  z-index: 40; pointer-events: auto;\n  /* 平时：一条淡淡的角线（不是纯透明，否则玩家发现不了） */\n  opacity: .28; transition: opacity .12s ease;\n}\n.be3-rs:hover, .be3-rs.is-active { opacity: 1; }\n/* 角标记用两条内阴影画「L 形」，四角各自朝向 */\n.be3-rs-nw { left: 0; top: 0; cursor: nwse-resize; box-shadow: inset 3px 3px 0 0 var(--be3-accent); border-top-left-radius: var(--be3-r-lg); }\n.be3-rs-ne { right: 0; top: 0; cursor: nesw-resize; box-shadow: inset -3px -3px 0 0 var(--be3-accent); border-top-right-radius: var(--be3-r-lg); }\n.be3-rs-sw { left: 0; bottom: 0; cursor: nesw-resize; box-shadow: inset 3px -3px 0 0 var(--be3-accent); border-bottom-left-radius: var(--be3-r-lg); }\n.be3-rs-se { right: 0; bottom: 0; cursor: nwse-resize; box-shadow: inset -3px 3px 0 0 var(--be3-accent); border-bottom-right-radius: var(--be3-r-lg); }\n/*\n * 🔴 **不要**加 `.be3-root { resize: both }`（第 112 窗口删掉的）：\n *   原生 resize 只在右下角、与自绘 se 冲突、且会改 `overflow` 打乱分层滚动。\n */\n\n/* 顶栏：可拖动的手感提示（否则玩家不知道这里能按住挪窗口） */\n.be3-topbar { cursor: grab; }\n.be3-topbar:active { cursor: grabbing; }\n/* 顶栏里的控件保持正常光标（别让按钮显示成「可拖」） */\n.be3-topbar button, .be3-topbar a, .be3-topbar input,\n.be3-topbar select, .be3-topbar textarea { cursor: pointer; }\n\n/* ============================================================================\n * 悬浮球（照 Stage_1 .be-fab:38-57）\n * ----------------------------------------------------------------------------\n * 🔴 用户纠正过：「stage_1 做的是个悬浮窗」——球常驻页面角落，点它开关面板。\n *   没有球 = 一进酒馆就糊一个大窗。\n * ==========================================================================*/\n.be3-fab {\n  position: fixed;\n  z-index: 2147482000;\n  width: 52px;\n  height: 52px;\n  border-radius: 50%;\n  border: 1px solid var(--be3-border-strong, #3a4256);\n  background: radial-gradient(circle at 32% 28%, #2b3540, #10141a 78%);\n  color: var(--be3-accent, #5b8def);\n  cursor: grab;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 6px 20px rgba(0, 0, 0, .55);\n  transition: transform .12s, box-shadow .12s;\n  touch-action: none;\n  padding: 0;\n  font-size: 24px;\n  line-height: 1;\n}\n.be3-fab:hover {\n  transform: scale(1.07);\n  color: #9cc6ec;\n  box-shadow: 0 8px 28px rgba(0, 0, 0, .7);\n}\n.be3-fab:active { cursor: grabbing; }\n.be3-fab-icon { pointer-events: none; }\n\n/* ============================================================================\n * 尺寸档位（照 Stage_1 的 data-be-size，按**面板自己的像素宽**分级）\n * ----------------------------------------------------------------------------\n * 🔴 为什么不用 @media：@media 看的是**视口**，而玩家拉的是**面板**。\n *   面板拉窄了但视口没变 ⇒ 内部三栏不会跟着收（正是「拉窄了但没适配」那个问题）。\n *   ⇒ 由 float-window.js 写 data-be3-size，CSS 按它分级。\n * ⚠️ 阈值必须与 float-window.js 的 PANEL_W_MID/NARROW/TINY 一一对应。\n * ==========================================================================*/\n\n/* mid：右栏收窄 */\n/* 档位只微调**最小宽度**，不改比例（否则 7:3 在 mid 档就不成立）。 */\n.be3-root[data-be3-size=\"mid\"] .be3-col-right { min-width: 300px; }\n\n/* narrow：右栏更窄 + 左栏收窄 */\n.be3-root[data-be3-size=\"narrow\"] .be3-col-right { min-width: 280px; }\n.be3-root[data-be3-size=\"narrow\"] .be3-col-left { flex: 0 0 210px; }\n\n/* tiny：三栏挤不下 ⇒ 右栏改为下方堆叠（变成上下两段） */\n.be3-root[data-be3-size=\"tiny\"] { flex-direction: column; }\n.be3-root[data-be3-size=\"tiny\"] .be3-body { flex-direction: column; }\n.be3-root[data-be3-size=\"tiny\"] .be3-col-left { flex: 0 0 auto; max-height: 180px; border-right: none; border-bottom: 1px solid var(--be3-border); }\n/* 🔴🔴 中栏卡片的伸缩策略（第 72 窗口 UI 轮，照用户红线）：\n   只有【战场】弹性吃剩余空间；【小队】与【日志】必须固定高度、绝不压缩。\n   修前所有卡默认 `flex: 0 1 auto`（可收缩）⇒ 战场一旦 `flex: 1` 就把它们压成 0。\n   ⚠️ 这正是我上一轮「战场自适应」失败的真实原因（不是上限没给对）。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"party\"],\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"log\"],\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"hud\"] { flex: 0 0 auto; }\n/* 🔴🔴 战场卡**不可收缩**（`flex: 0 0 auto`）：高度由画布的固定 300px 决定。\n   修前这里写 `flex: 1 1 auto` ⇒ 中栏内容超高时 flex 把它从 300 压到 **167px**，\n   而 SVG 仍按 292px 渲染 ⇒ 底部被 `overflow:hidden` 裁掉（单位图标只剩上半身）。\n   ⇒ 超高时让**中栏自己滚**（见 .be3-col-center 的 overflow-y），而不是压内容。\n   这正是用户说的「多的靠滚轮自己去找」。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"field\"] {\n  flex: 0 0 auto; display: block;\n}\n/* 战场卡内部：卡体要能把高度传给画布 */\n/* 战场卡体：正常流式布局即可（画布是固定高度，不需要 flex 传递）。 */\n.be3-root .be3-col-center > .be3-card[data-be3-card=\"field\"] > .be3-card-body {\n  display: block;\n}\n\n.be3-root[data-be3-size=\"tiny\"] .be3-col-center { flex: 1 1 auto; min-height: 0; }\n.be3-root[data-be3-size=\"tiny\"] .be3-col-right { flex: 0 0 45%; border-left: none; border-top: 1px solid var(--be3-border); }\n\n/* short：底部两条压紧 */\n.be3-root[data-be3-hsize=\"short\"] .be3-chatbar { padding: 4px 10px 6px; }\n.be3-root[data-be3-hsize=\"short\"] .be3-chat-input { min-height: 30px; max-height: 60px; }\n.be3-root[data-be3-hsize=\"short\"] .be3-usage { padding: 3px 10px; }\n\n/*\n * 四角抓手的 hover 提示**已合并到上面「四角缩放抓手」那一节**（第 112 窗口）。\n * 🔴 修前这里有第二份 `.be3-rs:hover { background: … }` ⇒ 与那节的 opacity 规则\n *   各说一半：hover 时既加背景又保留 28% 透明度，看起来像「糊了一块」。\n *   ⇒ 一份实现只留一处（与 `.be3-log` 那次重复定义同一条纪律）。\n */\n\n/* ============================================================================\n * 功能 C：世界书配置（书清单 + 条目勾选 + 搜索 + 分页）\n * ----------------------------------------------------------------------------\n * 设计：`_design/C-worldbook.md` §10。全部挂在左栏第 5 节里。\n * 🔴 颜色沿用面板既有变量（--be3-*），不引入新色板 —— 与其它卡视觉一致。\n * ==========================================================================*/\n.be3-wb { display: flex; flex-direction: column; gap: 6px; }\n.be3-wb-bad { color: #e0a95c; font-size: 11px; line-height: 1.5; }\n.be3-wb-books { display: flex; flex-direction: column; gap: 2px; }\n.be3-wb-book { display: flex; align-items: center; gap: 4px; padding: 2px 0; }\n.be3-wb-book.is-open { background: rgba(91, 141, 239, .10); border-radius: 3px; }\n.be3-wb-check {\n  background: none; border: none; color: #7d8797; cursor: pointer;\n  font-size: 13px; line-height: 1; padding: 1px 2px;\n}\n.be3-wb-check.is-on { color: #5b8def; }\n.be3-wb-bookname {\n  background: none; border: none; color: #cdd4e0; cursor: pointer;\n  font-size: 11px; padding: 1px 2px; text-align: left; max-width: 118px;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-wb-bookname:hover { color: #fff; text-decoration: underline; }\n.be3-wb-src { color: #7d8797; font-size: 10px; }\n.be3-wb-arrow { color: #7d8797; font-size: 10px; }\n.be3-wb-tools { display: flex; gap: 4px; align-items: center; }\n.be3-wb-search {\n  flex: 1; min-width: 0; background: #1b222c; border: 1px solid var(--be3-border);\n  border-radius: 3px; color: #cdd4e0; font-size: 11px; padding: 2px 5px;\n}\n.be3-wb-filters { display: flex; flex-wrap: wrap; gap: 3px; align-items: center; }\n.be3-wb-f {\n  background: #1b222c; border: 1px solid var(--be3-border); border-radius: 3px;\n  color: #9aa3b5; cursor: pointer; font-size: 10px; padding: 1px 5px;\n}\n.be3-wb-f.is-on { background: #2b3a52; border-color: #5b8def; color: #dfe6f2; }\n.be3-wb-list {\n  display: flex; flex-direction: column; gap: 1px;\n  max-height: 260px; overflow-y: auto;\n}\n.be3-wb-item { display: flex; align-items: center; gap: 3px; font-size: 11px; padding: 1px 0; }\n.be3-wb-item.is-off { opacity: .55; }\n.be3-wb-name {\n  flex: 1; min-width: 0; color: #cdd4e0;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-wb-item.is-on .be3-wb-name { color: #fff; }\n.be3-wb-lamp { font-size: 10px; border-radius: 2px; padding: 0 2px; }\n.be3-wb-lamp.is-blue { color: #5b8def; }\n.be3-wb-lamp.is-green { color: #4fbf7b; }\n.be3-wb-lamp.is-other { color: #7d8797; }\n.be3-wb-len { color: #7d8797; font-size: 10px; white-space: nowrap; }\n.be3-wb-tag {\n  font-size: 9px; border-radius: 2px; padding: 0 3px;\n  background: #2b3a52; color: #9aa3b5; white-space: nowrap;\n}\n.be3-wb-tag.is-bad { background: #4a2b2b; color: #e08a8a; }\n.be3-wb-tag.is-warn { background: #4a3f2b; color: #e0c08a; }\n.be3-wb-tag.is-ejs { background: #3a2b4a; color: #c09ae0; }\n.be3-wb-pager { display: flex; align-items: center; gap: 6px; justify-content: center; }\n\n\n/* ==========================================================================\n * ★ 第 69 窗口（E4 抓出）：画布上**玩家标记的删除按钮**\n *\n * 🔴 为什么必须有视觉提示：它在 SVG 里是一行 <text>，没有背景时\n *   会和标记标签混在一起，玩家根本看不出「这个 ✕ 是可以点的」。\n *   尺寸给到 11px 且加 hover 放大 —— 它是**唯一**能删标记的入口。\n * ========================================================================== */\n.be3-shape-del {\n  font-size: 11px;\n  fill: #ff8f8f;\n  cursor: pointer;\n  opacity: .75;\n  paint-order: stroke;\n  stroke: rgba(0, 0, 0, .55);\n  stroke-width: 2px;\n}\n.be3-shape-del:hover { opacity: 1; font-size: 14px; }\n\n\n/* ==========================================================================\n * ★ 第 69 窗口（F2 抓出）：左栏节头**可点**的视觉提示\n *\n * 🔴 修前 6 个节头是纯装饰（没有 action）⇒ 玩家看到 ▸ 会去点，点了没反应。\n *   现在它们真的能折叠，所以必须给出「可以点」的样子：手型光标 + hover 高亮。\n * ========================================================================== */\n.be3-side-head { cursor: pointer; user-select: none; }\n.be3-side-head:hover { background: rgba(255, 255, 255, .04); }\n.be3-side-section.is-folded .be3-side-head { opacity: .8; }\n\n\n/* ==========================================================================\n * ★ 第 69 窗口（F2）：左栏「技能系统」的**分段二选一按钮**\n *\n * 🔴 为什么单独写：线框图里那 3 组是「两个等宽按钮拼成一条」的形态，\n *   与现有的 .be3-btn（单个按钮）视觉层级不同 —— 玩家一眼要能看出\n *   「这两个是**互斥**的，只能选一个」。\n * ========================================================================== */\n.be3-seg { display: flex; gap: 0; margin: 2px 0 8px; }\n.be3-seg-btn {\n  flex: 1 1 0; padding: 5px 6px; font-size: 12px;\n  background: rgba(255, 255, 255, .04); color: var(--be3-dim, #9aa3b5);\n  border: 1px solid rgba(255, 255, 255, .12); cursor: pointer;\n  transition: background .12s, color .12s;\n}\n.be3-seg-btn:first-child { border-radius: 5px 0 0 5px; }\n.be3-seg-btn:last-child { border-radius: 0 5px 5px 0; border-left: none; }\n.be3-seg-btn:hover { background: rgba(255, 255, 255, .09); }\n.be3-seg-btn.is-on {\n  background: var(--be3-accent, #5b8def); color: #fff;\n  border-color: var(--be3-accent, #5b8def); font-weight: 600;\n}\n.be3-cfg-lab { font-size: 11px; color: var(--be3-dim, #9aa3b5); margin: 8px 0 2px; }\n\n/* ============================================================================\n * ★★ 第 70 窗口（功能 G）：目标状态栏三形态 + 穿脱装备\n * ----------------------------------------------------------------------------\n * 对照用户字符画（`_design/G0-字符画原图.md`）的**块顺序**，样式按本项目设计系统。\n * 🔴 三态色沿用现有变量：`--be3-ok`（满）/ `--be3-warn`（中）/ `--be3-danger`（危）。\n * 🔴 `.is-empty` 是**第四态**（读不到）—— 不填色。绝不把「不知道」画成「空血」。\n * ==========================================================================*/\n\n/* ---- 主角卡容器 ---- */\n.be3-sb { display: flex; flex-direction: column; gap: 8px; }\n.be3-sb-switch { display: flex; align-items: center; gap: 6px; }\n.be3-sb-divider { height: 1px; background: var(--be3-border); margin: 2px 0; }\n\n/* ---- 顶部：头像 + 四条资源线 + 身份 ---- */\n/* 🔴 三段并排，但**子项必须能收缩**（见下面各块的 min-width:0）。\n   不加 `flex-wrap`：换行会让版式跳到两行，与线框图不符。\n   收缩 + 省略号 比 换行 更接近原设计意图。 */\n/* ★★ 第 81 窗口：**顶上这块改成「头像 | 身份 / 数值」两列**（用户第 5 条后半句：\n *   「目标状态栏中，HP 828/82 / SAN --/ / CP 0/10 / 源力 7/ 右边半块视觉上\n *    都被【拉缇娜 / LV.52 · 异界魔王 · 灾厄 / 178520 / 798767】盖住了」）。\n *\n * 🔴 修前是**三列并排**：`头像 | 数值条 | 身份`（`.be3-sb-ident` 在最右）。\n *   而身份块里的名字是 15px、经验那行是 9px 等宽数字（`178520 / 798767` 有 15 个字符），\n *   它在窄栏里**撑出了自己的最小宽度**（`flex: 0 1 auto` + 名字不换行），\n *   ⇒ 反过来把中间的数值列压到只剩一半，四条数值的**右半边被身份块盖住**。\n *   🧪 判据当时全绿（三块都在 DOM、文字都对）—— 只有截图能看出「盖住」。\n *\n * ⇒ 正解：**身份块单独占一行**（在头像右侧的第一行），数值条在它下面**独占整行**。\n *   这样两条轴都不再抢宽度：名字再怎么长，也只压自己的行。\n * ⚠️ 仍用 `flex-wrap` 兜底：极窄时身份块会整体掉到下一行，而不是压扁数值。\n */\n.be3-sb-top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-start;\n  gap: 6px 8px;\n  min-width: 0;\n}\n/* 数值条：吃掉头像右侧的整行（`flex-basis` 给足，保证它一定换行到身份块下面） */\n.be3-sb-top > .be3-sb-vitals {\n  order: 3;\n  flex: 1 1 100%;\n  min-width: 0;\n}\n.be3-sb-vitals { display: flex; flex-direction: column; gap: 3px;\n  flex: 1 1 auto; min-width: 0; overflow: hidden; }\n.be3-sb-vital { display: flex; align-items: center; gap: 5px; font-size: 11px; }\n/* 🔴 标签列写死 30px 且不可缩 ⇒ 与上面的问题同一类。改 26px + 可缩。 */\n.be3-sb-vital-label {\n  flex: 0 1 26px; min-width: 22px; color: var(--be3-text-muted); font-size: 10px;\n  font-variant-numeric: tabular-nums; white-space: nowrap;\n}\n.be3-sb-bar-bg {\n  position: relative; flex: 1 1 auto; height: 8px; min-width: 40px;\n  background: var(--be3-border); border-radius: 3px; overflow: hidden;\n}\n.be3-sb-bar-bg.is-mini { flex: 0 0 52px; height: 6px; }\n.be3-sb-bar-fill {\n  position: absolute; left: 0; top: 0; bottom: 0;\n  background: linear-gradient(180deg, #7fd0a0, var(--be3-ok));\n  border-radius: 3px; transition: width .18s ease;\n}\n.be3-sb-bar-fill.is-mid { background: linear-gradient(180deg, #f0c070, var(--be3-warn)); }\n.be3-sb-bar-fill.is-low { background: linear-gradient(180deg, #f08080, var(--be3-danger)); }\n/* 🔴 第四态：读不到 ⇒ 不填色（不是空血条） */\n.be3-sb-bar-fill.is-empty { width: 0 !important; background: transparent; }\n.be3-sb-bar-fill.is-cp { background: linear-gradient(180deg, #8fb8ff, var(--be3-accent)); }\n.be3-sb-bar-fill.is-sp { background: linear-gradient(180deg, #b79cff, #7c5cf0); }\n.be3-sb-shield {\n  position: absolute; top: 0; bottom: 0; background: rgba(255, 255, 255, .38);\n  border-left: 1px solid rgba(255, 255, 255, .55);\n}\n/* 🔴 `flex: 0 0 auto` + `min-width: 76px` ⇒ 不可缩、必占 76px。\n   右栏 7:3 变窄后这一行放不下，就顶出去盖住身份块。\n   ⇒ 改成可收缩 + 省略号；完整数值始终在 `title` 里。 */\n.be3-sb-bar-text {\n  flex: 0 1 auto; min-width: 44px; text-align: right;\n  font-variant-numeric: tabular-nums; font-size: 11px;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-sb-bar-text > b { color: var(--be3-ok); font-size: 12px; }\n.be3-sb-bar-text > span { color: var(--be3-text-muted); font-size: 10px; }\n.be3-sb-temp { font-style: normal; color: var(--be3-accent); font-size: 10px; margin-left: 2px; }\n\n/* ---- 身份块 ---- */\n/* 🔴 `min-width` 96 → 0 + 允许收缩：修前它不可缩，与 vitals 抢宽导致文字重叠。\n   `flex: 0 1 auto` 让它能被压缩，`min-width: 0` 是 flex 收缩的前提\n   （默认 min-width:auto 会按内容撑开，那是重叠的直接原因）。 */\n.be3-sb-ident { display: flex; flex-direction: column; gap: 2px; align-items: flex-start;\n  min-width: 0; flex: 1 1 auto; text-align: left; }\n/* 🔴 人名可以换行，但**不许截断**（截图里「拉缇娜」被 828/828 盖住就是这个原因）。 */\n.be3-sb-ident-name { font-size: 15px; letter-spacing: .5px; line-height: 1.2;\n  overflow-wrap: break-word; word-break: break-word; max-width: 100%; }\n.be3-sb-sub { font-size: 10px; color: var(--be3-text-muted); }\n.be3-sb-exp-wrap { width: 100%; display: flex; flex-direction: column; gap: 2px; margin-top: 2px; }\n.be3-sb-exp-num { font-size: 9px; color: var(--be3-text-muted); text-align: center; font-variant-numeric: tabular-nums; }\n.be3-sb-exp { display: block; height: 4px; background: var(--be3-border); border-radius: 2px; overflow: hidden; }\n.be3-sb-exp > i { display: block; height: 100%; background: var(--be3-accent); }\n\n/* ---- 位置 / 周边 ---- */\n.be3-sb-around { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; font-size: 11px; }\n.be3-sb-around-text { color: var(--be3-text); }\n.be3-sb-around-chip {\n  padding: 1px 5px; border-radius: 3px; font-size: 10px;\n  border: 1px solid var(--be3-border); color: var(--be3-text-muted);\n}\n.be3-sb-around-chip.is-cover { border-color: var(--be3-ok); color: var(--be3-ok); }\n.be3-sb-around-chip.is-high { border-color: var(--be3-warn); color: var(--be3-warn); }\n.be3-sb-around-chip.is-low { border-color: var(--be3-accent); color: var(--be3-accent); }\n/* 🔴 面板推算的那一档必须与「AI 写的」视觉可分（虚线边框） */\n.be3-sb-around-chip.is-calc { border-style: dashed; }\n\n/* ★★★ 第 84 窗口：**坐标 chip / 高度 chip**（用户第 3 条「敌人信息内补充位置和高度」）\n *\n * 🔴 两者视觉上必须**能分开**，因为它们来源不同（这是本项目的老纪律）：\n *   · `is-pos`   坐标：AI 写的**一手事实** ⇒ 实线、等宽数字\n *   · `is-elevh` 高度：面板按 y **推算**的几何事实 ⇒ **虚线**（与 `is-calc` 同一条规矩）\n * ⚠️ 高度的三档配色与画布上的 ▲/▼ 角标**同一套**（琥珀=高、青蓝=低），\n *   否则玩家会以为「卡片上的高地」和「地图上的高地」是两回事。 */\n.be3-sb-around-chip.is-pos {\n  font-family: var(--be3-font-mono);\n  font-variant-numeric: tabular-nums;\n  border-color: rgba(255, 255, 255, .28);\n  color: var(--be3-text);\n  letter-spacing: .2px;\n}\n.be3-sb-around-chip.is-elevh { border-style: dashed; }\n.be3-sb-around-chip.is-elevh.is-high { border-color: #d9a441; color: #ffd79a; }\n.be3-sb-around-chip.is-elevh.is-low { border-color: #6fa8dc; color: #a8cdea; }\n.be3-sb-around-chip.is-elevh.is-flat { border-color: var(--be3-border); color: var(--be3-text-muted); }\n/* 高度未知：**不许**用自己的颜色（它既不是高也不是低）—— 用一个中性的问号色 */\n.be3-sb-around-chip.is-elevh.is-unknown {\n  border-color: var(--be3-border); border-style: dotted; color: var(--be3-text-dim, #6b7785);\n}\n\n/* ★★★ 第 84 窗口：**掩体模块**（用户：「后面再加个【是否有掩体…】的字段或相关描述，\n *   按你已经写的【位置】的样式来，只是再加一个描述模块」）\n *\n * 🔴 形态 = 「小标签 + 值」，与左栏「位置」那一列同款（`be3-sb-status-label` 的字号/颜色）。\n * 🔴 三态各有自己的颜色 —— 这是玩家要分辨的**三种不同事实**：\n *   · `is-has`    有掩体 ⇒ 绿色（有保护）\n *   · `is-none`   明确无 ⇒ **琥珀**（暴露，危险，要引起注意）\n *   · `is-unknown` 未标注 ⇒ **灰色虚框**（不知道 ≠ 没有）\n * ⚠️ 「未标注」绝不能画成「无」的琥珀色 —— 那会把「不知道」谎报成「暴露」。\n */\n.be3-sb-around-cover {\n  display: inline-flex; align-items: center; gap: 4px;\n  padding-left: 4px;\n  border-left: 1px solid var(--be3-border-strong, var(--be3-border));\n}\n.be3-sb-around-cover-k {\n  font-style: normal; font-size: 10px; color: var(--be3-text-muted);\n  white-space: nowrap;\n}\n.be3-sb-around-cover-v {\n  font-size: 10px; font-weight: 600; padding: 0 5px; border-radius: 3px;\n  border: 1px solid var(--be3-border); white-space: nowrap;\n}\n.be3-sb-around-cover-v.is-has { border-color: var(--be3-ok); color: var(--be3-ok); }\n.be3-sb-around-cover-v.is-none { border-color: var(--be3-warn); color: var(--be3-warn); }\n.be3-sb-around-cover-v.is-unknown {\n  border-style: dotted; border-color: var(--be3-border); color: var(--be3-text-dim, #6b7785);\n}\n.be3-sb-around-note { font-size: 9px; color: var(--be3-text-muted); font-style: italic; }\n\n/* ---- 状态 chip ---- */\n.be3-sb-status { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; font-size: 11px; }\n.be3-sb-status-label {\n  flex: 0 0 auto; color: var(--be3-text-muted); font-size: 10px; min-width: 52px;\n}\n.be3-sb-status-chip {\n  display: inline-flex; align-items: center; gap: 2px;\n  padding: 1px 5px; border-radius: 3px; font-size: 10px;\n  border: 1px solid var(--be3-border); background: rgba(255, 255, 255, .03);\n}\n.be3-sb-status-chip > b { font-weight: 600; }\n.be3-sb-status-chip > i { font-style: normal; color: var(--be3-text-muted); font-size: 9px; }\n.be3-sb-status-chip.is-battle { border-color: var(--be3-warn); }\n.be3-sb-status-chip.is-ending { border-color: var(--be3-danger); color: var(--be3-danger); }\n\n/* ---- 三张大卡（攻 / 物理减 / 魔法减） ---- */\n.be3-sb-cards { display: flex; gap: 6px; }\n.be3-sb-card {\n  flex: 1 1 0; display: flex; flex-direction: column; align-items: center; gap: 1px;\n  padding: 5px 4px; border-radius: 5px; border: 1px solid var(--be3-border);\n  background: rgba(255, 255, 255, .02);\n}\n.be3-sb-card.is-atk { border-color: var(--be3-accent); }\n.be3-sb-card.is-phys { border-color: var(--be3-ok); }\n.be3-sb-card.is-mag { border-color: #b79cff; }\n.be3-sb-card-label { font-size: 9px; color: var(--be3-text-muted); }\n.be3-sb-card-value { font-size: 15px; font-variant-numeric: tabular-nums; }\n.be3-sb-card-value > small { font-size: 9px; color: var(--be3-text-muted); margin-left: 1px; }\n.be3-sb-card-sub { font-size: 9px; color: var(--be3-text-muted); font-variant-numeric: tabular-nums; }\n\n/* ---- 三张小卡（攻击次数 / 暴击伤害 / 暴击阈值+率） ---- */\n.be3-sb-crits { display: flex; gap: 6px; }\n.be3-sb-crit {\n  flex: 1 1 0; display: flex; flex-direction: column; align-items: center;\n  padding: 4px; border-radius: 5px; border: 1px solid var(--be3-border);\n}\n.be3-sb-crit-value { font-size: 14px; font-variant-numeric: tabular-nums; }\n.be3-sb-crit-value > small { font-size: 9px; color: var(--be3-text-muted); }\n.be3-sb-crit-value > em { font-style: normal; font-size: 10px; color: var(--be3-accent); margin-left: 1px; }\n.be3-sb-crit-label { font-size: 9px; color: var(--be3-text-muted); }\n\n/* ---- 六维（六格，中文+缩写，值下面加成） ---- */\n.be3-sb-attrs { display: flex; gap: 4px; }\n.be3-sb-attr {\n  flex: 1 1 0; display: flex; flex-direction: column; align-items: center;\n  padding: 3px 2px; border-radius: 4px; border: 1px solid var(--be3-border);\n}\n.be3-sb-attr-name { font-size: 9px; color: var(--be3-text-muted); }\n.be3-sb-attr-name > i { font-style: normal; font-size: 8px; opacity: .7; margin-left: 2px; }\n.be3-sb-attr-val { font-size: 12px; font-variant-numeric: tabular-nums; }\n.be3-sb-attr-val > small { font-size: 9px; margin-left: 1px; }\n.be3-sb-attr-val > small.is-plus { color: var(--be3-ok); }\n.be3-sb-attr-val > small.is-minus { color: var(--be3-danger); }\n\n/* ---- 特质 ---- */\n.be3-sb-traits { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; font-size: 11px; }\n.be3-sb-traits-label { color: var(--be3-text-muted); font-size: 10px; }\n.be3-sb-trait {\n  padding: 1px 5px; border-radius: 3px; font-size: 10px;\n  border: 1px solid var(--be3-border); color: var(--be3-text);\n}\n\n/* ---- 兜底警告 ---- */\n.be3-sb-warn { font-size: 9px; color: var(--be3-warn); }\n\n/* ---- 队友卡（窄行版） ---- */\n.be3-sb-companion { display: flex; flex-direction: column; gap: 5px; }\n.be3-sb-comp-head { display: flex; align-items: center; gap: 8px; }\n.be3-sb-comp-id { display: flex; flex-direction: column; gap: 1px; flex: 1 1 auto; }\n.be3-sb-tag {\n  padding: 0 5px; border-radius: 3px; font-size: 9px;\n  border: 1px solid var(--be3-border); color: var(--be3-text-muted);\n}\n.be3-sb-tag.is-role { border-color: var(--be3-accent); color: var(--be3-accent); }\n.be3-sb-comp-vitals { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-comp-num { font-variant-numeric: tabular-nums; color: var(--be3-text-muted); }\n.be3-sb-comp-attrs { display: flex; gap: 8px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-mini-attr { display: inline-flex; align-items: baseline; gap: 2px; }\n.be3-sb-mini-attr > i { font-style: normal; color: var(--be3-text-muted); font-size: 9px; }\n.be3-sb-mini-attr > b { font-variant-numeric: tabular-nums; }\n.be3-sb-comp-combat { display: flex; gap: 3px; flex-wrap: wrap; }\n.be3-sb-mini-combat {\n  display: inline-flex; align-items: baseline; gap: 2px;\n  padding: 1px 4px; border-radius: 3px; font-size: 9px;\n  border: 1px solid var(--be3-border);\n}\n.be3-sb-mini-combat > i { font-style: normal; color: var(--be3-text-muted); }\n.be3-sb-mini-combat > b { font-variant-numeric: tabular-nums; }\n.be3-sb-comp-line { display: flex; align-items: baseline; gap: 5px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-comp-line > i { font-style: normal; color: var(--be3-text-muted); font-size: 9px; min-width: 26px; }\n.be3-sb-mini-eq, .be3-sb-mini-skill {\n  padding: 1px 4px; border-radius: 3px; border: 1px solid var(--be3-border); font-size: 9px;\n}\n.be3-sb-mini-eq { border-color: var(--be3-ok); }\n.be3-sb-mini-skill { border-color: var(--be3-accent); }\n\n/* ---- 敌人卡 ---- */\n.be3-sb-enemy { display: flex; flex-direction: column; gap: 5px; }\n.be3-sb-enemy-head { display: flex; align-items: flex-start; gap: 8px; }\n.be3-sb-enemy-id { display: flex; flex-direction: column; gap: 2px; flex: 1 1 auto; }\n.be3-sb-enemy-name { font-size: 13px; }\n.be3-sb-enemy-lv { font-size: 10px; color: var(--be3-warn); margin-right: 3px; }\n.be3-sb-enemy-tags { display: flex; gap: 3px; flex-wrap: wrap; }\n.be3-sb-enemy-quick {\n  display: flex; flex-direction: column; align-items: flex-end; gap: 1px;\n  font-size: 10px; color: var(--be3-text-muted); font-variant-numeric: tabular-nums;\n}\n.be3-sb-enemy-vitals { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-enemy-attrs { display: flex; gap: 8px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-enemy-line { display: flex; align-items: baseline; gap: 5px; flex-wrap: wrap; font-size: 10px; }\n.be3-sb-enemy-line > i { font-style: normal; color: var(--be3-text-muted); font-size: 9px; min-width: 42px; }\n.be3-sb-enemy-chip {\n  padding: 1px 4px; border-radius: 3px; font-size: 9px;\n  border: 1px solid var(--be3-border);\n}\n.be3-sb-enemy-chip > em { font-style: normal; color: var(--be3-accent); margin-left: 2px; }\n.be3-sb-enemy-chip.is-skill { border-color: var(--be3-accent); }\n.be3-sb-enemy-chip.is-weak { border-color: var(--be3-danger); color: var(--be3-danger); }\n.be3-sb-enemy-chip.is-resist { border-color: var(--be3-ok); color: var(--be3-ok); }\n\n/* ---- 装备穿脱页 ---- */\n.be3-sb-slots { display: flex; flex-direction: column; gap: 3px; }\n.be3-sb-slot {\n  display: flex; align-items: center; gap: 6px;\n  padding: 3px 5px; border-radius: 4px; border: 1px solid var(--be3-border); font-size: 10px;\n}\n.be3-sb-slot.is-empty { border-style: dashed; opacity: .7; }\n.be3-sb-slot-label { flex: 0 0 44px; color: var(--be3-text-muted); font-size: 9px; }\n.be3-sb-slot-name { flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.be3-sb-slot-btn {\n  flex: 0 0 auto; padding: 1px 6px; border-radius: 3px; cursor: pointer;\n  border: 1px solid var(--be3-border); background: transparent;\n  color: var(--be3-text); font-size: 9px;\n}\n.be3-sb-slot-btn:hover { border-color: var(--be3-accent); color: var(--be3-accent); }\n.be3-sb-slot-btn.is-equip { border-color: var(--be3-ok); color: var(--be3-ok); }\n.be3-sb-boxhead { font-size: 10px; color: var(--be3-text-muted); margin-top: 4px; }\n.be3-sb-boxlist { display: flex; flex-direction: column; gap: 3px; max-height: 180px; overflow-y: auto; }\n.be3-sb-boxitem {\n  display: flex; align-items: center; gap: 6px;\n  padding: 3px 5px; border-radius: 4px; border: 1px solid var(--be3-border); font-size: 10px;\n}\n/* 🔴 这条 note 的文字**必须**在一个 <span> 里 —— 见 status-card.js 的注释\n   （Stage_1 踩过 flex 把文字拆成 3 列的 bug，所有自动检查都正常、只有肉眼看得见） */\n.be3-sb-note {\n  display: flex; align-items: flex-start; gap: 5px;\n  padding: 4px 6px; border-radius: 4px; font-size: 9px;\n  color: var(--be3-text-muted); background: rgba(255, 255, 255, .03);\n  border-left: 2px solid var(--be3-accent);\n}\n.be3-sb-note > span { line-height: 1.5; }\n.be3-sb-note > span > b { color: var(--be3-warn); }\n\n/* ============================================================================\n * 🔴🔴 三栏宽度：中栏 : 右栏 = **7 : 3**（第 72 窗口，用户要求）\n *\n * 这条**必须放在文件最后**：前面 `.be3-col-center { flex: 1 1 auto }`（tiny 档遗留）\n * 与它特异性相同，靠「后者胜」把 7:3 悄悄覆盖成了 1:1 ——\n * 而那种覆盖**不报错**，只看代码根本发现不了（实测比例 1.1:1）。\n * ⇒ 现在把 tiny 档那条加上了 `[data-be3-size=\"tiny\"]` 前缀（作用域收窄），\n *    并在这里用同样的特异性 + 更靠后的位置兜底。\n * ⚠️ 以后再加栏宽规则，**只改这一处**，不要在别处写 `.be3-col-center { flex: ... }`。\n * ==========================================================================*/\n.be3-root .be3-body > .be3-col-center {\n  flex: 7 1 0 !important;\n  min-width: 0;\n  min-height: 0;\n  overflow-y: auto;\n  gap: 7px;\n  padding: 7px;\n}\n.be3-root .be3-body > .be3-col-right {\n  flex: 3 1 0 !important;\n  /* 🔴 `min-width` 必须够小（260）：它只是「极窄面板下的可读保底」，\n     写 320 会把实际宽度顶得远超 flex 分配值 ⇒ 7:3 失效（实测 0.76:1）。 */\n  /* 🔴 极窄面板下的可读保底（不影响正常比例：flex-basis 0 时 min-width 只在\n     分配结果低于它时才生效）。实测 2.19:1 vs 目标 2.33:1，差值来自 padding。 */\n  min-width: 240px;\n  padding: 7px;\n  gap: 7px;\n  border-left: 1px solid var(--be3-border);\n  background: #171c22;\n  overflow-y: auto;\n}\n/* 🔴 右栏**内部的卡片也必须能收缩**：否则卡里的长标题\n   （「同伴 / 附近的人 (参考)」等）会把整栏撑宽，7:3 就永远不成立。 */\n.be3-root .be3-body > .be3-col-right > .be3-card {\n  min-width: 0;\n}\n/* tiny 档仍是上下堆叠（覆盖上面的 7:3） */\n.be3-root[data-be3-size=\"tiny\"] .be3-body > .be3-col-right {\n  flex: 0 0 45% !important; border-left: none; border-top: 1px solid var(--be3-border);\n}\n\n/* ============================================================================\n * ★★ 第 86 窗口：**大屏配置页**（API / 预设配置 / 世界书配置）\n * ----------------------------------------------------------------------------\n * 用户原话：「【API配置】【预设配置（提示词(契约预览)）】【世界书配置】不再展开\n *   设置栏内长条，改为展开占【当前目标】+【目标状态栏】宽度，\n *   【chatBox】+【回合状态栏】以上的大屏配置页面。正文居中，方便玩家观察。」\n *\n * 🔴 版式怎么来的（*不是* 我拍的高度）：\n *   · 宽度 = 中栏 + 右栏 ⇒ 它就是一个绝对定位块，`left: 左栏宽度`、`right: 0`\n *     （左栏还要显示【技能系统】【后台数据】两条长条，不能让配置页盖住它）\n *   · 高度 = 【回合状态栏】+【发言栏】**以上** ⇒ 贴满 `.be3-body`\n *     （`.be3-body` 本来就是「顶栏以下、两条页脚以上」的弹性区）\n *   ⚠️ 所以这里**一处都不写固定高度**：写了就会和页脚的两个档位（normal/short）\n *      互相漂移，而漂移的症状是「底部的发言栏被盖住一截」。\n *\n * 🔴 为什么用 `position: absolute` 覆盖而不是「不渲染中右栏」：\n *   不渲染 ⇒ `scroll-keep` 收不到 `mid`/`right` 的滚动位置 ⇒ 关掉配置页会跳回顶部\n *   （第 68 窗口的老 bug 会原样回来）。三栏照常渲染、配置页浮在上面，行为可预测。\n * ⚠️ 中栏/右栏**保持可见但不能点**（`pointer-events: none`）：\n *   它们被完全遮住了，留着可点只会让玩家误触到看不见的按钮。\n * ==========================================================================*/\n.be3-body { position: relative; }\n.be3-root .be3-body.is-cfg-open > .be3-col-center,\n.be3-root .be3-body.is-cfg-open > .be3-col-right { pointer-events: none; }\n\n.be3-cfg-wrap {\n  position: absolute;\n  top: 0; right: 0; bottom: 0;\n  /* 左栏宽度（258px）由下面这条跟着 .be3-col-left 一起变：\n     窄档 210px 时配置页也要跟着让位，否则两者会重叠 48px。 */\n  left: 258px;\n  z-index: 30;\n  display: flex;\n  padding: 7px;\n  background: rgba(10, 12, 16, .72);\n  box-sizing: border-box;\n}\n.be3-root[data-be3-size=\"narrow\"] .be3-cfg-wrap { left: 210px; }\n/* 左栏隐藏时（⚙ 被收起）配置页吃满整行 —— 否则右边会留一条空的黑边 */\n.be3-root .be3-body > .be3-col-left[hidden] ~ .be3-cfg-wrap { left: 0; }\n/* tiny 档左栏变成横条在顶上 ⇒ 配置页回到整行 */\n.be3-root[data-be3-size=\"tiny\"] .be3-cfg-wrap { left: 0; }\n\n.be3-cfg-page {\n  flex: 1 1 auto;\n  min-width: 0; min-height: 0;\n  display: flex; flex-direction: column;\n  background: var(--be3-surface);\n  border: 1px solid var(--be3-border-strong);\n  border-radius: var(--be3-r-md);\n  box-shadow: var(--be3-shadow);\n  overflow: hidden;\n}\n\n/* ---- 页头 ---- */\n.be3-cfg-phead {\n  display: flex; align-items: baseline; gap: 10px;\n  padding: 9px 12px;\n  background: linear-gradient(180deg, #232b34, #1a2028);\n  border-bottom: 1px solid var(--be3-border);\n  flex: 0 0 auto;\n}\n.be3-cfg-ptitle { font-size: 13.5px; font-weight: 700; }\n.be3-cfg-psub { font-size: 11.5px; color: var(--be3-text-muted); }\n\n/* ---- 正文：**居中**（用户要求「方便玩家观察」） ---- */\n.be3-cfg-pbody {\n  flex: 1 1 auto; min-height: 0;\n  overflow-y: auto;\n  padding: 10px 12px 14px;\n  display: flex; flex-direction: column; gap: 8px;\n  /* 🔴 这一行就是「正文居中」：内容区限宽 + 自动左右外边距。\n     不限宽的话，1180px 宽的面板上一行字会横跨 900px，玩家眼睛要来回扫。 */\n  max-width: 1180px;\n  width: 100%;\n  margin: 0 auto;\n  box-sizing: border-box;\n}\n/* 两栏（预设：条目 | 契约预览；世界书：本体条目 | EJS） */\n.be3-cfg-two { display: flex; flex-direction: row; gap: 12px; align-items: stretch; }\n.be3-cfg-col { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 6px; }\n.be3-cfg-two > .be3-cfg-col:first-child { flex: 0 0 46%; }\n/* 🔴🔴 真机截图抓到的**布局真 bug**（不是观感）：\n   `.be3-cfg-pbody` 是 `overflow-y:auto` 的**滚动容器**，而 `.be3-cfg-list` 自己又带\n   `max-height:46vh; overflow-y:auto`。两层滚动叠在一起时，内层（条目列表）在\n   flex-column 里被压成 **0 高** ⇒ 玩家看到「提示词条目（19）」下面**一片空白**，\n   而条目其实都在。（我一开始误判成「段容器被 shrink」，加 `flex:none` 没用 ——\n   真正的原因是**内层还以为自己有 46vh**，而外层根本没给到那么高。）\n   ⇒ 配置页里的列表**不再自己滚**：让 `.be3-cfg-pbody` 那一个滚动条负责全部。\n   ⚠️ 世界书册（`.be3-cfg-wblist.is-register`）同理，已单独放开。 */\n.be3-cfg-two .be3-cfg-list { max-height: none; overflow-y: visible; }\n\n.be3-cfg-chead {\n  display: flex; align-items: center; gap: 6px;\n  font-size: 12px; font-weight: 600; color: var(--be3-text);\n  border-bottom: 1px solid var(--be3-border); padding-bottom: 4px;\n}\n\n/* ---- 通用小件 ---- */\n.be3-cfg-hint { font-size: 11px; color: var(--be3-text-muted); line-height: 1.6; }\n.be3-cfg-bad {\n  font-size: 11.5px; color: var(--be3-danger); line-height: 1.6;\n  border: 1px solid var(--be3-danger); border-radius: 4px; padding: 4px 6px;\n}\n.be3-cfg-ok { font-size: 11.5px; color: var(--be3-ok); line-height: 1.6; }\n.be3-cfg-tag {\n  font-size: 9.5px; padding: 0 5px; border-radius: 8px; white-space: nowrap;\n  color: var(--be3-accent); border: 1px solid var(--be3-accent);\n}\n.be3-cfg-tag.is-warn { color: var(--be3-warn); border-color: var(--be3-warn); }\n.be3-cfg-src { font-size: 10px; color: var(--be3-text-muted); white-space: nowrap; }\n.be3-cfg-tools { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-cfg-facts { display: flex; flex-wrap: wrap; gap: 4px 14px; }\n.be3-cfg-fact { font-size: 11.5px; color: var(--be3-text-muted); }\n.be3-cfg-fact > b { color: var(--be3-text); font-weight: 600; margin-left: 5px; }\n\n/* 勾选框 / 单选点（两处都要能一眼看出「点得动」） */\n.be3-cfg-chk, .be3-cfg-radio {\n  background: none; border: none; cursor: pointer; padding: 0 2px;\n  font-size: 13px; line-height: 1.2; color: var(--be3-text-muted);\n}\n.be3-cfg-chk.is-on { color: var(--be3-accent); }\n.be3-cfg-radio.is-on { color: var(--be3-ok); }\n\n/* 输入框 / 下拉 / 多行框（大屏页里给足尺寸 —— 这是它们存在的理由） */\n.be3-cfg-input, .be3-cfg-select, .be3-cfg-textarea {\n  background: var(--be3-bg); color: var(--be3-text);\n  border: 1px solid var(--be3-border); border-radius: 4px;\n  font-size: 12px; font-family: inherit; padding: 4px 6px;\n  box-sizing: border-box; min-width: 0;\n}\n.be3-cfg-input:focus, .be3-cfg-select:focus, .be3-cfg-textarea:focus {\n  outline: none; border-color: var(--be3-accent);\n}\n.be3-cfg-input.is-search { flex: 1 1 auto; }\n.be3-cfg-select.is-picker { width: auto; max-width: 240px; }\n.be3-cfg-textarea {\n  width: 100%; min-height: 120px; resize: vertical; line-height: 1.55;\n  font: 12px/1.55 ui-monospace, Consolas, monospace;\n}\n.be3-cfg-textarea.is-io { min-height: 96px; }\n\n/* ---- API 页 ---- */\n.be3-cfg-apilist { display: flex; flex-direction: column; gap: 8px; }\n.be3-cfg-api {\n  border: 1px solid var(--be3-border); border-radius: 6px;\n  padding: 7px 9px; background: rgba(255, 255, 255, .02);\n}\n.be3-cfg-api.is-active-api { border-color: var(--be3-accent); }\n.be3-cfg-api.is-off { opacity: .62; }\n.be3-cfg-apihead { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }\n.be3-cfg-apiname { font-size: 12px; font-weight: 600; }\n.be3-cfg-apigrid {\n  display: grid; grid-template-columns: 46px minmax(0, 1fr);\n  gap: 4px 8px; align-items: center;\n}\n.be3-cfg-apigrid .be3-cfg-input { width: 100%; }\n/* ★ 第 106 窗口：模型行 = 输入框（可下拉候选）+【查模型】按钮 + 状态行。\n   🔴 单独给**模型这一行**开一条 2 列子网格，**不动上面那条两列总网格** ——\n      动了它，地址 / 密钥两行的对齐会一起变（那是更贵的回归）。\n   ⚠️ 状态行（loading/ok/err）横跨整行，不挤在窄列里。 */\n.be3-cfg-modelrow {\n  display: grid; grid-template-columns: minmax(0, 1fr) auto;\n  gap: 4px 6px; align-items: center;\n}\n.be3-cfg-modelrow .be3-cfg-input { width: 100%; min-width: 0; }\n.be3-cfg-modelrow .be3-cfg-modelq { white-space: nowrap; }\n/* ★ 第 107 窗口：「带多少历史」这一行是输入框 + 应用按钮 + 当前值 */\n.be3-cfg-histrow { display: inline-flex; align-items: center; gap: 6px; }\n.be3-cfg-histrow .be3-cfg-input { min-width: 0; }\n\n.be3-cfg-modelrow .be3-cfg-hint,\n.be3-cfg-modelrow .be3-cfg-bad { grid-column: 1 / -1; margin: 0; }\n\n/* ---- 预设页 ---- */\n/* 🔴 列表**不再自己限高**（第 87 窗口）。\n   真机截图抓到的**布局真 bug**：`.be3-cfg-list` 带 `max-height:46vh; overflow-y:auto`，\n   而它的父级（配置页正文）本身也是滚动容器 ⇒ 条目列表在 flex 列里被压成 **0 高**，\n   玩家看到「提示词条目（19）」下面一片空白，而 19 条其实都在 DOM 里（判据全绿）。\n   ⇒ 只留**外层**一个滚动条。\n   ⚠️ 这条与 `.be3-cfg-two .be3-cfg-list` 那条是同一件事的两半，**别只改一半**。 */\n.be3-cfg-list {\n  display: flex; flex-direction: column; gap: 4px;\n  max-height: none; overflow-y: visible; padding-right: 2px;\n}\n.be3-cfg-item {\n  border: 1px solid var(--be3-border); border-radius: 6px;\n  background: rgba(255, 255, 255, .02);\n}\n.be3-cfg-item.is-open { border-color: var(--be3-accent); }\n.be3-cfg-item.is-off { opacity: .6; }\n/* 🔴 第 87 窗口：条目行里的名字要给**足够权重**。\n   修前 `flex:1 1 auto` 让名字在「标签 + role + 来源 + 4 个小按钮」挤过来时\n   被压成「【战斗扩展】…」—— 玩家分不清是哪一条。⇒ 给一个下限，其余元素让位。 */\n.be3-cfg-itemhead > .be3-cfg-itemname { min-width: 7em; flex: 2 1 auto; }\n.be3-cfg-itemhead > .be3-cfg-src,\n.be3-cfg-itemhead > .be3-cfg-tag { flex: none; }\n.be3-cfg-itemhead { display: flex; align-items: center; gap: 5px; padding: 4px 6px; }\n.be3-cfg-itemname {\n  background: none; border: none; cursor: pointer; text-align: left;\n  color: var(--be3-text); font-size: 12px; padding: 1px 2px;\n  flex: 1 1 auto; min-width: 0;\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n}\n.be3-cfg-itemname:hover { color: #fff; text-decoration: underline; }\n.be3-cfg-itembody {\n  border-top: 1px dashed var(--be3-border);\n  padding: 6px 8px 8px; display: flex; flex-direction: column; gap: 6px;\n}\n.be3-cfg-itemrow { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.be3-cfg-itemrow .be3-cfg-input { flex: 1 1 160px; }\n.be3-cfg-lab { font-size: 10.5px; color: var(--be3-text-muted); }\n.be3-cfg-pre {\n  margin: 0; padding: 7px 8px; border-radius: 5px;\n  background: var(--be3-bg); border: 1px solid var(--be3-border);\n  font: 11px/1.6 ui-monospace, Consolas, monospace;\n  white-space: pre-wrap; word-break: break-word;\n  overflow: auto;\n}\n.be3-cfg-pre.is-tall { max-height: 60vh; }\n\n/* ---- 预设页的分段（★ 第 87 窗口：战斗扩展 / 玩家副本） ---- */\n/* 🔴 真机截图抓到的观感 bug：左栏「提示词条目（19）」下面**一片空白** ——\n   根因不是数据（条目真的在），而是分段容器没有自己的盒子：\n   `.be3-cfg-list` 是 `flex-direction: column` + `max-height:46vh`，\n   而每段 `.be3-cfg-seg` 的高度由内容撑开；一旦某段的子项全是 `is-off`（opacity 不影响布局），\n   段与段之间会**互相挤成 0 高**（flex 默认 `flex-shrink:1`）。\n   ⇒ 给段 `flex: none`（不许被压），给段内一个可见的分区标题条。 */\n.be3-cfg-seg { display: flex; flex-direction: column; gap: 3px; flex: none; }\n.be3-cfg-seglab {\n  position: sticky; top: 0; z-index: 1;\n  font-size: 11px; color: var(--be3-text-muted);\n  background: var(--be3-surface-2);\n  border-left: 3px solid var(--be3-border-strong);\n  padding: 2px 6px; margin: 4px 0 2px; border-radius: 3px;\n}\n.be3-cfg-seg.is-battle > .be3-cfg-seglab { border-left-color: var(--be3-accent); color: #cfdcf5; }\n.be3-cfg-seg.is-player > .be3-cfg-seglab { border-left-color: var(--be3-ok); color: #cfe9d8