    return engineCtl;
  }

  const histLimit = () => (caps ? caps.chatHistoryLimit(0) : 0);

  function sendChatDraft() {
    const raw = String(ui.runner && ui.runner.getChatDraft ? ui.runner.getChatDraft() : '');
    if (!raw.trim()) { note('发言栏是空的 —— 先写点什么'); return { ok: false, reason: 'empty' }; }
    const eng = engine();
    if (!eng) {
      note('⚠️ 发送引擎没装配起来（`send/engine.js` 缺失）⇒ 草稿已保留，未发送');
      return { ok: false, reason: 'no_engine' };
    }
    const p = eng.send(raw, { source: 'chatbar' });

    p.then((r) => {

      if (r && r.ok && r.kind === 'ok' && ui.runner && ui.runner.setChatDraft) {
        ui.runner.setChatDraft('');
      }
      paint();
    }).catch((e) => {
      safeNote(`⚠️ 发送流程异常：${e && e.message ? e.message : e}`);
      paint();
    });
    return { ok: true, reason: 'pending' };
  }

  function settleBattle(opts) {
    const ctl = settleCtl || settleEngine();
    if (!ctl) return { ok: false, reason: 'no_settle', written: 0 };
    return (opts && opts.preview === true) ? ctl.preview() : ctl.settle();
  }

  let settleCtl = null;
  function settleEngine() {
    if (settleCtl) return settleCtl;
    const M = get('__BE3_SETTLE__');
    if (!M || !M.createSettle) return null;
    settleCtl = M.createSettle({
      getRunner: () => ui.runner,
      getEngine: () => engine(),
      note: (t) => note(t),
      paint: () => paint(),
    });
    return settleCtl;
  }

  function promptPreviewText() {
    const M = get('__BE3_PROMPT__');
    if (!M || !M.previewFor) return '';
    const pk = cfgPresetPack();
    return M.previewFor(ui.runner, histLimit(), {
      worldbookText: wb ? wb.getCachedText() : '',

      presetItems: pk.items,

      playerPresetItems: pk.playerPreset,
      vars: pk.vars,
    });
  }

  const cfg = caps && typeof caps.cfgModule === 'function'
    ? caps.cfgModule({ previewText: () => promptPreviewText() })
    : null;

  const cfgPresetItems = () => (cfg && typeof cfg.forSend === 'function' ? cfg.forSend() : null);

  const cfgPresetPack = () => (cfg && typeof cfg.forSendPack === 'function'
    ? cfg.forSendPack()
    : { items: cfgPresetItems(), playerPreset: null, vars: null, missingVars: [], dropped: [] });

  function scrollDo(op, saved) {
    const K = get('__BE3_SCROLLKEEP__');
    if (!K) return op === 'capture' ? {} : undefined;
    if (op === 'capture') return K.capture ? K.capture(ui.panel) : {};
    if (K.restore) K.restore(ui.panel, saved);
    return undefined;
  }

  function paint() {

    if (!ui.panel) return;
    if (!ui.runner) { paintFallbackBox(ui.panel, '内核没装配起来（runner 为空）'); return; }
    const R = get('__BE3_RENDER__');
    if (!R || typeof R.renderPanel !== 'function') {
      paintFallbackBox(ui.panel, '渲染模块 __BE3_RENDER__.renderPanel 不存在');
      return;
    }
    try {
      const VM = get('__BE3_VIEWMODEL__');
      const view = VM && VM.buildView ? VM.buildView(ui.runner, get('__BE3_GEOMETRY__'), {
        genState: (() => { const e = engine(); return e && e.getState ? e.getState() : 'idle'; })(),
        config: {

          model: '',
          maxChatHistory: histLimit(),
          hasGenerate: !!hostApi('generate'),

          hasGenerateRaw: !!hostApi('generateRaw'),

          promptPreview: promptPreviewText(),

          api: caps ? caps.apiSnapshot() : {},

          wb: wb ? wb.viewForRender() : { books: [], entries: null, namesApiOk: false, map: {} },

          preset: cfg.viewForRender(),
        },

        getItem: (key) => localGetItem(key),
      }) : {};
      const scroll = scrollDo('capture');

      IH.around(ui.panel, () => { ui.panel.innerHTML = R.renderPanel(ui.runner.snapshot(), view); });
      scrollDo('restore', scroll);

      FW.attach(ui.panel);
      if (canvasFit) canvasFit.fit();
    } catch (e) {
      const msg = `渲染抛错：${e && e.message ? e.message : e}`;
      if (typeof console !== 'undefined') console.error('[BE3] ' + msg, e);
      paintFallbackBox(ui.panel, msg);
    }
  }

  const act = (() => {
    const M = get('__BE3_ACTIONS__');
    if (!M || !M.createActions) return null;
    return M.createActions({
      getRunner: () => ui.runner,
      note: (t) => note(t),
      paint: () => paint(),
      unmount: () => unmount(),
      readMvu: () => readMvuStatData(),
      confirm: (t) => {
        const w = hostWin();
        if (!w || typeof w.confirm !== 'function') return null;
        try { return w.confirm(t); } catch (e) { return null; }
      },
      sendChat: () => sendChatDraft(),

      getEngine: () => engine(),

      settleBattle: () => settleBattle(),

      settlePreview: () => settleBattle({ preview: true }),

      promptPreview: () => promptPreviewText(),

      appendSkillMark: (name, at) => (inputHooks && inputHooks.appendSkillMark ? inputHooks.appendSkillMark(name, at) : ''),

      getBagSelection: () => (ui.runner && ui.runner.getBagSelection ? ui.runner.getBagSelection() : []),
      clearBagSelection: () => (ui.runner && ui.runner.clearBagSelection ? ui.runner.clearBagSelection() : []),

      apiConfig: (mutator) => apiConfig(mutator),

      apiSetField: (i, field, value) => apiConfig((raw) => A().setApiField(raw, i, field, value)),

      apiModels: (i) => (caps && typeof caps.apiModels === 'function'
        ? caps.apiModels(i) : Promise.resolve({ ok: false, models: [], reason: '宿主能力没装配起来' })),

      setChatHistoryLimit: (n) => (caps ? caps.setChatHistoryLimit(n) : 0),

      wb,

      cfg,
    });
  })();

  const ACTIONS = (act && act.ACTIONS) || {};
  const PARAM_ACTIONS = (act && act.PARAM_ACTIONS) || {};

  let boundWbView = false;
  const explainFailure = (n, r) => (act ? act.explainFailure(n, r) : null);

  function wireWbView() {
    if (!wb || boundWbView || !ui.runner || typeof ui.runner.bindWbView !== 'function') return;
    boundWbView = ui.runner.bindWbView((p) => wb.setView(p));
  }

  function onPanelClick(ev) {
    wireWbView();
    const t = ev.target && ev.target.closest ? ev.target.closest('[data-be3-action]') : null;
    if (!t) return;
    const name = t.getAttribute('data-be3-action');
    ev.preventDefault();
    ev.stopPropagation();

    const pf = PARAM_ACTIONS[name];
    if (pf) {
      try {
        explainFailure(name, pf(t));
      } catch (e) {
        if (typeof console !== 'undefined') console.error('[BE3] 动作失败', name, e);
        return;
      }
      paint();
      return;
    }

    const fn = ACTIONS[name];
    if (!fn) {

      if (typeof console !== 'undefined') console.warn('[BE3] 未实现的动作：', name);
      return;
    }
    try { fn(); } catch (e) {
      if (typeof console !== 'undefined') console.error('[BE3] 动作失败', name, e);
      return;
    }
    paint();
  }

  const inputHooks = (() => {
    const M = get('__BE3_INPUTHOOKS__');
    if (!M || !M.createInputHooks) return null;    return M.createInputHooks({
      getRunner: () => ui.runner,
      getPanel: () => ui.panel,
      repaint: () => paint(),

      focus: (sel, at) => {
        const doc = hostDoc();
        const box = doc && ui.panel ? ui.panel.querySelector(sel) : null;
        if (!box) return;
        try {
          box.focus();
          const len = asText(box.value).length;
          const n = (at === null || at === undefined) ? NaN : Number(at);
          const pos = Number.isFinite(n) ? Math.max(0, Math.min(len, Math.floor(n))) : len;
          box.setSelectionRange(pos, pos);
        } catch (e) {          }
      },
      onSend: () => sendChatDraft(),
    });
  })();

  function onPanelInput(ev) {
    if (inputHooks) inputHooks.handler(ev);
    wireWbView();
    const t = ev && ev.target;
    const kind = t && t.getAttribute ? t.getAttribute('data-be3-input') : null;

    if (kind === 'wb-search') { if (wb) wb.setView({ search: t.value == null ? '' : t.value }); return; }

    if (kind === 'hist-limit') { const hr = caps && caps.cfgHistInput(t.value); if (hr && hr.note) note(hr.note); return; }
    if (kind && kind.indexOf('cfg-preset-') === 0) {
      const r = caps ? caps.cfgInput({
        kind, index: t.getAttribute('data-be3-idx'), value: t.value, type: ev.type,
      }) : { handled: true, repaint: false, note: '宿主能力没装配起来' };
      if (r && r.repaint) paint(); else if (r && r.note) note(r.note);
    }    if (kind === 'cfg-wb-pick') {
      if (!wb) { note('⚠️ 世界书功能没装配起来（预览/harness 属正常）'); return; }
      const book = String(t.value == null ? '' : t.value).trim();
      const cur = wb.selection();
      if (!book || Object.prototype.hasOwnProperty.call((cur && cur.map) || {}, book)) { paint(); return; }
      const r = wb.apply({ type: 'follow', book });
      note(r && r.ok ? `✅ 已加入《${book}》（条目按线上启用状态跟随）` : `⚠️ 加不进去：${(r && r.reason) || '未知原因'}`);
      paint();
    }
    if (!kind || kind.indexOf('api-') !== 0) return;
    if (ev.type !== 'change') return;

    const r = caps ? caps.apiSetField(kind, Number(t.getAttribute('data-be3-api-index')), t.value)
      : { ok: false, reason: '宿主能力没装配起来' };

    if (r.ok) note('✅ API 配置已保存');
    else note(`⚠️ API 配置没保存：${r.reason || '未知原因'}`);
  }

  function onPanelKeyDown(ev) { if (inputHooks && inputHooks.keyHandler) inputHooks.keyHandler(ev); }

  const pointer = (() => {
    const M = get('__BE3_DRAG__');
    if (!M || !M.createPointerLayer) return { down() {}, move() {}, up() {}, fit: null };
    const w = hostWin();
    const raf = w && w.requestAnimationFrame ? w.requestAnimationFrame.bind(w) : (fn) => setTimeout(fn, 16);
    try {
      return M.createPointerLayer({
        doc: () => hostDoc(),
        getPanel: () => ui.panel,
        getRunner: () => ui.runner,
        getGeometry: () => get('__BE3_GEOMETRY__'),
        repaint: () => paint(),
        raf,
      });
    } catch (e) {
      if (typeof console !== 'undefined') console.warn('[BE3] 指针手势装配失败', e);
      return { down() {}, move() {}, up() {}, fit: null };
    }
  })();
  const canvasFit = pointer.fit;

  const snapCaret = () => { try { if (inputHooks && inputHooks.snapshotCaret) inputHooks.snapshotCaret(); } catch (e) {             } };
  function onPointerDown(ev) { snapCaret(); pointer.down(ev); }
  function onPointerUp(ev) { snapCaret(); pointer.up(ev); }
  function onPointerMove(ev) { pointer.move(ev); }

  function readMvuStatData() {
    const self = typeof window !== 'undefined' ? window : null;
    if (!self) return null;
    const pick = () => {
      let mvu = null;
      try { mvu = self.Mvu; } catch (e) {          }
      if (!mvu) { try { const p = hostWin(); mvu = p && p.Mvu; } catch (e) {          } }
      return mvu;
    };
    try {
      const mvu = pick();
      if (!mvu || typeof mvu.getMvuData !== 'function') return null;
      const a = (mvu.getMvuData({ type: 'message', message_id: 'latest' }) || {}).stat_data || null;
      const b = (mvu.getMvuData({ type: 'chat' }) || {}).stat_data || null;

      if (a && Object.keys(a).length) {
        return Object.assign({}, a, {
          系统配置: Object.assign({}, (b && b.系统配置) || {}, (a && a.系统配置) || {}),
        });
      }
      return b || null;
    } catch (e) {
      if (typeof console !== 'undefined') console.warn('[BE3] 读 MVU 失败', e);
    }
    return null;
  }

  const replySrc = (() => {
    const M = get('__BE3_REPLYSRC__');
    if (!M || !M.createReplySource) return null;

    return M.createReplySource({ getWindow: () => apiWin() });
  })();

  function readLatestAiText() { return replySrc ? replySrc.latest() : ''; }

  const panelHost = (() => {
    const M = get('__BE3_PANELHOST__');
    if (!M || !M.createPanelHost) return null;
    return M.createPanelHost({ doc: () => hostDoc(), styles: STYLES });
  })();

  const OWNER_ATTR = (panelHost && panelHost.OWNER_ATTR) || 'data-be3-owner';
  const STYLE_ID = (panelHost && panelHost.STYLE_ID) || 'be3-styles';

  function healStale() {
    if (!panelHost) return 0;
    const keep = ui.fab;
    const n = panelHost.sweepLeftovers({ keep });
    if (n) note(`已清理上次残留的 ${n} 处面板残骸`);
    return n;
  }

  function injectStyles() { return panelHost ? panelHost.injectStyles() : false; }

  function floatWin() {
    if (ui.floatWin) return ui.floatWin;
    const M = get('__BE3_FLOATWIN__');
    if (!M || !M.createFloatWindow) return null;
    const w = hostWin();
    const doc = hostDoc();
    ui.floatWin = M.createFloatWindow({
      doc,
      storage: (w && w.localStorage) || null,

      win: () => apiWin(),
      viewport: () => ({
        w: (w && w.innerWidth) || 1200,
        h: (w && w.innerHeight) || 800,
      }),
    });
    return ui.floatWin;
  }

  function mountFab() {
    const doc = hostDoc();
    if (!doc) return false;
    if (ui.fab && ui.fab.parentNode === doc.body) return true;
    const F = floatWin();
    if (!F) return false;
    const fab = F.createFab({ onClick: () => togglePanel() });
    if (!fab) return false;
    if (ui.fab && ui.fab.parentNode) { try { ui.fab.parentNode.removeChild(ui.fab); } catch (e) {          } }
    (doc.body || doc.documentElement).appendChild(fab);
    ui.fab = fab;
    return true;
  }

  function paintFallbackBox(el, why) {
    return panelHost ? panelHost.paintFallbackBox(el, why) : false;
  }

  function mount() {
    const doc = hostDoc();
    if (!doc) return false;

    if (ui.mounted && ui.panel && ui.panel.parentNode) {
      note('面板已在页面上，跳过重复挂载');
      paint();
      return true;
    }

    healStale();
    mountFab();

    injectStyles();
    bindPagehide();

    chatCtl(true);

    const RM = get('__BE3_RUNNER__');
    if (!ui.runner && RM && RM.createRunner) {
      try { ui.runner = RM.createRunner(); } catch (e) { note(`⚠️ runner 创建失败：${e && e.message ? e.message : e}`); }
    }

    const el = doc.createElement('div');
    el.className = 'be3-panel-host';
    el.setAttribute(OWNER_ATTR, 'panel');
    el.addEventListener('click', onPanelClick);
    el.addEventListener('input', onPanelInput);

    el.addEventListener('change', onPanelInput);

    el.addEventListener('keydown', onPanelKeyDown);
    el.addEventListener('pointerdown', onPointerDown);
    el.addEventListener('pointermove', onPointerMove);
    el.addEventListener('pointerup', onPointerUp);
    el.addEventListener('pointercancel', onPointerUp);

  (() => { const M = get('__BE3_PRESETDRAG__'); if (M && typeof M.attachPresetDragTo === 'function') M.attachPresetDragTo({ doc, getPanel: () => el, paint: () => paint(), run: (n, t) => explainFailure(n, (PARAM_ACTIONS[n] || (() => null))(t)) }); })();
    doc.body.appendChild(el);
    ui.panel = el;
    ui.mounted = true;

    try {
      if (ui.runner && ui.runner.snapshot && ui.runner.snapshot().rows.length === 0) {
        const stat = readMvuStatData();
        if (stat) {
          const r = ui.runner.importSave(stat);
          note(`启动时已从存档导入 ${r.rows} 个单位 / ${r.skills} 个技能`);
        } else {
          note('⚠️ 没读到 MVU 存档（面板会从空表开始）');
        }
      }
    } catch (e) {
      note(`⚠️ 导入失败：${e && e.message ? e.message : e}`);
    }

    paint();

    const F = floatWin();
    if (F && F.attach) {
      try { F.attach(el); } catch (e) {
        if (typeof console !== 'undefined') console.warn('[BE3] 悬浮窗接线失败', e);
      }
    }
    return true;
  }

  function unmount(opts) {
    const o = opts && typeof opts === 'object' ? opts : {};

    const w = hostWin();
    if (w && w.__BE3__) { try { delete w.__BE3__; } catch (e) { w.__BE3__ = null; } }

    if (ui.panel && ui.panel.parentNode) ui.panel.parentNode.removeChild(ui.panel);
    ui.panel = null;
    ui.mounted = false;

    if (pointer && pointer.drag && typeof pointer.drag.cancel === 'function') pointer.drag.cancel();
    if (inputHooks) inputHooks.cancel();
    if (replySrc) replySrc.forget();

    if (o.all === true) {
      if (ui.fab && ui.fab.parentNode) ui.fab.parentNode.removeChild(ui.fab);
      ui.fab = null;
      if (panelHost) panelHost.removeStyles();
      panelHost && panelHost.sweepLeftovers();
    }
    return true;
  }

  function submitReply(text) {
    if (!ui.runner) {
      const RM = get('__BE3_RUNNER__');
      if (!RM || typeof RM.createRunner !== 'function') {
        note('⚠️ 内核没装配起来（`__BE3_RUNNER__` 缺失）⇒ 回复无法落地');
        return { ok: false, reason: 'no_runner', applied: 0 };
      }
      try { ui.runner = RM.createRunner(); } catch (e) {
        note(`⚠️ runner 创建失败：${e && e.message ? e.message : e}`);
        return { ok: false, reason: 'no_runner', applied: 0 };
      }
    }
    const txt = replySrc ? replySrc.remember(text) : '';
    const r = ui.runner.submitReply(txt, { auto: true });
    paint();
    return r;
  }

  function forgetReply() { if (replySrc) replySrc.forget(); }

  function expose() {
    const w = hostWin();
    if (!w) return;
    const M = get('__BE3_DEBUGAPI__');
    if (!M || !M.createDebugApi) return;
    w.__BE3__ = M.createDebugApi({
      getRunner: () => ui.runner,
      paint: () => paint(),
      mount: () => mount(),
      unmount: () => unmount(),
      submitReply: (t) => submitReply(t),
      forgetReply: () => forgetReply(),
      getEngine: () => engine(),
      settleBattle: () => settleBattle(),
      settleText: () => (settleCtl ? settleCtl.getText() : ''),
      promptPreview: () => promptPreviewText(),

      diag: () => chatCtl(false),
      apiConfig: () => (caps ? caps.apiSnapshot() : {}),
      apiCaps: () => (caps ? caps.hostCaps().from : {}),
    });

    const TPH = get('__BE3_TPBHOST__'); if (TPH && TPH.createTestPackHost) TPH.createTestPackHost({ getRunner: () => ui.runner, win: hostWin, paint: () => paint(), setRunner: (r) => { ui.runner = r; }, makeRunner: () => get('__BE3_RUNNER__').createRunner() }).attach();
  }

  const hooks = (() => {
    const M = get('__BE3_HOOKS__');
    if (!M || !M.createWiredHooks) return null;
    return M.createWiredHooks({

      apiWin: () => apiWin(),
      findGlobal: (name) => findGlobalFn(name),
      scriptId: SCRIPT_ID,
      iframeName: selfIframeName(),
      buttonName: BUTTON_NAME,
      onButton: () => togglePanel(),
      onPageHide: () => unmount({ all: true }),
    });
  })();

  function togglePanel() {

    if (ui.mounted && ui.panel && ui.panel.parentNode) { unmount(); return false; }
    const ok = mount(); expose(); return ok;
  }

  function bindPagehide() { if (hooks) hooks.bindPagehide(); }

  function boot() {
    try {

      const doc = hostDoc();
      if (!doc) return;

      healStale(); injectStyles(); bindPagehide();
      if (!ui.runner) ui.runner = get('__BE3_RUNNER__').createRunner();

      const fabOk = mountFab();
      expose();
      if (typeof console !== 'undefined') {
        if (fabOk) console.log('[BE3] 悬浮球已就绪（点击开/关面板）。关闭面板：点面板右上角 ×');
        else console.warn('[BE3] ⚠️ 悬浮球没能挂上页面（宿主 document 取不到或被拒）');
      }
    } catch (e) {
      if (typeof console !== 'undefined') console.error('[BE3] 启动失败', e);
    }
  }

  let booted = false;
  function bootOnce() { if (booted) return; booted = true; boot(); }

  bootOnce();

  if (typeof window !== 'undefined') {
    window.__BE3_MOUNT__ = { mount, unmount, submitReply, forgetReply, toggle: togglePanel, bootOnce };
  }
  if (typeof module !== 'undefined' && module.exports) module.exports = { mount, unmount, submitReply, forgetReply, toggle: togglePanel, bootOnce };
})();

})();
